private final class StatusMenuCommandRouter: NSObject {
    weak var appController: AppController?

    @objc func clearHistory(_ sender: Any?) {
        appController?.performStatusMenuClearHistory(sender)
    }

    @objc func showSnippetEditor(_ sender: Any?) {
        appController?.performStatusMenuShowSnippetEditor(sender)
    }

    @objc func showPreferencePanel(_ sender: Any?) {
        appController?.performStatusMenuShowPreferencePanel(sender)
    }

    @objc(selectMenuItem:) func selectMenuItem(_ sender: Any?) {
        appController?.performMenuControllerSelectClip(sender)
    }

    @objc(selectSnippetMenuItem:) func selectSnippetMenuItem(_ sender: Any?) {
        appController?.performMenuControllerSelectSnippet(sender)
    }

    @objc(selectActionMenuItem:) func selectActionMenuItem(_ sender: Any?) {
        appController?.performMenuControllerSelectAction(sender)
    }
}

