@objc(CMLegacyArchivedClip)
private final class LegacyArchivedClip: NSObject, NSCoding {
    var types: [String] = []
    var createdDate = Date()
    var lastUsedDate = Date()
    var stringValue = ""
    var rtfData: Data?
    var pdfData: Data?
    var filenames: [String]?
    var urls: [String]?
    var imageData: Data?

    required init?(coder: NSCoder) {
        super.init()

        if let decodedTypes = legacyStringArray(from: coder.decodeObject(forKey: "types")) {
            types = decodedTypes.map(ClipItem.normalizedPasteboardType)
        }

        createdDate = coder.decodeObject(forKey: "createdDate") as? Date ?? Date()
        lastUsedDate = coder.decodeObject(forKey: "lastUsedDate") as? Date
            ?? coder.decodeObject(forKey: "lastAccessedDate") as? Date
            ?? createdDate
        stringValue = coder.decodeObject(forKey: "stringValue") as? String
            ?? coder.decodeObject(forKey: "NSStringPboardType") as? String
            ?? coder.decodeObject(forKey: NSPasteboard.PasteboardType.string.rawValue) as? String
            ?? ""
        rtfData = legacyData(
            from: coder,
            keys: [
                "RTFData",
                "RTFD",
                "RTF",
                "NSRTFDPboardType",
                "NSRTFPboardType",
                "NeXT RTFD pasteboard type",
                "NeXT Rich Text Format v1.0 pasteboard type",
                NSPasteboard.PasteboardType.rtfd.rawValue,
                NSPasteboard.PasteboardType.rtf.rawValue
            ]
        )
        pdfData = legacyData(
            from: coder,
            keys: [
                "PDF",
                "NSPDFPboardType",
                NSPasteboard.PasteboardType.pdf.rawValue
            ]
        )
        filenames = legacyStringArray(from: coder.decodeObject(forKey: "filenames"))
            ?? legacyStringArray(from: coder.decodeObject(forKey: "NSFilenamesPboardType"))
        urls = legacyStringArray(from: coder.decodeObject(forKey: "URL"))
            ?? legacyStringArray(from: coder.decodeObject(forKey: "NSURLPboardType"))
            ?? legacyStringArray(from: coder.decodeObject(forKey: "Apple URL pasteboard type"))

        if let image = coder.decodeObject(forKey: "image") as? NSImage {
            imageData = image.tiffRepresentation
        } else {
            imageData = legacyData(
                from: coder,
                keys: [
                    "TIFF",
                    "PICT",
                    "NSTIFFPboardType",
                    "NSPICTPboardType",
                    "NeXT TIFF v4.0 pasteboard type",
                    NSPasteboard.PasteboardType.tiff.rawValue,
                    NSPasteboard.PasteboardType.clipMenuPICT.rawValue
                ]
            )
        }
    }

    func encode(with coder: NSCoder) {}

    var clipItem: ClipItem {
        var inferredTypes = types
        if inferredTypes.isEmpty {
            if !stringValue.isEmpty {
                inferredTypes.append(NSPasteboard.PasteboardType.string.rawValue)
            }
            if rtfData != nil {
                inferredTypes.append(NSPasteboard.PasteboardType.rtf.rawValue)
            }
            if pdfData != nil {
                inferredTypes.append(NSPasteboard.PasteboardType.pdf.rawValue)
            }
            if filenames?.isEmpty == false {
                inferredTypes.append(NSPasteboard.PasteboardType.clipMenuFilenames.rawValue)
            }
            if urls?.isEmpty == false {
                inferredTypes.append(NSPasteboard.PasteboardType.clipMenuURL.rawValue)
            }
            if imageData != nil {
                inferredTypes.append(NSPasteboard.PasteboardType.tiff.rawValue)
            }
        }

        return ClipItem(
            types: inferredTypes,
            createdAt: createdDate,
            lastUsedAt: lastUsedDate,
            text: stringValue,
            rtfData: rtfData,
            pdfData: pdfData,
            filenames: filenames,
            urls: urls,
            imageData: imageData
        )
    }
}

@objc(Clip)
