private struct RuntimeActionNode: Decodable {
    var nodeTitle: String
    var action: [String: String]?
    var children: [RuntimeActionNode]

    private enum CodingKeys: String, CodingKey {
        case nodeTitle
        case isLeaf
        case children
        case action
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        nodeTitle = try container.decode(String.self, forKey: .nodeTitle)
        if let decodedAction = try container.decodeIfPresent([String: LossyActionString].self, forKey: .action) {
            action = normalizedActionDictionary(decodedAction.mapValues { $0.value })
        } else {
            action = nil
        }
        children = try container.decodeIfPresent([RuntimeActionNode].self, forKey: .children) ?? []
        if (try container.decodeIfPresent(Bool.self, forKey: .isLeaf)) == false {
            action = nil
        }
    }

    init(nodeTitle: String, action: [String: String]? = nil, children: [RuntimeActionNode] = []) {
        self.nodeTitle = nodeTitle
        self.action = action
        self.children = children
    }
}

private struct LossyActionString: Decodable {
    let value: String

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let string = try? container.decode(String.self) {
            value = string
        } else if let integer = try? container.decode(Int.self) {
            value = String(integer)
        } else if let bool = try? container.decode(Bool.self) {
            value = bool ? "1" : "0"
        } else if let double = try? container.decode(Double.self) {
            value = String(double)
        } else {
            value = ""
        }
    }
}

private func actionDictionary(from object: Any?) -> [String: String]? {
    if let action = object as? [String: String] {
        return normalizedActionDictionary(action)
    }
    guard let dictionary = object as? NSDictionary else { return nil }

    var result: [String: String] = [:]
    for (key, value) in dictionary {
        guard let key = key as? String else { continue }
        if let value = value as? String {
            result[key] = value
        } else if let value = value as? NSNumber {
            result[key] = value.stringValue
        } else {
            result[key] = "\(value)"
        }
    }
    return result.isEmpty ? nil : normalizedActionDictionary(result)
}

private func normalizedActionDictionary(_ action: [String: String]) -> [String: String] {
    var normalized = action
    if normalized["name"] == "removeAction" {
        normalized["name"] = "remove:"
    }
    if normalized["type"] == nil {
        if let path = normalized["path"], !path.isEmpty {
            normalized["type"] = "js"
        } else if normalized["name"]?.isEmpty == false {
            normalized["type"] = "builtin"
        }
    }
    return normalized
}

private func excludedAppDictionaries(from object: Any?) -> [[String: String]] {
    guard let array = object as? [Any] else { return [] }

    return array.compactMap { item in
        let dictionary: [String: Any]
        if let swiftDictionary = item as? [String: Any] {
            dictionary = swiftDictionary
        } else if let nsDictionary = item as? NSDictionary {
            var bridged: [String: Any] = [:]
            for (key, value) in nsDictionary {
                guard let key = key as? String else { continue }
                bridged[key] = value
            }
            dictionary = bridged
        } else {
            return nil
        }

        guard let bundleIdentifier = dictionary[kCMBundleIdentifierKey] as? String,
              !bundleIdentifier.isEmpty else {
            return nil
        }

        var result = [kCMBundleIdentifierKey: bundleIdentifier]
        if let name = dictionary[kCMNameKey] as? String, !name.isEmpty {
            result[kCMNameKey] = name
        }
        return result
    }
}

private func legacyStringArray(from object: Any?) -> [String]? {
    if let strings = object as? [String] {
        return strings
    }
    if let array = object as? NSArray {
        let strings = array.compactMap { element -> String? in
            if let string = element as? String {
                return string
            }
            if let value = element as? NSNumber {
                return value.stringValue
            }
            return nil
        }
        return strings.isEmpty ? nil : strings
    }
    if let string = object as? String {
        return [string]
    }
    return nil
}

private func legacyData(from coder: NSCoder, keys: [String]) -> Data? {
    for key in keys {
        if let data = coder.decodeObject(forKey: key) as? Data {
            return data
        }
        if let string = coder.decodeObject(forKey: key) as? String,
           let data = string.data(using: .utf8) {
            return data
        }
    }
    return nil
}

@objc(CMLegacyRuntimeArchivedActionNode)
private final class LegacyRuntimeArchivedActionNode: NSObject, NSCoding {
    var nodeTitle = ""
    var isLeaf = false
    var children: [LegacyRuntimeArchivedActionNode] = []
    var action: [String: String]?

    override init() {
        super.init()
    }

    required init?(coder: NSCoder) {
        nodeTitle = coder.decodeObject(forKey: "nodeTitle") as? String ?? ""
        isLeaf = (coder.decodeObject(forKey: "isLeaf") as? NSNumber)?.boolValue ?? false
        let decodedChildren = coder.decodeObject(forKey: "children")
        if let childNodes = decodedChildren as? [LegacyRuntimeArchivedActionNode] {
            children = childNodes
        } else if let childNodes = decodedChildren as? NSArray {
            children = childNodes.compactMap { $0 as? LegacyRuntimeArchivedActionNode }
        }
        action = actionDictionary(from: coder.decodeObject(forKey: "action"))
        super.init()
    }

    func encode(with coder: NSCoder) {
        coder.encode(nodeTitle, forKey: "nodeTitle")
        coder.encode(NSNumber(value: isLeaf), forKey: "isLeaf")
        coder.encode(children, forKey: "children")
        if let action {
            coder.encode(action as NSDictionary, forKey: "action")
        }
    }

    func runtimeActionNode() -> RuntimeActionNode {
        if isLeaf {
            return RuntimeActionNode(nodeTitle: nodeTitle, action: action)
        }

        return RuntimeActionNode(
            nodeTitle: nodeTitle,
            children: children
                .filter { $0 !== self }
                .map { $0.runtimeActionNode() }
        )
    }
}

