enum LoginItemManager {
    static func setEnabled(_ enabled: Bool) -> Bool {
#if DEBUG
        if debugSimulateLoginItemMutationFailure() {
            return false
        }
        if debugBypassLoginItemMutation() {
            return true
        }
#endif
        if #available(macOS 13.0, *) {
            do {
                if enabled {
                    if SMAppService.mainApp.status != .enabled {
                        try SMAppService.mainApp.register()
                    }
                    try removeLaunchAgentIfPresent()
                } else if SMAppService.mainApp.status == .enabled {
                    try SMAppService.mainApp.unregister()
                    try removeLaunchAgentIfPresent()
                } else {
                    try removeLaunchAgentIfPresent()
                }
                return true
            } catch {
                NSLog("ClipMenu failed to update login item: \(error.localizedDescription)")
                return false
            }
        }

        return setLaunchAgentEnabled(enabled)
    }

    static var supportsMainAppLoginItem: Bool {
        true
    }

    private static var launchAgentURL: URL? {
        FileManager.default.urls(for: .libraryDirectory, in: .userDomainMask).first?
            .appendingPathComponent("LaunchAgents", isDirectory: true)
            .appendingPathComponent("\(launchAgentLabel).plist")
    }

    private static var launchAgentLabel: String {
        let bundleIdentifier = Bundle.main.bundleIdentifier ?? "com.naotaka.ClipMenu"
        return "\(bundleIdentifier).login"
    }

    private static func setLaunchAgentEnabled(_ enabled: Bool) -> Bool {
        guard let url = launchAgentURL else { return false }

        do {
            if enabled {
                try FileManager.default.createDirectory(
                    at: url.deletingLastPathComponent(),
                    withIntermediateDirectories: true
                )
                let plist: [String: Any] = [
                    "Label": launchAgentLabel,
                    "ProgramArguments": ["/usr/bin/open", Bundle.main.bundlePath],
                    "RunAtLoad": true,
                    "LimitLoadToSessionType": "Aqua"
                ]
                let data = try PropertyListSerialization.data(
                    fromPropertyList: plist,
                    format: .xml,
                    options: 0
                )
                try data.write(to: url, options: .atomic)
            } else {
                try removeLaunchAgentIfPresent()
            }
            return true
        } catch {
            NSLog("ClipMenu failed to update LaunchAgent login item: \(error.localizedDescription)")
            return false
        }
    }

    private static func removeLaunchAgentIfPresent() throws {
        guard let url = launchAgentURL, FileManager.default.fileExists(atPath: url.path) else { return }
        try FileManager.default.removeItem(at: url)
    }
}

