        let acceptedPersistentDefaults: [String: Any] = [
            CMLegacyHasLaunchedBeforeKey: true,
            CMEnableAutomaticCheckKey: true,
            CMLegacyAutomaticChecksEnabledKey: true,
            CMLegacyAllowsAutomaticUpdatesKey: true,
