        func makeDeterministicClip(text: String, created: TimeInterval, lastUsed: TimeInterval) -> ClipItem {
            ClipItem(
                text: text,
                createdAt: Date(timeIntervalSinceReferenceDate: created),
                lastUsedAt: Date(timeIntervalSinceReferenceDate: lastUsed)
            )
        }

        defer {
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalSortOrder, forKey: CMPrefReorderClipsAfterPasting)
            restoreDefault(originalInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
