        ].forEach { clipsStore.add($0) }

        defaults.set(2, forKey: CMPrefReorderClipsAfterPasting)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let beforeSelectOrderedTexts = clipsStore.orderedClips.map(\.text)
        var afterSelectOrderedTexts = beforeSelectOrderedTexts
        var selectedText = ""
