            "normalizedStoredSortOrder": defaults.object(forKey: CMPrefReorderClipsAfterPasting) as Any,
            "normalizedSortOrderIsLastUsed": defaults.bool(forKey: CMPrefReorderClipsAfterPasting),
            "beforeSelectOrderedTexts": beforeSelectOrderedTexts,
            "expectedBeforeSelectOrderedTexts": expectedBeforeSelectOrderedTexts,
            "selectedText": selectedText,
            "afterSelectOrderedTexts": afterSelectOrderedTexts,
            "expectedAfterSelectOrderedTexts": expectedAfterSelectOrderedTexts,
            "state": actualState,
            "expectedState": expectedState,
            "selectionPromotedToTop": afterSelectOrderedTexts.first == selectedText,
            "matchesExpected": (actualState as NSDictionary).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

