    private func runDebugExcludedAppsCancelReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugExcludedAppsCancelReportPath")
            ?? "/tmp/clipmenu-excluded-apps-cancel-report.json")
        let originalExcludedAppsObject = defaults.object(forKey: CMPrefExcludeAppsKey)

        defer {
            if let originalExcludedAppsObject {
                defaults.set(originalExcludedAppsObject, forKey: CMPrefExcludeAppsKey)
            } else {
                defaults.removeObject(forKey: CMPrefExcludeAppsKey)
            }
            CMReloadRecordingPreferences()
            NSApp.terminate(nil)
        }

        defaults.set([[kCMBundleIdentifierKey: "com.example.persisted", kCMNameKey: "Persisted App"]], forKey: CMPrefExcludeAppsKey)
        CMReloadRecordingPreferences()
        let beforeStage = CMCurrentExcludedAppsDictionaries()

        CMStageExcludedAppForTesting(bundleIdentifier: "com.example.temporary", name: "Temporary App")
        let afterStage = CMCurrentExcludedAppsDictionaries()
        let persistedBeforeRevert = defaults.array(forKey: CMPrefExcludeAppsKey) as? [[String: String]] ?? []

        CMRevertExcludedApps()
        let afterRevert = CMCurrentExcludedAppsDictionaries()
        let persistedAfterRevert = defaults.array(forKey: CMPrefExcludeAppsKey) as? [[String: String]] ?? []
        let expectedPersistedApps = [[
            kCMBundleIdentifierKey: "com.example.persisted",
            kCMNameKey: "Persisted App"
        ]]
        let expectedStagedApps = [
            [kCMBundleIdentifierKey: "com.example.persisted", kCMNameKey: "Persisted App"],
            [kCMBundleIdentifierKey: "com.example.temporary", kCMNameKey: "Temporary App"]
        ]
        let actualState: [String: Any] = [
            "beforeStage": beforeStage,
            "afterStage": afterStage,
            "persistedBeforeRevert": persistedBeforeRevert,
            "afterRevert": afterRevert,
            "persistedAfterRevert": persistedAfterRevert
        ]
        let expectedState: [String: Any] = [
            "beforeStage": expectedPersistedApps,
            "afterStage": expectedStagedApps,
            "persistedBeforeRevert": expectedPersistedApps,
            "afterRevert": expectedPersistedApps,
            "persistedAfterRevert": expectedPersistedApps
        ]

        let report: [String: Any] = [
            "beforeStage": beforeStage,
            "afterStage": afterStage,
            "persistedBeforeRevert": persistedBeforeRevert,
            "afterRevert": afterRevert,
            "persistedAfterRevert": persistedAfterRevert,
            "state": actualState,
            "expectedState": expectedState,
            "cancelSemanticsPreserved": beforeStage.count == 1
                && afterStage.count == 2
                && persistedBeforeRevert.count == 1
                && afterRevert.count == 1
                && persistedAfterRevert.count == 1,
            "matchesExpected": (actualState as NSDictionary).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

