    private func topLevelActionNodeCount(at url: URL) -> Int {
        guard let data = try? Data(contentsOf: url),
              let plist = try? PropertyListSerialization.propertyList(from: data, format: nil),
              let nodes = plist as? [[String: Any]] else {
            return 0
        }
        return nodes.count
    }

    private func topLevelActionNodeTitles(at url: URL) -> [String] {
        guard let data = try? Data(contentsOf: url),
              let plist = try? PropertyListSerialization.propertyList(from: data, format: nil),
              let nodes = plist as? [[String: Any]] else {
            return []
        }
        return nodes.compactMap { $0["nodeTitle"] as? String }
    }

    private func committedActionNodeCount() -> Int {
        guard let data = CMCommittedActionNodesData(),
              let nodes = try? PropertyListDecoder().decode([RuntimeActionNode].self, from: data) else {
            return 0
        }
        return nodes.count
    }

    private func committedActionNodeTitles() -> [String] {
        guard let data = CMCommittedActionNodesData(),
              let nodes = try? PropertyListDecoder().decode([RuntimeActionNode].self, from: data) else {
            return []
        }
        return nodes.map(\.nodeTitle)
    }

    private func persistedLeafNodesContainChildrenKey(at url: URL) -> Bool {
        guard let data = try? Data(contentsOf: url),
              let plist = try? PropertyListSerialization.propertyList(from: data, format: nil),
              let nodes = plist as? [[String: Any]] else {
            return false
        }

        func leafContainsChildrenKey(in nodes: [[String: Any]]) -> Bool {
            for node in nodes {
                let isLeaf = (node["isLeaf"] as? NSNumber)?.boolValue
                    ?? (node["isLeaf"] as? Bool)
                    ?? (node["action"] != nil)
                if isLeaf, node.keys.contains("children") {
                    return true
                }
                if let children = node["children"] as? [[String: Any]],
                   leafContainsChildrenKey(in: children) {
                    return true
                }
            }
            return false
        }

        return leafContainsChildrenKey(in: nodes)
    }

    private func debugActionTreeRemovalSelectionReport(at actionsURL: URL) -> [String: Any] {
        func writeBaseline(_ data: Data) {
            try? data.write(to: actionsURL, options: .atomic)
            CMReloadActionPreferences()
        }

        writeBaseline(actionTreeRemovalSelectionBaselineData())
        let selectedFirstChild = CMSelectActionPreferenceNodeForTesting(path: "Folder/First Child")
        CMRemoveSelectedActionNodeForTesting()
        let removeFirstChildSelectionAfter = CMCurrentSelectedActionPreferencePath()

        writeBaseline(actionTreeSingleChildRemovalBaselineData())
        let selectedOnlyChild = CMSelectActionPreferenceNodeForTesting(path: "Folder/Only Child")
        CMRemoveSelectedActionNodeForTesting()
        let removeOnlyChildSelectionAfter = CMCurrentSelectedActionPreferencePath()

        return [
            "removeFirstChildSelectionAfter": removeFirstChildSelectionAfter as Any,
            "removeFirstChildSelectsNextSibling": selectedFirstChild && removeFirstChildSelectionAfter == "Folder/Second Child",
            "removeOnlyChildSelectionAfter": removeOnlyChildSelectionAfter as Any,
            "removeOnlyChildSelectsParent": selectedOnlyChild && removeOnlyChildSelectionAfter == "Folder"
        ]
    }

    private func debugActionTreeDragDropReport(at actionsURL: URL, reservedActionPath: String) -> [String: Any] {
        func writeBaseline() {
            try? actionTreeDragDropBaselineData().write(to: actionsURL, options: .atomic)
            CMReloadActionPreferences()
        }

        writeBaseline()
        let insertedAfterLeaf = CMInsertReservedActionForTesting(
            reservedPath: reservedActionPath,
            destinationParentPath: nil,
            insertionIndex: 2
        )
        let dropAfterLeafPaths = CMCurrentActionPreferencePaths()

        writeBaseline()
        let insertedIntoFolder = CMInsertReservedActionForTesting(
            reservedPath: reservedActionPath,
            destinationParentPath: "Folder",
            insertionIndex: 2
        )
        let dropIntoFolderPaths = CMCurrentActionPreferencePaths()

        writeBaseline()
        let movedAfterLeaf = CMMoveActionNodeForTesting(
            sourcePath: "Folder/First Child",
            destinationParentPath: nil,
            insertionIndex: 2
        )
        let moveAfterLeafPaths = CMCurrentActionPreferencePaths()

        return [
            "dropAfterLeafPaths": dropAfterLeafPaths,
            "dropAfterLeafMatchesExpected": insertedAfterLeaf && dropAfterLeafPaths == [
                "Folder",
                "Folder/First Child",
                "Folder/Second Child",
                "Tail Action",
                reservedActionPath
            ],
            "dropIntoFolderPaths": dropIntoFolderPaths,
            "dropIntoFolderMatchesExpected": insertedIntoFolder && dropIntoFolderPaths == [
                "Folder",
                "Folder/First Child",
                "Folder/Second Child",
                "Folder/\(reservedActionPath)",
                "Tail Action"
            ],
            "moveAfterLeafPaths": moveAfterLeafPaths,
            "moveAfterLeafMatchesExpected": movedAfterLeaf && moveAfterLeafPaths == [
                "Folder",
                "Folder/Second Child",
                "Tail Action",
                "First Child"
            ]
        ]
    }

    private func debugActionInspectorReport(
        at actionsURL: URL,
        reservedActionPath: String,
        localizedBuiltInTypeTitle: String,
        flushMainRunLoop: () -> Void
    ) -> [String: Any] {
        func writeBaseline(_ data: Data) {
            try? data.write(to: actionsURL, options: .atomic)
            CMReloadActionPreferences()
            flushMainRunLoop()
        }

        writeBaseline(actionTreeRemovalSelectionBaselineData())
        let selectedReserved = CMSelectReservedActionPreferenceNodeForTesting(path: reservedActionPath)
        flushMainRunLoop()
        let reservedSnapshot = CMCurrentActionInspectorSnapshotForTesting()

        let selectedAction = CMSelectActionPreferenceNodeForTesting(path: "Folder/First Child")
        flushMainRunLoop()
        let actionSnapshot = CMCurrentActionInspectorSnapshotForTesting()

        return [
            "reservedInspectorPane": reservedSnapshot?["pane"] ?? NSNull(),
            "reservedInspectorName": reservedSnapshot?["name"] ?? NSNull(),
            "reservedInspectorType": reservedSnapshot?["type"] ?? NSNull(),
            "reservedInspectorIsEditable": reservedSnapshot?["isEditable"] ?? NSNull(),
            "reservedInspectorMatchesExpected": selectedReserved
                && (reservedSnapshot?["pane"] as? String) == "reserved"
                && (reservedSnapshot?["name"] as? String) == reservedActionPath
                && (reservedSnapshot?["type"] as? String) == localizedBuiltInTypeTitle
                && (reservedSnapshot?["isEditable"] as? Bool) == false,
            "actionInspectorPane": actionSnapshot?["pane"] ?? NSNull(),
            "actionInspectorName": actionSnapshot?["name"] ?? NSNull(),
            "actionInspectorType": actionSnapshot?["type"] ?? NSNull(),
            "actionInspectorIsEditable": actionSnapshot?["isEditable"] ?? NSNull(),
            "actionInspectorMatchesExpected": selectedAction
                && (actionSnapshot?["pane"] as? String) == "action"
                && (actionSnapshot?["name"] as? String) == "First Child"
                && (actionSnapshot?["type"] as? String) == localizedBuiltInTypeTitle
                && (actionSnapshot?["isEditable"] as? Bool) == true
        ]
    }

    private func debugActionTreeAddButtonReport(
        at actionsURL: URL,
        reservedActionPath: String,
        flushMainRunLoop: () -> Void
    ) -> [String: Any] {
        func writeBaseline(_ data: Data) {
            try? data.write(to: actionsURL, options: .atomic)
            CMReloadActionPreferences()
            flushMainRunLoop()
        }

        writeBaseline(actionTreeRemovalSelectionBaselineData())
        let selectedAction = CMSelectActionPreferenceNodeForTesting(path: "Folder/First Child")
        let selectedReserved = CMSelectReservedActionPreferenceNodeForTesting(path: reservedActionPath)
        CMAddSelectedReservedActionForTesting()
        flushMainRunLoop()
        let paths = CMCurrentActionPreferencePaths()

        return [
            "addSelectedReservedActionPaths": paths,
            "addSelectedReservedActionMatchesExpected": selectedAction
                && selectedReserved
                && paths == [
                    "Folder",
                    "Folder/First Child",
                    "Folder/Second Child",
                    "Tail Action",
                    reservedActionPath
                ]
        ]
    }

    private func debugActionNameValidationReport(
        at actionsURL: URL,
        flushMainRunLoop: () -> Void
    ) -> [String: Any] {
        func writeBaseline(_ data: Data) {
            try? data.write(to: actionsURL, options: .atomic)
            CMReloadActionPreferences()
            flushMainRunLoop()
        }

        writeBaseline(actionTreeRemovalSelectionBaselineData())
        let selectedAction = CMSelectActionPreferenceNodeForTesting(path: "Folder/First Child")
        flushMainRunLoop()
        let editReport = CMTestActionInspectorNameEditForTesting("")
        let before = (editReport?["before"] as? [String: Any])?["name"] as? String
        let after = (editReport?["after"] as? [String: Any])?["name"] as? String
        let commitSucceeded = editReport?["commitSucceeded"] as? Bool

        return [
            "emptyActionNameBefore": before ?? NSNull(),
            "emptyActionNameAfter": after ?? NSNull(),
            "emptyActionNameCommitRejected": (commitSucceeded == false),
            "emptyActionNameMatchesExpected": selectedAction
                && before == "First Child"
                && after == "First Child"
                && commitSucceeded == false
        ]
