    private func debugActionOutlineInteractionReport(
        at actionsURL: URL,
        flushMainRunLoop: () -> Void
    ) -> [String: Any] {
        func writeBaseline(_ data: Data) {
            try? data.write(to: actionsURL, options: .atomic)
            CMReloadActionPreferences()
            ActionTreePresentationState.shared.resetForTesting()
            flushMainRunLoop()
        }

        writeBaseline(actionTreeRemovalSelectionBaselineData())
        CMSetExpandedActionPreferencePathsForTesting([])
        flushMainRunLoop()

        let selectedCollapsedFolder = CMSelectActionPreferenceNodeForTesting(path: "Folder")
        flushMainRunLoop()
        let collapsedFolderPathsAfterRowSelection = CMCurrentExpandedActionPreferencePaths()

        let selectedTailAction = CMSelectActionPreferenceNodeForTesting(path: "Tail Action")
        let toggledFolderExpansion = CMToggleExpandedActionPreferencePathForTesting(path: "Folder")
        flushMainRunLoop()
        let expandedFolderPathsAfterChevron = CMCurrentExpandedActionPreferencePaths()
        let selectionAfterChevronToggle = CMCurrentSelectedActionPreferencePath()

        let selectedExpandedFolder = CMSelectActionPreferenceNodeForTesting(path: "Folder")
        flushMainRunLoop()
        let expandedFolderPathsAfterExpandedRowSelection = CMCurrentExpandedActionPreferencePaths()

        return [
            "collapsedFolderPathsAfterRowSelection": collapsedFolderPathsAfterRowSelection,
            "rowSelectionKeepsFolderCollapsed": selectedCollapsedFolder
                && collapsedFolderPathsAfterRowSelection.isEmpty,
            "expandedFolderPathsAfterChevron": expandedFolderPathsAfterChevron,
            "chevronToggleExpandsFolder": toggledFolderExpansion
                && expandedFolderPathsAfterChevron == ["Folder"],
            "selectionAfterChevronToggle": selectionAfterChevronToggle as Any,
            "chevronTogglePreservesSelection": selectedTailAction
                && selectionAfterChevronToggle == "Tail Action",
            "expandedFolderPathsAfterExpandedRowSelection": expandedFolderPathsAfterExpandedRowSelection,
            "rowSelectionKeepsExpandedFolderOpen": selectedExpandedFolder
                && expandedFolderPathsAfterExpandedRowSelection == ["Folder"]
        ]
    }

    private func runDebugLoginItemSyncReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugStringValue(forKey: "debugLoginItemSyncReportPath")
            ?? "/tmp/clipmenu-login-item-sync-report.json")
        let requestedLoginItemState = debugBoolArgumentValue(forKey: "debugRequestedLoginItemState") ?? true
        let beforeLoginItem = defaults.bool(forKey: CMPrefLoginItemKey)
        let beforeSuppressed = defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)

        defaults.set(requestedLoginItemState, forKey: CMPrefLoginItemKey)
        lastRequestedLoginItemState = nil
        syncLoginItemState()
        let afterLoginItem = defaults.bool(forKey: CMPrefLoginItemKey)
        let afterSuppressed = defaults.bool(forKey: CMPrefSuppressAlertForLoginItemKey)
        let simulatedMutationFailure = debugSimulateLoginItemMutationFailure()
        let loginItemMutationBypassed = debugBypassLoginItemMutation()
        let expectedLastRequestedState: Bool = {
            if simulatedMutationFailure && requestedLoginItemState {
                return false
            }
            return requestedLoginItemState
        }()
        let expectedStoredLoginItem: Bool = {
            if simulatedMutationFailure && requestedLoginItemState {
                return false
            }
            return requestedLoginItemState
        }()
        let actualState: [String: Any] = [
            "before": [
                "loginItem": beforeLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "requestedLoginItemState": requestedLoginItemState,
            "simulatedMutationFailure": simulatedMutationFailure,
            "loginItemMutationBypassed": loginItemMutationBypassed,
            "after": [
                "loginItem": afterLoginItem,
                "suppressAlertForLoginItem": afterSuppressed
            ],
            "lastRequestedLoginItemState": lastRequestedLoginItemState as Any
        ]
        let expectedState: [String: Any] = [
            "before": [
                "loginItem": beforeLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "requestedLoginItemState": requestedLoginItemState,
            "simulatedMutationFailure": simulatedMutationFailure,
            "loginItemMutationBypassed": loginItemMutationBypassed,
            "after": [
                "loginItem": expectedStoredLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "lastRequestedLoginItemState": expectedLastRequestedState
        ]
        let matchesExpected = (actualState as NSDictionary).isEqual(to: expectedState)

        let report: [String: Any] = [
            "before": [
                "loginItem": beforeLoginItem,
                "suppressAlertForLoginItem": beforeSuppressed
            ],
            "requestedLoginItemState": requestedLoginItemState,
            "simulatedMutationFailure": simulatedMutationFailure,
            "loginItemMutationBypassed": loginItemMutationBypassed,
            "after": [
                "loginItem": afterLoginItem,
                "suppressAlertForLoginItem": afterSuppressed
            ],
            "lastRequestedLoginItemState": lastRequestedLoginItemState as Any,
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        NSApp.terminate(nil)
    }

