                let expectedIconSizeBadge = CMTypeIconSizeBadgeTitle(
                    size: CMNormalizedTypeLegacyMenuIconSize(UserDefaults.standard.object(forKey: CMPrefMenuIconSizeKey) as? Int ?? 16),
                    pixelLabel: NSLocalizedString("pixel", comment: "")
