                    && modifierRows.map { $0["title"] as? String ?? "" } == [
                        NSLocalizedString("1190.title", tableName: "Preferences", bundle: .main, value: "Control + Click:", comment: ""),
                        NSLocalizedString("1209.title", tableName: "Preferences", bundle: .main, value: "Shift + Click:", comment: ""),
                        NSLocalizedString("1215.title", tableName: "Preferences", bundle: .main, value: "Option + Click:", comment: ""),
                        NSLocalizedString("1221.title", tableName: "Preferences", bundle: .main, value: "Command + Click:", comment: "")
                    ]
                    && availableActionsSummary == expectedAvailableActionsSummary
                    && sourceTitles == expectedAvailableActionSourceTitles
                    && (emptyStates as NSDictionary).isEqual(to: expectedAvailableActionEmptyStates)
                    && emptyStates.keys.sorted() == ["builtin", "bundled", "user"]
                    && Set(toolbarButtonsEnabled.keys) == Set(["add", "addFolder", "remove", "moveUp", "moveDown"])
                    && toolbarButtonIconSources == expectedToolbarButtonIconSources

                report = [
                    "title": window.title,
                    "toolbarStyle": self.debugToolbarStyleName(window.toolbarStyle),
                    "isVisible": window.isVisible,
                    "selectedPaneTitle": selectedPaneTitle as Any,
                    "paneSnapshot": paneSnapshot,
                    "matchesExpected": matchesExpected
                ]
            } else {
                report["error"] = "Preferences window not available"
                report["matchesExpected"] = false
            }

            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }

            NSApp.terminate(nil)
        }
    }

