    private func debugCurrentShortcutDisplays() -> (clip: String, snippets: String, history: String) {
        let defaults = UserDefaults.standard
        let clipEnabled = defaults.object(forKey: CMPrefHotKeyEnabledKey) as? Bool ?? true
        let clipKeyCode = clipEnabled ? defaults.object(forKey: CMPrefHotKeyKeyCodeKey) as? Int ?? 9 : -1
        let clipModifierFlags = clipEnabled
            ? defaults.object(forKey: CMPrefHotKeyModifierFlagsKey) as? Int
                ?? Int(NSEvent.ModifierFlags([.command, .shift]).rawValue)
            : 0

        let snippetsEnabled = defaults.object(forKey: CMPrefSnippetsHotKeyEnabledKey) as? Bool ?? true
        let snippetsKeyCode = snippetsEnabled ? defaults.object(forKey: CMPrefSnippetsHotKeyKeyCodeKey) as? Int ?? 11 : -1
        let snippetsModifierFlags = snippetsEnabled
            ? defaults.object(forKey: CMPrefSnippetsHotKeyModifierFlagsKey) as? Int
                ?? Int(NSEvent.ModifierFlags([.command, .shift]).rawValue)
            : 0

        let historyModifierFlags = Int(NSEvent.ModifierFlags([.command, .control]).rawValue)

        return (
            clip: CMHotKeyDisplayStringForDebug(keyCode: clipKeyCode, modifierFlags: clipModifierFlags),
            snippets: CMHotKeyDisplayStringForDebug(keyCode: snippetsKeyCode, modifierFlags: snippetsModifierFlags),
            history: CMHotKeyDisplayStringForDebug(keyCode: 9, modifierFlags: historyModifierFlags)
        )
    }

    private func debugVisibleTextValues(in rootView: NSView?, window: NSWindow? = nil) -> [String] {
        guard rootView != nil || window?.contentView != nil else { return [] }

        var values: [String] = []
        var visitedObjects = Set<ObjectIdentifier>()

        func append(_ candidate: String?) {
            guard let candidate else { return }
            let trimmed = candidate.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else { return }
            values.append(trimmed)
        }

        func collect(from object: NSObject) {
            let identifier = ObjectIdentifier(object)
            guard visitedObjects.insert(identifier).inserted else { return }

            if let view = object as? NSView, view.isHidden {
                return
            }

            if let textField = object as? NSTextField {
                append(textField.stringValue)
            }

            if let button = object as? NSButton {
                append(button.title)
            }

            if let segmentedControl = object as? NSSegmentedControl {
                for segment in 0..<segmentedControl.segmentCount {
                    append(segmentedControl.label(forSegment: segment))
                }
            }

            if let control = object as? NSControl {
                append(control.stringValue)
            }

            if let window = object as? NSWindow {
                append(window.title)
            }

            if let view = object as? NSView {
                append(view.accessibilityLabel())
                append(view.accessibilityTitle())
                append(view.accessibilityValue() as? String)

                for subview in view.subviews {
                    collect(from: subview)
                }
            }
        }

        if let window {
            collect(from: window)
        } else if let rootView {
            collect(from: rootView)
        }
        return Array(NSOrderedSet(array: values)) as? [String] ?? values
    }

    private func debugPreferencesWindowTitleVisibilityName(_ visibility: NSWindow.TitleVisibility) -> String {
        switch visibility {
        case .visible:
            return "visible"
        case .hidden:
            return "hidden"
        @unknown default:
            return "unknown"
        }
    }

    private func debugToolbarStyleName(_ style: NSWindow.ToolbarStyle) -> String {
        switch style {
        case .automatic:
            return "automatic"
        case .expanded:
            return "expanded"
        case .preference:
            return "preference"
        case .unified:
            return "unified"
        case .unifiedCompact:
            return "unifiedCompact"
        @unknown default:
            return "unknown"
        }
    }

    private func debugWindowStyleMaskNames(_ styleMask: NSWindow.StyleMask) -> [String] {
        let knownMasks: [(NSWindow.StyleMask, String)] = [
            (.titled, "titled"),
            (.closable, "closable"),
            (.miniaturizable, "miniaturizable"),
            (.resizable, "resizable"),
            (.fullSizeContentView, "fullSizeContentView"),
            (.unifiedTitleAndToolbar, "unifiedTitleAndToolbar"),
            (.hudWindow, "hudWindow"),
            (.utilityWindow, "utilityWindow"),
            (.docModalWindow, "docModalWindow"),
            (.nonactivatingPanel, "nonactivatingPanel")
        ]

        return knownMasks.compactMap { mask, name in
            styleMask.contains(mask) ? name : nil
        }
    }

