    private func applyDebugSnippetEditorSelectionModeIfNeeded(_ mode: String?) -> Bool {
        guard let mode, !mode.isEmpty else { return true }

        let store = SnippetFileStore.shared
        switch mode {
        case "populated":
            let seed = populateSnippetStoreForDebugWorkflowSeed(persistReset: true, persistSeededState: true)
            store.selectedFolderIDs = [seed.qaFolderID]
            store.notePrimaryFolder(seed.qaFolderID)
            if let greetingSnippetID = seed.greetingSnippetID {
                store.selectedSnippetIDs = [greetingSnippetID]
                store.notePrimarySnippet(greetingSnippetID)
            } else {
                store.selectedSnippetIDs = []
            }
            return true

        case "searchFixture":
            let qaFolderID = store.addFolder()
            guard let qaIndex = store.folders.firstIndex(where: { $0.id == qaFolderID }) else {
                return false
            }

            var qaFolder = store.folders[qaIndex]
            qaFolder.title = "QA"
            store.updateFolder(id: qaFolderID, to: qaFolder)

            store.selectedFolderIDs = [qaFolderID]
            store.notePrimaryFolder(qaFolderID)

            let snippetFixtures: [(title: String, content: String)] = [
                ("Greeting", "Hello from snippet"),
                ("Bug Bash", "Needs follow-up"),
                ("Archive", "Greeting appears in content only")
            ]

            var primarySnippetID: UUID?
            for fixture in snippetFixtures {
                guard let snippetID = store.addSnippet(),
                      let folderIndex = store.folders.firstIndex(where: { $0.id == qaFolderID }),
                      let snippetIndex = store.folders[folderIndex].snippets.firstIndex(where: { $0.id == snippetID }) else {
                    return false
                }
                var snippet = store.folders[folderIndex].snippets[snippetIndex]
                snippet.title = fixture.title
                snippet.content = fixture.content
                store.updateSnippet(folderID: qaFolderID, snippetID: snippetID, to: snippet)
                if primarySnippetID == nil {
                    primarySnippetID = snippetID
                }
            }

            store.save()
            store.reload()
            store.selectedFolderIDs = [qaFolderID]
            store.notePrimaryFolder(qaFolderID)
            if let primarySnippetID {
                store.selectedSnippetIDs = [primarySnippetID]
                store.notePrimarySnippet(primarySnippetID)
            } else {
                store.selectedSnippetIDs = []
            }
            return true

        case "noFolder":
            store.selectedFolderIDs = []
            store.selectedSnippetIDs = []
            return true

        case "noSnippets":
            if let emptyFolder = store.folders.first(where: { $0.snippets.isEmpty }) {
                store.notePrimaryFolder(emptyFolder.id)
                store.selectedFolderIDs = [emptyFolder.id]
                store.selectedSnippetIDs = []
                return true
            }

            guard let folderIndex = store.selectedFolderIndex,
                  store.folders.indices.contains(folderIndex) else {
                return false
            }

            let folderID = store.folders[folderIndex].id
            let snippetIDs = store.folders[folderIndex].snippets.map(\.id)
            guard !snippetIDs.isEmpty else {
                store.notePrimaryFolder(folderID)
                store.selectedFolderIDs = [folderID]
                store.selectedSnippetIDs = []
                return true
            }

            store.selectedFolderIDs = [folderID]
            store.notePrimaryFolder(folderID)
            store.selectedSnippetIDs = Set(snippetIDs)
            if let primarySnippetID = snippetIDs.first {
                store.notePrimarySnippet(primarySnippetID)
            }
            store.removeSelectedSnippet()
            store.save()
            store.selectedFolderIDs = [folderID]
            store.notePrimaryFolder(folderID)
            store.selectedSnippetIDs = []
            return store.folders.first(where: { $0.id == folderID })?.snippets.isEmpty == true

        case "multipleFolders":
            if store.folders.count < 2 {
                _ = populateSnippetStoreForDebugWorkflowSeed(
                    persistReset: true,
                    persistSeededState: true
                )
            }
            guard store.folders.count >= 2 else { return false }
            let firstFolderID = store.folders[0].id
            let secondFolderID = store.folders[1].id
            store.notePrimaryFolder(firstFolderID)
            store.selectedFolderIDs = [firstFolderID, secondFolderID]
            store.selectedSnippetIDs = []
            return true

        case "multipleSnippets":
            if store.selectedFolderIndex == nil || store.folders.isEmpty {
                let seed = populateSnippetStoreForDebugWorkflowSeed(
                    persistReset: true,
                    persistSeededState: true
                )
                store.selectedFolderIDs = [seed.qaFolderID]
                store.notePrimaryFolder(seed.qaFolderID)
                if let greetingSnippetID = seed.greetingSnippetID {
                    store.selectedSnippetIDs = [greetingSnippetID]
                    store.notePrimarySnippet(greetingSnippetID)
                }
            }
            guard let folderIndex = store.selectedFolderIndex,
                  store.folders.indices.contains(folderIndex) else {
                return false
            }

            let folderID = store.folders[folderIndex].id
            var createdSyntheticSnippet = false
            while store.folders[folderIndex].snippets.count < 2 {
                guard let snippetID = store.addSnippet(),
                      let refreshedFolderIndex = store.folders.firstIndex(where: { $0.id == folderID }),
                      let snippetIndex = store.folders[refreshedFolderIndex].snippets.firstIndex(where: { $0.id == snippetID }) else {
                    return false
                }
                var snippet = store.folders[refreshedFolderIndex].snippets[snippetIndex]
                snippet.title = "Follow Up"
                snippet.content = "Needs follow-up"
                store.updateSnippet(folderID: folderID, snippetID: snippetID, to: snippet)
                createdSyntheticSnippet = true
            }

            if createdSyntheticSnippet {
                store.save()
            }

            guard let refreshedFolderIndex = store.folders.firstIndex(where: { $0.id == folderID }) else {
                return false
            }
            let snippetIDs = Array(store.folders[refreshedFolderIndex].snippets.prefix(2).map(\.id))
            guard let primarySnippetID = snippetIDs.first else { return false }
            store.notePrimaryFolder(folderID)
            store.selectedFolderIDs = [folderID]
            store.notePrimarySnippet(primarySnippetID)
            store.selectedSnippetIDs = Set(snippetIDs)
            return store.selectedSnippetIDs.count == 2

        default:
            return false
        }
    }

