                let expectedFooterButtonIconSources: [String: String] = [:]
                let snippetStore = SnippetFileStore.shared
                let expectedSnippetActionsMenuStates = [
                    NSLocalizedString("Import Snippets...", comment: ""): true,
                    NSLocalizedString("Export Snippets...", comment: ""): !snippetStore.folders.isEmpty
                ]
                let expectedFolderActionBarStates = [
                    NSLocalizedString("Add Folder", comment: ""): true,
                    NSLocalizedString("Delete Folder", comment: ""): !snippetStore.selectedFolderIDs.isEmpty,
                    NSLocalizedString("Enable/Disable Folder", comment: ""): !snippetStore.selectedFolderIDs.isEmpty,
                    NSLocalizedString("Snippet Actions", comment: ""): true
                ]
                let expectedToolbarItemStates = [
                    NSLocalizedString("Add Snippet", comment: ""): !snippetStore.selectedFolderIDs.isEmpty,
                    NSLocalizedString("Delete Snippet", comment: ""): true,
                    NSLocalizedString("Enable/Disable Snippet", comment: ""): !snippetStore.selectedSnippetIDs.isEmpty
                ]
                let selectedFolder = snippetStore.selectedFolderIndex.flatMap {
                    snippetStore.folders.indices.contains($0) ? snippetStore.folders[$0] : nil
                }
                let selectedSnippet: Snippet? = {
                    guard let folderIndex = snippetStore.selectedFolderIndex,
                          snippetStore.folders.indices.contains(folderIndex),
                          let snippetIndex = snippetStore.selectedSnippetIndex,
                          snippetStore.folders[folderIndex].snippets.indices.contains(snippetIndex) else {
                        return nil
                    }
                    return snippetStore.folders[folderIndex].snippets[snippetIndex]
                }()
                let effectiveSelectedSnippet: Snippet? = {
                    guard snippetStore.selectedFolderIDs.count == 1,
                          snippetStore.selectedSnippetIDs.count == 1 else {
                        return nil
                    }
                    return selectedSnippet
                }()
                let visibleSnippetCount: Int = {
                    guard let folderIndex = snippetStore.selectedFolderIndex,
                          snippetStore.folders.indices.contains(folderIndex) else {
                        return 0
                    }
                    let normalizedScopeRawValue = self.snippetSearchScope(rawValue: requestedSearchScopeRawValue ?? "all")
                    let trimmedQuery = requestedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
                    let snippets = Array(snippetStore.folders[folderIndex].snippets.enumerated())
                    guard normalizedScopeRawValue != "all" || !trimmedQuery.isEmpty else {
                        return snippets.count
                    }
                    if trimmedQuery.isEmpty {
                        return snippets.count
                    }
                    return snippets.filter { entry in
                        switch normalizedScopeRawValue {
                        case "title":
                            return entry.element.title.localizedCaseInsensitiveContains(trimmedQuery)
                        case "content":
                            return entry.element.content.localizedCaseInsensitiveContains(trimmedQuery)
                        default:
                            return String(entry.offset).localizedCaseInsensitiveContains(trimmedQuery)
                                || entry.element.title.localizedCaseInsensitiveContains(trimmedQuery)
                                || entry.element.content.localizedCaseInsensitiveContains(trimmedQuery)
                        }
                    }.count
                }()
                let expectedBrowserTextAppearance: [String: [String: Any]] = {
                    var appearance: [String: [String: Any]] = [:]
                    if !snippetStore.folders.isEmpty {
                        appearance["folderOutline"] = [
                            "fontName": "LucidaGrande",
                            "fontSize": 13
                        ]
                    }
                    if visibleSnippetCount > 0 {
                        appearance["snippetTable"] = [
                            "fontName": "LucidaGrande",
                            "fontSize": 13
                        ]
                    }
                    return appearance
                }()
                let expectedSearchScopeRawValue = requestedSearchScopeRawValue ?? "all"
                let expectedSearchScopeTitle = self.localizedSnippetSearchScopeTitle(for: expectedSearchScopeRawValue)
                let expectedSnippetListState: [String: String] = {
                    if snippetStore.selectedFolderIDs.count > 1 {
                        return [
                            "mode": "multipleFolders",
                            "systemImage": "checklist",
                            "title": NSLocalizedString("Multiple Folders Selected", comment: ""),
                            "message": NSLocalizedString("Choose a single folder to browse its snippets.", comment: "")
                        ]
                    }
                    if snippetStore.selectedFolderIndex == nil {
                        return [
                            "mode": "noFolder",
                            "systemImage": "sidebar.left",
                            "title": NSLocalizedString("Choose a Folder", comment: ""),
                            "message": NSLocalizedString("Select a folder to browse its snippets.", comment: "")
                        ]
                    }
                    if visibleSnippetCount == 0 {
                        let trimmedQuery = requestedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
                        return [
                            "mode": trimmedQuery.isEmpty ? "noSnippets" : "noMatches",
                            "systemImage": trimmedQuery.isEmpty ? "doc.text" : "magnifyingglass",
                            "title": trimmedQuery.isEmpty ? NSLocalizedString("No Snippets", comment: "") : NSLocalizedString("No Matches", comment: ""),
                            "message": trimmedQuery.isEmpty
                                ? NSLocalizedString("Add a snippet to the selected folder.", comment: "")
                                : NSLocalizedString("Try a different search term.", comment: "")
                        ]
                    }
                    return [
                        "mode": "results",
                        "systemImage": "list.bullet",
                        "title": CMModernLocalizationIsJapanese()
                            ? "\(visibleSnippetCount)件を表示"
                            : (visibleSnippetCount == 1 ? "1 visible" : "\(visibleSnippetCount) visible"),
                            "message": {
                            if let snippetTitle = effectiveSelectedSnippet?.title {
                                return snippetTitle
                            }
                            if let folderTitle = selectedFolder?.title {
                                return folderTitle
                            }
                            return CMLocalizedModernString("No folder selected", japanese: "フォルダ未選択")
                        }()
                    ]
                }()
                let expectedVisibleSnippetTitles: [String] = {
                    guard let folderIndex = snippetStore.selectedFolderIndex,
                          snippetStore.folders.indices.contains(folderIndex) else {
                        return []
                    }
                    let normalizedScopeRawValue = self.snippetSearchScope(rawValue: requestedSearchScopeRawValue ?? "all")
                    let trimmedQuery = requestedSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
                    let snippets = Array(snippetStore.folders[folderIndex].snippets.enumerated())
                    let filtered: [Snippet]
                    if trimmedQuery.isEmpty {
                        filtered = snippets.map(\.element)
                    } else {
                        filtered = snippets.compactMap { entry in
                            let matches: Bool
                            switch normalizedScopeRawValue {
                            case "title":
                                matches = entry.element.title.localizedCaseInsensitiveContains(trimmedQuery)
                            case "content":
                                matches = entry.element.content.localizedCaseInsensitiveContains(trimmedQuery)
                            default:
                                matches = String(entry.offset).localizedCaseInsensitiveContains(trimmedQuery)
                                    || entry.element.title.localizedCaseInsensitiveContains(trimmedQuery)
                                    || entry.element.content.localizedCaseInsensitiveContains(trimmedQuery)
                            }
                            return matches ? entry.element : nil
                        }
                    }
                    return filtered.map(\.title)
                }()
                let expectedDetailPaneState: [String: String] = {
                    if snippetStore.selectedFolderIDs.count > 1 {
                        return [
                            "mode": "multipleFolders",
                            "systemImage": "checklist",
                            "title": NSLocalizedString("Multiple Folders Selected", comment: ""),
                            "message": NSLocalizedString("Choose a single folder to browse its snippets.", comment: "")
                        ]
                    }
                    if snippetStore.selectedSnippetIDs.count > 1 {
                        return [
                            "mode": "multipleSnippets",
                            "systemImage": "checklist",
                            "title": NSLocalizedString("Multiple Snippets Selected", comment: ""),
                            "message": NSLocalizedString("Choose a single snippet to edit its content.", comment: "")
                        ]
                    }
                    if effectiveSelectedSnippet == nil {
                        return [
                            "mode": "noSnippet",
                            "systemImage": "doc.text",
                            "title": NSLocalizedString("No Snippet Selected", comment: ""),
                            "message": NSLocalizedString("Choose a snippet to edit its content.", comment: "")
                        ]
                    }
                    return [
                        "mode": "editor",
                        "systemImage": "square.and.pencil",
                        "title": effectiveSelectedSnippet?.title ?? NSLocalizedString("No Snippet Selected", comment: ""),
                        "message": {
                            if let snippetTitle = effectiveSelectedSnippet?.title {
                                return snippetTitle
                            }
                            if let folderTitle = selectedFolder?.title {
                                return folderTitle
                            }
                            return CMLocalizedModernString("No folder selected", japanese: "フォルダ未選択")
                        }()
                    ]
                }()
                let expectedDetailPaneSectionTitles: [String] = {
                    []
                }()
                let expectedDetailEditorAppearance: [String: Any] = {
                    guard effectiveSelectedSnippet != nil else { return [:] }
                    return [
                        "fontName": "Helvetica",
                        "fontSize": 13
                    ]
                }()
                let expectedSearchPlaceholder = NSLocalizedString("876.placeholderString", tableName: "Preferences", bundle: .main, value: "All", comment: "")
                let expectedSearchEnabled = snippetStore.hasSingleSelectedFolder
                let expectedSearchAppearance: [String: Any] = [
                    "fontName": "LucidaGrande",
                    "fontSize": 13
                ]
                let expectedFolderGroupHeader = NSLocalizedString("Groups", comment: "")
                let matchesExpected = NSApp.isActive
                    && window.title == NSLocalizedString("Snippet Editor", comment: "")
                    && self.debugToolbarStyleName(window.toolbarStyle) == "unifiedCompact"
                    && styleMasks == ["titled", "closable", "miniaturizable", "resizable"]
                    && window.isVisible
                    && window.isKeyWindow
                    && window.isMainWindow
                    && contentLayoutWidth == 640
                    && contentLayoutHeight == 480
                    && window.isDocumentEdited == false
                    && (requestedSearchScopeRawValue == nil || requestedSearchScopeApplied)
                    && requestedSearchQueryApplied
                    && (requestedSelectionMode == nil || requestedSelectionModeApplied)
                    && toolbarIconSources == expectedToolbarIconSources
                    && (toolbarLayout["defaultItemLabels"] as? [String]) == expectedToolbarDefaultItemLabels
                    && (toolbarLayout["usesFlexibleSpaceBeforeSearch"] as? Bool) == true
                    && (toolbarLayout["searchFieldWidth"] as? Int) == 182
                    && toolbarItemStates == expectedToolbarItemStates
                    && splitLayout == expectedSplitLayout
                    && browserMetrics == expectedBrowserMetrics
                    && browserAppearance == expectedBrowserAppearance
                    && NSDictionary(dictionary: browserTextAppearance).isEqual(to: expectedBrowserTextAppearance)
                    && (search["isEnabled"] as? Bool) == expectedSearchEnabled
                    && NSDictionary(dictionary: searchAppearance).isEqual(to: expectedSearchAppearance)
                    && (search["placeholder"] as? String) == expectedSearchPlaceholder
                    && (search["text"] as? String) == requestedSearchQuery
                    && (search["scopeOptions"] as? [String]) == [
                        NSLocalizedString("All", comment: ""),
                        NSLocalizedString("Title", comment: ""),
                        NSLocalizedString("Content", comment: "")
                    ]
                    && (search["selectedScopeRawValue"] as? String) == expectedSearchScopeRawValue
                    && (search["selectedScopeTitle"] as? String) == expectedSearchScopeTitle
                    && (paneSnapshot["folderGroupHeader"] as? String) == expectedFolderGroupHeader
                    && (folderBrowserStructure["firstRowTitle"] as? String) == expectedFolderGroupHeader
                    && (folderBrowserStructure["firstRowIsGroup"] as? Bool) == true
                    && (folderBrowserStructure["rowCount"] as? Int) == (snippetStore.folders.count + 1)
                    && folderActionBarIconSources == expectedFolderActionBarIconSources
                    && folderActionBarStates == expectedFolderActionBarStates
                    && snippetActionsMenuTitles == expectedSnippetActionsMenuTitles
                    && snippetActionsMenuStates == expectedSnippetActionsMenuStates
                    && rowIconSources == expectedRowIconSources
                    && (browserHeaders["folderOutlineShowsHeader"] as? Bool) == false
                    && (browserHeaders["snippetTableShowsHeader"] as? Bool) == true
                    && (browserHeaders["snippetTableHeaderTitle"] as? String) == NSLocalizedString("863.headerCell.title", tableName: "Preferences", bundle: .main, value: "Title", comment: "")
                    && (browserHeaders["snippetTableHeaderHeight"] as? Int) == 17
                    && snippetListState == expectedSnippetListState
                    && visibleSnippetTitles == expectedVisibleSnippetTitles
                    && snippetListSurface == [
                        "showsTableSurface": true,
                        "showsEmptyStateCard": false
                    ]
                    && (detailPane["style"] as? String) == "contentEditor"
                    && detailPaneState == expectedDetailPaneState
                    && (detailPane["sectionTitles"] as? [String]) == expectedDetailPaneSectionTitles
                    && NSDictionary(dictionary: detailEditorAppearance).isEqual(to: expectedDetailEditorAppearance)
                    && (detailPane["showsEditorSurface"] as? Bool) == (effectiveSelectedSnippet != nil)
                    && (detailPane["showsEmptyStateCard"] as? Bool) == (effectiveSelectedSnippet == nil)
                    && (detailPane["showsContextChips"] as? Bool) == false
                    && (detailPane["showsInlineTitle"] as? Bool) == false
                    && (detailPane["showsInlineFolder"] as? Bool) == false
                    && (detailPane["showsEnabledToggle"] as? Bool) == false
                    && (selection["selectedFolderTitle"] as? String) == selectedFolder?.title
                    && (selection["selectedSnippetTitle"] as? String) == effectiveSelectedSnippet?.title
                    && (selection["selectedSnippetEnabled"] as? Bool) == effectiveSelectedSnippet?.isEnabled
                    && (paneSnapshot["footerButtons"] as? [String]) == []
                    && footerButtonIconSources == expectedFooterButtonIconSources

                report = [
                    "appIsActive": NSApp.isActive,
                    "keyWindowTitle": NSApp.keyWindow?.title as Any,
                    "mainWindowTitle": NSApp.mainWindow?.title as Any,
                    "title": window.title,
                    "titleVisibility": self.debugPreferencesWindowTitleVisibilityName(window.titleVisibility),
                    "titlebarAppearsTransparent": window.titlebarAppearsTransparent,
                    "isMovableByWindowBackground": window.isMovableByWindowBackground,
                    "toolbarStyle": self.debugToolbarStyleName(window.toolbarStyle),
                    "styleMasks": styleMasks,
                    "isVisible": window.isVisible,
                    "isKeyWindow": window.isKeyWindow,
                    "isMainWindow": window.isMainWindow,
                    "frame": [
                        "x": window.frame.origin.x,
                        "y": window.frame.origin.y,
                        "width": window.frame.size.width,
                        "height": window.frame.size.height
                    ],
                    "contentLayout": [
                        "width": contentLayoutWidth,
                        "height": contentLayoutHeight
                    ],
                    "isDocumentEdited": window.isDocumentEdited,
                        "requestedSearchScopeRawValue": requestedSearchScopeRawValue as Any,
                        "requestedSearchScopeApplied": requestedSearchScopeApplied,
                        "requestedSearchQuery": requestedSearchQuery,
                        "requestedSearchQueryApplied": requestedSearchQueryApplied,
                        "requestedSelectionMode": requestedSelectionMode as Any,
                        "requestedSelectionModeApplied": requestedSelectionModeApplied,
                    "paneSnapshot": paneSnapshot,
                    "toolbarIconSources": toolbarIconSources,
                    "expectedToolbarIconSources": expectedToolbarIconSources,
                    "toolbarLayout": toolbarLayout,
                    "expectedToolbarDefaultItemLabels": expectedToolbarDefaultItemLabels,
                    "toolbarItemStates": toolbarItemStates,
                    "expectedToolbarItemStates": expectedToolbarItemStates,
                    "splitLayout": splitLayout,
                    "expectedSplitLayout": expectedSplitLayout,
                    "browserMetrics": browserMetrics,
                    "expectedBrowserMetrics": expectedBrowserMetrics,
                    "browserAppearance": browserAppearance,
                    "expectedBrowserAppearance": expectedBrowserAppearance,
                    "browserTextAppearance": browserTextAppearance,
                    "expectedBrowserTextAppearance": expectedBrowserTextAppearance,
                    "browserHeaders": browserHeaders,
                    "browserDebug": browserDebug,
                    "visibleSnippetTitles": visibleSnippetTitles,
                    "expectedVisibleSnippetTitles": expectedVisibleSnippetTitles,
                    "snippetListSurface": snippetListSurface,
                    "folderActionBarIconSources": folderActionBarIconSources,
                    "expectedFolderActionBarIconSources": expectedFolderActionBarIconSources,
                    "folderActionBarStates": folderActionBarStates,
                    "expectedFolderActionBarStates": expectedFolderActionBarStates,
                    "snippetActionsMenuTitles": snippetActionsMenuTitles,
                    "expectedSnippetActionsMenuTitles": expectedSnippetActionsMenuTitles,
                    "snippetActionsMenuStates": snippetActionsMenuStates,
                    "expectedSnippetActionsMenuStates": expectedSnippetActionsMenuStates,
                    "rowIconSources": rowIconSources,
                    "expectedRowIconSources": expectedRowIconSources,
                    "footerButtonIconSources": footerButtonIconSources,
                    "expectedFooterButtonIconSources": expectedFooterButtonIconSources,
                    "matchesExpected": matchesExpected
                ]
                } else {
                    report["error"] = "Snippet Editor window not available"
                    report["requestedSearchScopeRawValue"] = requestedSearchScopeRawValue as Any
                    report["requestedSearchScopeApplied"] = requestedSearchScopeApplied
                    report["requestedSearchQuery"] = requestedSearchQuery
                    report["requestedSearchQueryApplied"] = requestedSearchQueryApplied
                    report["requestedSelectionMode"] = requestedSelectionMode as Any
                    report["requestedSelectionModeApplied"] = requestedSelectionModeApplied
                    report["matchesExpected"] = false
                }

                if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                    try? data.write(to: reportURL, options: .atomic)
                }

                NSApp.terminate(nil)
            }

            let needsExtraSettle = requestedSearchScopeApplied || !requestedSearchQuery.isEmpty || requestedSelectionMode != nil
            if needsExtraSettle {
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {
                    writeReport()
                }
            } else {
                writeReport()
            }
        }
    }

