    private func runDebugSnippetReorderTransferReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetReorderTransferReportPath")
            ?? "/tmp/clipmenu-snippet-reorder-transfer-report.json")
        let snippetStore = SnippetFileStore.shared
        let originalFolders = snippetStore.folders
        let originalSelection = snippetStore.currentSelectionSnapshot()

        func submenuTitles(in menu: NSMenu, folderTitle: String) -> [String] {
            menu.items.first(where: { $0.title == folderTitle })?.submenu?.items.map(\.title) ?? []
        }

        defer {
            snippetStore.folders = originalFolders
            snippetStore.save()
            snippetStore.reload()
            snippetStore.restoreSelectionSnapshot(originalSelection)
            snippetEditorController?.close()
            NSApp.terminate(nil)
        }

        showSnippetEditor(nil)
        let expectedEditorWindowTitle = NSLocalizedString("Snippet Editor", comment: "")
        let editorWindowVisible = snippetEditorController?.window?.isVisible == true
        let editorWindowTitle = snippetEditorController?.window?.title ?? ""

        let seed = populateSnippetStoreForDebugWorkflowSeed(persistReset: true)
        let qaFolderID = seed.qaFolderID
        let docsFolderID = seed.docsFolderID
        let greetingSnippetID = seed.greetingSnippetID

        let folderTitlesBeforeMove = snippetStore.folders.map(\.title)
        let snippetTitlesByFolderBeforeMove = snippetStore.folders.map { $0.snippets.map(\.title) }

        snippetStore.moveFolders(from: IndexSet(integer: 1), to: 0)
        let folderTitlesAfterReorder = snippetStore.folders.map(\.title)

        if let greetingSnippetID {
            snippetStore.moveSnippetForTesting(
                sourceFolderID: qaFolderID,
                snippetID: greetingSnippetID,
                targetFolderID: docsFolderID,
                destinationIndex: 0
            )
        }

        let snippetTitlesByFolderAfterMove = snippetStore.folders.map { $0.snippets.map(\.title) }
        let snippetsMenuAfterMove = makeSnippetsMenu()
        let docsSubmenuTitlesAfterMove = submenuTitles(in: snippetsMenuAfterMove, folderTitle: "Docs")
        let qaSubmenuTitlesAfterMove = submenuTitles(in: snippetsMenuAfterMove, folderTitle: "QA")

        snippetStore.save()
        snippetStore.reload()

        let folderTitlesAfterReload = snippetStore.folders.map(\.title)
        let snippetTitlesByFolderAfterReload = snippetStore.folders.map { $0.snippets.map(\.title) }
        let snippetsMenuAfterReload = makeSnippetsMenu()
        let docsSubmenuTitlesAfterReload = submenuTitles(in: snippetsMenuAfterReload, folderTitle: "Docs")
        let qaSubmenuTitlesAfterReload = submenuTitles(in: snippetsMenuAfterReload, folderTitle: "QA")

        let matchesExpected = editorWindowVisible
            && editorWindowTitle == expectedEditorWindowTitle
            && folderTitlesBeforeMove == ["QA", "Docs"]
            && snippetTitlesByFolderBeforeMove == [["Greeting"], []]
            && folderTitlesAfterReorder == ["Docs", "QA"]
            && snippetTitlesByFolderAfterMove == [["Greeting"], []]
            && docsSubmenuTitlesAfterMove == ["1. Greeting"]
            && qaSubmenuTitlesAfterMove.isEmpty
            && folderTitlesAfterReload == ["Docs", "QA"]
            && snippetTitlesByFolderAfterReload == [["Greeting"], []]
            && docsSubmenuTitlesAfterReload == ["1. Greeting"]
            && qaSubmenuTitlesAfterReload.isEmpty

        let report: [String: Any] = [
            "editorWindowVisible": editorWindowVisible,
            "editorWindowTitle": editorWindowTitle,
            "folderTitlesBeforeMove": folderTitlesBeforeMove,
            "snippetTitlesByFolderBeforeMove": snippetTitlesByFolderBeforeMove,
            "folderTitlesAfterReorder": folderTitlesAfterReorder,
            "snippetTitlesByFolderAfterMove": snippetTitlesByFolderAfterMove,
            "docsSubmenuTitlesAfterMove": docsSubmenuTitlesAfterMove,
            "qaSubmenuTitlesAfterMove": qaSubmenuTitlesAfterMove,
            "folderTitlesAfterReload": folderTitlesAfterReload,
            "snippetTitlesByFolderAfterReload": snippetTitlesByFolderAfterReload,
            "docsSubmenuTitlesAfterReload": docsSubmenuTitlesAfterReload,
            "qaSubmenuTitlesAfterReload": qaSubmenuTitlesAfterReload,
            "matchesExpected": matchesExpected
