    private func runDebugSnippetFolderActionBarStateReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetFolderActionBarStateReportPath")
            ?? "/tmp/clipmenu-snippet-folder-action-bar-state-report.json")
        let settleDelay = debugOneShotDoubleValue(forKey: "debugSnippetFolderActionBarStateSettleDelay") ?? 0.25
        let store = SnippetFileStore.shared
        let originalFolders = store.folders
        let originalSelection = store.currentSelectionSnapshot()

        func writeReport(_ report: [String: Any]) {
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
        }

        func restoreAndQuit() {
            store.folders = originalFolders
            store.restoreSelectionSnapshot(originalSelection)
            store.save()
            store.reload()
            snippetEditorController?.close()
            NSApp.terminate(nil)
        }

        let seed = populateSnippetStoreForDebugWorkflowSeed(persistReset: true, persistSeededState: true)
        showSnippetEditor(nil)
        NSApp.activate(ignoringOtherApps: true)
        snippetEditorController?.window?.makeMain()
        snippetEditorController?.window?.makeKeyAndOrderFront(nil)

        DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) { [weak self] in
            guard self != nil else { return }

            store.restoreSelectionSnapshot(.init(
                selectedFolderIDs: [seed.qaFolderID],
                selectedSnippetIDs: [],
                primarySelectedFolderID: seed.qaFolderID,
                primarySelectedSnippetID: nil
            ))
            let selectedSnapshot = CMSnippetEditorSnapshotForDebug()
            let selectedStates = selectedSnapshot["folderActionBarStates"] as? [String: Bool] ?? [:]

            store.restoreSelectionSnapshot(.init(
                selectedFolderIDs: [],
                selectedSnippetIDs: [],
                primarySelectedFolderID: nil,
                primarySelectedSnippetID: nil
            ))
            let unselectedSnapshot = CMSnippetEditorSnapshotForDebug()
            let unselectedStates = unselectedSnapshot["folderActionBarStates"] as? [String: Bool] ?? [:]

            let expectedSelectedStates = [
                NSLocalizedString("Add Folder", comment: ""): true,
                NSLocalizedString("Delete Folder", comment: ""): true,
                NSLocalizedString("Enable/Disable Folder", comment: ""): true,
                NSLocalizedString("Snippet Actions", comment: ""): true
            ]
            let expectedUnselectedStates = [
                NSLocalizedString("Add Folder", comment: ""): true,
                NSLocalizedString("Delete Folder", comment: ""): false,
                NSLocalizedString("Enable/Disable Folder", comment: ""): false,
                NSLocalizedString("Snippet Actions", comment: ""): true
            ]

            let report: [String: Any] = [
                "selectedFolderBrowserStructure": selectedSnapshot["folderBrowserStructure"] as Any,
                "selectedStates": selectedStates,
                "expectedSelectedStates": expectedSelectedStates,
                "unselectedStates": unselectedStates,
                "expectedUnselectedStates": expectedUnselectedStates,
                "matchesExpected": selectedStates == expectedSelectedStates
                    && unselectedStates == expectedUnselectedStates
            ]
            writeReport(report)
            restoreAndQuit()
        }
    }

