        let longText = "This is a very long history title that should truncate in the menu while staying intact when selected."
        let multilineClip = ClipItem(
            text: multilineText,
            createdAt: Date(timeIntervalSinceReferenceDate: 100),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 100)
