        func makeScratchPasteboard(suffix: String) -> NSPasteboard {
            NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.capture-filter.\(suffix).\(UUID().uuidString)"))
        }

        defaults.set(ClipItem.defaultStoreTypes(), forKey: CMPrefStoreTypesKey)
        defaults.removeObject(forKey: CMPrefExcludeAppsKey)

        let unsupportedPasteboard = makeScratchPasteboard(suffix: "unsupported")
        let unsupportedType = NSPasteboard.PasteboardType("public.html")
        unsupportedPasteboard.clearContents()
        unsupportedPasteboard.declareTypes([unsupportedType], owner: nil)
        unsupportedPasteboard.setString("<b>unsupported</b>", forType: unsupportedType)
        let unsupportedTypeRejected = capturedClip(from: unsupportedPasteboard, frontmostBundleIdentifier: nil) == nil

        let emptyStringPasteboard = makeScratchPasteboard(suffix: "emptyString")
        emptyStringPasteboard.clearContents()
        emptyStringPasteboard.declareTypes([.string], owner: nil)
        emptyStringPasteboard.setString("", forType: .string)
        let emptyStringRejected = capturedClip(from: emptyStringPasteboard, frontmostBundleIdentifier: nil) == nil

        var disabledStringStoreTypes = ClipItem.defaultStoreTypes()
        disabledStringStoreTypes["String"] = false
        defaults.set(disabledStringStoreTypes, forKey: CMPrefStoreTypesKey)
        let disabledStringPasteboard = makeScratchPasteboard(suffix: "disabledString")
        disabledStringPasteboard.clearContents()
        disabledStringPasteboard.declareTypes([.string], owner: nil)
        disabledStringPasteboard.setString("disabled-string-clip", forType: .string)
        let disabledStringTypeRejected = capturedClip(from: disabledStringPasteboard, frontmostBundleIdentifier: nil) == nil

        defaults.set(ClipItem.defaultStoreTypes(), forKey: CMPrefStoreTypesKey)
        let excludedBundleIdentifier = "com.naotaka.ClipMenu.debug.excluded-app"
        defaults.set([[kCMBundleIdentifierKey: excludedBundleIdentifier, kCMNameKey: "Debug Excluded"]], forKey: CMPrefExcludeAppsKey)
        let excludedPasteboard = makeScratchPasteboard(suffix: "excludedApp")
        excludedPasteboard.clearContents()
        excludedPasteboard.declareTypes([.string], owner: nil)
        excludedPasteboard.setString("excluded-app-clip", forType: .string)
        let excludedAppRejected = capturedClip(from: excludedPasteboard, frontmostBundleIdentifier: excludedBundleIdentifier) == nil
        let allowedClip = capturedClip(
            from: excludedPasteboard,
            frontmostBundleIdentifier: "com.naotaka.ClipMenu.debug.allowed-app"
        )
        let nonExcludedAppAccepted = allowedClip?.text == "excluded-app-clip"

        report["unsupportedTypeRejected"] = unsupportedTypeRejected
        report["emptyStringRejected"] = emptyStringRejected
        report["disabledStringTypeRejected"] = disabledStringTypeRejected
        report["excludedAppRejected"] = excludedAppRejected
        report["nonExcludedAppAccepted"] = nonExcludedAppAccepted
        report["nonExcludedAppAcceptedText"] = allowedClip?.text as Any
        report["matchesExpected"] = unsupportedTypeRejected
            && emptyStringRejected
            && disabledStringTypeRejected
            && excludedAppRejected
            && nonExcludedAppAccepted

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugHistoryMutationReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugHistoryMutationReportPath")
            ?? "/tmp/clipmenu-history-mutation-report.json")
        var report: [String: Any] = [
            "usedIsolatedSupportDirectory": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let originalClips = clipsStore.clips
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)

        defer {
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            rebuildMenu()
            NSApp.terminate(nil)
        }

        func makeDeterministicClip(text: String, seconds: TimeInterval) -> ClipItem {
            let date = Date(timeIntervalSinceReferenceDate: seconds)
            return ClipItem(text: text, createdAt: date, lastUsedAt: date)
        }

        func seedBaselineHistoryVerificationClips() {
            clipsStore.clear()
            clipsStore.add(makeDeterministicClip(text: "fixture-alpha", seconds: 100))
            clipsStore.add(makeDeterministicClip(text: "fixture-beta", seconds: 200))
            clipsStore.add(makeDeterministicClip(text: "fixture-gamma", seconds: 300))
            clipsStore.add(makeDeterministicClip(text: "fixture-delta", seconds: 400))
        }

        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        seedBaselineHistoryVerificationClips()
        let baselineOrderedTexts = clipsStore.orderedClips.map(\.text)

        let duplicateTarget = clipsStore.orderedClips.last ?? clipsStore.orderedClips.first
        let countBeforeDuplicate = clipsStore.clips.count
        let duplicateTargetText = duplicateTarget?.text ?? ""
        if let duplicateTarget {
            clipsStore.add(duplicateTarget)
        }
        let afterDuplicateOrderedTexts = clipsStore.orderedClips.map(\.text)
        let duplicatePromotedToTop = afterDuplicateOrderedTexts.first == duplicateTargetText
        let duplicateKeptCount = clipsStore.clips.count == countBeforeDuplicate

        defaults.set(2, forKey: CMPrefMaxHistorySizeKey)
        clipsStore.trimToCurrentHistoryLimit()
        let trimmedOrderedTexts = clipsStore.orderedClips.map(\.text)
        let trimmedCount = clipsStore.clips.count
        let afterTrimUnsavedChanges = clipsStore.debugHasUnsavedChanges

        let expectedBaselineOrderedTexts = ["fixture-delta", "fixture-gamma", "fixture-beta", "fixture-alpha"]
        let expectedAfterDuplicateOrderedTexts = ["fixture-alpha", "fixture-delta", "fixture-gamma", "fixture-beta"]
        let expectedTrimmedOrderedTexts = ["fixture-alpha", "fixture-delta"]

        report["baselineOrderedTexts"] = baselineOrderedTexts
        report["duplicateTargetText"] = duplicateTargetText
        report["afterDuplicateOrderedTexts"] = afterDuplicateOrderedTexts
        report["duplicatePromotedToTop"] = duplicatePromotedToTop
        report["duplicateKeptCount"] = duplicateKeptCount
        report["trimmedOrderedTexts"] = trimmedOrderedTexts
        report["trimmedCount"] = trimmedCount
        report["afterTrimUnsavedChanges"] = afterTrimUnsavedChanges
        report["expectedState"] = [
            "baselineOrderedTexts": expectedBaselineOrderedTexts,
            "duplicateTargetText": "fixture-alpha",
            "afterDuplicateOrderedTexts": expectedAfterDuplicateOrderedTexts,
            "trimmedOrderedTexts": expectedTrimmedOrderedTexts,
            "trimmedCount": 2
        ]
        report["matchesExpected"] = baselineOrderedTexts == expectedBaselineOrderedTexts
            && duplicateTargetText == "fixture-alpha"
            && afterDuplicateOrderedTexts == expectedAfterDuplicateOrderedTexts
            && duplicatePromotedToTop
            && duplicateKeptCount
            && trimmedOrderedTexts == expectedTrimmedOrderedTexts
            && trimmedCount == 2
            && afterTrimUnsavedChanges

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugHistoryPersistenceReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugHistoryPersistenceReportPath")
            ?? "/tmp/clipmenu-history-persistence-report.json")
        var report: [String: Any] = [
            "usedIsolatedSupportDirectory": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let originalClips = clipsStore.clips
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)
        let originalSaveHistoryOnQuit = defaults.object(forKey: CMPrefSaveHistoryOnQuitKey)

        defer {
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            restoreDefault(originalSaveHistoryOnQuit, forKey: CMPrefSaveHistoryOnQuitKey)
            clipsStore.removeSavedHistory()
            rebuildMenu()
            NSApp.terminate(nil)
        }

        func makeDeterministicClip(text: String, seconds: TimeInterval) -> ClipItem {
            let date = Date(timeIntervalSinceReferenceDate: seconds)
            return ClipItem(text: text, createdAt: date, lastUsedAt: date)
        }

        func seedBaselineHistoryVerificationClips() {
            clipsStore.clear()
            clipsStore.add(makeDeterministicClip(text: "fixture-alpha", seconds: 100))
            clipsStore.add(makeDeterministicClip(text: "fixture-beta", seconds: 200))
            clipsStore.add(makeDeterministicClip(text: "fixture-gamma", seconds: 300))
            clipsStore.add(makeDeterministicClip(text: "fixture-delta", seconds: 400))
        }

        defaults.set(2, forKey: CMPrefMaxHistorySizeKey)
        seedBaselineHistoryVerificationClips()
        clipsStore.trimToCurrentHistoryLimit()
        let trimmedOrderedTexts = clipsStore.orderedClips.map(\.text)
        let saveSucceeded = clipsStore.save()

        let reloadedStore = ClipStore()
        reloadedStore.load()
        let reloadedOrderedTexts = reloadedStore.orderedClips.map(\.text)

        reloadedStore.removeSavedHistory()
        let clearedStore = ClipStore()
        clearedStore.load()
        let clearedReloadCount = clearedStore.clips.count
        let clearedReloadEmpty = clearedStore.clips.isEmpty

        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        clipsStore.clear()
        clipsStore.add(ClipItem(text: "quit-save-alpha"))
        clipsStore.add(ClipItem(text: "quit-save-beta"))
        let quitSaveExpectedTexts = clipsStore.orderedClips.map(\.text)
        defaults.set(true, forKey: CMPrefSaveHistoryOnQuitKey)
        let quitSavePersistSucceeded = persistHistoryForTermination()
        let quitSaveReloadStore = ClipStore()
        quitSaveReloadStore.load()
        let quitSaveReloadTexts = quitSaveReloadStore.orderedClips.map(\.text)

        clipsStore.clear()
        clipsStore.add(ClipItem(text: "quit-discard-alpha"))
        defaults.set(false, forKey: CMPrefSaveHistoryOnQuitKey)
        let quitDiscardPersistSucceeded = persistHistoryForTermination()
        let quitDiscardReloadStore = ClipStore()
        quitDiscardReloadStore.load()
        let quitDiscardReloadCount = quitDiscardReloadStore.clips.count
        let quitDiscardReloadEmpty = quitDiscardReloadStore.clips.isEmpty

        clipsStore.clear()
        clipsStore.removeSavedHistory()
        defaults.set(true, forKey: CMPrefSaveHistoryOnQuitKey)
        clipsStore.add(ClipItem(text: "capture-flush-alpha"))
        let captureFlushPersistSucceeded = persistCapturedHistoryIfPreferred()
        let captureFlushReloadStore = ClipStore()
        captureFlushReloadStore.load()
        let captureFlushReloadTexts = captureFlushReloadStore.orderedClips.map(\.text)

        let expectedTrimmedOrderedTexts = ["fixture-delta", "fixture-gamma"]
        let expectedQuitSaveReloadTexts = ["quit-save-beta", "quit-save-alpha"]
        let expectedCaptureFlushReloadTexts = ["capture-flush-alpha"]

        report["trimmedOrderedTextsBeforeSave"] = trimmedOrderedTexts
        report["saveSucceeded"] = saveSucceeded
        report["reloadedOrderedTexts"] = reloadedOrderedTexts
        report["reloadMatchesTrimmedState"] = reloadedOrderedTexts == trimmedOrderedTexts
        report["clearedReloadCount"] = clearedReloadCount
        report["clearedReloadEmpty"] = clearedReloadEmpty
        report["quitSavePersistSucceeded"] = quitSavePersistSucceeded
        report["quitSaveExpectedTexts"] = quitSaveExpectedTexts
        report["quitSaveReloadTexts"] = quitSaveReloadTexts
        report["quitSaveReloadMatchesExpected"] = quitSaveReloadTexts == quitSaveExpectedTexts
        report["quitDiscardPersistSucceeded"] = quitDiscardPersistSucceeded
        report["quitDiscardReloadCount"] = quitDiscardReloadCount
        report["quitDiscardReloadEmpty"] = quitDiscardReloadEmpty
        report["captureFlushPersistSucceeded"] = captureFlushPersistSucceeded
        report["captureFlushReloadTexts"] = captureFlushReloadTexts
        report["captureFlushReloadMatchesExpected"] = captureFlushReloadTexts == expectedCaptureFlushReloadTexts
        report["expectedState"] = [
            "trimmedOrderedTextsBeforeSave": expectedTrimmedOrderedTexts,
            "reloadedOrderedTexts": expectedTrimmedOrderedTexts,
            "clearedReloadCount": 0,
            "quitSaveReloadTexts": expectedQuitSaveReloadTexts,
            "quitDiscardReloadCount": 0,
            "captureFlushReloadTexts": expectedCaptureFlushReloadTexts
        ]
        report["matchesExpected"] = trimmedOrderedTexts == expectedTrimmedOrderedTexts
            && saveSucceeded
            && reloadedOrderedTexts == expectedTrimmedOrderedTexts
            && clearedReloadCount == 0
            && clearedReloadEmpty
            && quitSavePersistSucceeded
            && quitSaveExpectedTexts == expectedQuitSaveReloadTexts
            && quitSaveReloadTexts == expectedQuitSaveReloadTexts
            && quitDiscardPersistSucceeded
            && quitDiscardReloadCount == 0
            && quitDiscardReloadEmpty
            && captureFlushPersistSucceeded
            && captureFlushReloadTexts == expectedCaptureFlushReloadTexts

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugTypedCaptureReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugTypedCaptureReportPath")
            ?? "/tmp/clipmenu-typed-capture-report.json")
        var report: [String: Any] = [
            "usedIsolatedSupportDirectory": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let originalStoreTypes = defaults.object(forKey: CMPrefStoreTypesKey)

        defer {
            restoreDefault(originalStoreTypes, forKey: CMPrefStoreTypesKey)
            NSApp.terminate(nil)
        }

        func makeScratchPasteboard(suffix: String) -> NSPasteboard {
            NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.typed-capture.\(suffix).\(UUID().uuidString)"))
        }

        let allDisabledStoreTypes = Dictionary(uniqueKeysWithValues: ClipItem.defaultStoreTypes().keys.map { ($0, false) })
        defaults.set(allDisabledStoreTypes, forKey: CMPrefStoreTypesKey)
        let allDisabledStringPasteboard = makeScratchPasteboard(suffix: "allDisabledString")
        allDisabledStringPasteboard.clearContents()
        allDisabledStringPasteboard.declareTypes([.string], owner: nil)
        allDisabledStringPasteboard.setString("all-disabled-string-clip", forType: .string)
        let allDisabledStoreTypesRejectString = capturedClip(from: allDisabledStringPasteboard, frontmostBundleIdentifier: nil) == nil

        let allDisabledPDFPasteboard = makeScratchPasteboard(suffix: "allDisabledPDF")
        _ = writeDebugPDFPasteboard(allDisabledPDFPasteboard)
        let allDisabledStoreTypesRejectPDF = capturedClip(from: allDisabledPDFPasteboard, frontmostBundleIdentifier: nil) == nil

        var pdfOnlyStoreTypes = Dictionary(uniqueKeysWithValues: ClipItem.defaultStoreTypes().keys.map { ($0, false) })
        pdfOnlyStoreTypes["PDF"] = true
        defaults.set(pdfOnlyStoreTypes, forKey: CMPrefStoreTypesKey)
        let pdfOnlyStringPasteboard = makeScratchPasteboard(suffix: "pdfOnlyString")
        pdfOnlyStringPasteboard.clearContents()
        pdfOnlyStringPasteboard.declareTypes([.string], owner: nil)
        pdfOnlyStringPasteboard.setString("pdf-only-string-clip", forType: .string)
        let pdfOnlyStoreTypesRejectString = capturedClip(from: pdfOnlyStringPasteboard, frontmostBundleIdentifier: nil) == nil

        let pdfOnlyPasteboard = makeScratchPasteboard(suffix: "pdfOnly")
        _ = writeDebugPDFPasteboard(pdfOnlyPasteboard)
        let pdfOnlyClip = capturedClip(from: pdfOnlyPasteboard, frontmostBundleIdentifier: nil)
        let pdfOnlyStoreTypesAcceptPDF = pdfOnlyClip?.types.contains(NSPasteboard.PasteboardType.pdf.rawValue) == true

        var rtfOnlyStoreTypes = Dictionary(uniqueKeysWithValues: ClipItem.defaultStoreTypes().keys.map { ($0, false) })
        rtfOnlyStoreTypes["RTF"] = true
        defaults.set(rtfOnlyStoreTypes, forKey: CMPrefStoreTypesKey)
        let rtfOnlyStringPasteboard = makeScratchPasteboard(suffix: "rtfOnlyString")
        rtfOnlyStringPasteboard.clearContents()
        rtfOnlyStringPasteboard.declareTypes([.string], owner: nil)
        rtfOnlyStringPasteboard.setString("rtf-only-string-clip", forType: .string)
        let rtfOnlyStoreTypesRejectString = capturedClip(from: rtfOnlyStringPasteboard, frontmostBundleIdentifier: nil) == nil

        let rtfOnlyPasteboard = makeScratchPasteboard(suffix: "rtfOnly")
        _ = writeDebugRTFPasteboard(rtfOnlyPasteboard)
        let rtfOnlyClip = capturedClip(from: rtfOnlyPasteboard, frontmostBundleIdentifier: nil)
        let rtfOnlyStoreTypesAcceptRTF = rtfOnlyClip?.types.contains(NSPasteboard.PasteboardType.rtf.rawValue) == true
            && rtfOnlyClip?.rtfData?.isEmpty == false
            && rtfOnlyClip?.text == "Rich Smoke"

        var tiffOnlyStoreTypes = Dictionary(uniqueKeysWithValues: ClipItem.defaultStoreTypes().keys.map { ($0, false) })
        tiffOnlyStoreTypes["TIFF"] = true
        defaults.set(tiffOnlyStoreTypes, forKey: CMPrefStoreTypesKey)
        let tiffOnlyStringPasteboard = makeScratchPasteboard(suffix: "tiffOnlyString")
        tiffOnlyStringPasteboard.clearContents()
        tiffOnlyStringPasteboard.declareTypes([.string], owner: nil)
        tiffOnlyStringPasteboard.setString("tiff-only-string-clip", forType: .string)
        let tiffOnlyStoreTypesRejectString = capturedClip(from: tiffOnlyStringPasteboard, frontmostBundleIdentifier: nil) == nil

        let tiffOnlyPasteboard = makeScratchPasteboard(suffix: "tiffOnly")
        _ = writeDebugImagePasteboard(tiffOnlyPasteboard)
        let tiffOnlyClip = capturedClip(from: tiffOnlyPasteboard, frontmostBundleIdentifier: nil)
        let tiffOnlyStoreTypesAcceptImage = tiffOnlyClip?.types.contains(NSPasteboard.PasteboardType.tiff.rawValue) == true
            && tiffOnlyClip?.imageData?.isEmpty == false

        var disabledTIFFStoreTypes = ClipItem.defaultStoreTypes()
        disabledTIFFStoreTypes["TIFF"] = false
        defaults.set(disabledTIFFStoreTypes, forKey: CMPrefStoreTypesKey)
        let disabledTIFFPasteboard = makeScratchPasteboard(suffix: "disabledTIFF")
        _ = writeDebugImagePasteboard(disabledTIFFPasteboard)
        let disabledTIFFTypeRejected = capturedClip(from: disabledTIFFPasteboard, frontmostBundleIdentifier: nil) == nil

        var disabledRTFDStoreTypes = ClipItem.defaultStoreTypes()
        disabledRTFDStoreTypes["RTFD"] = false
        defaults.set(disabledRTFDStoreTypes, forKey: CMPrefStoreTypesKey)
        let disabledRTFDPasteboard = makeScratchPasteboard(suffix: "disabledRTFD")
        _ = writeDebugRTFDOnlyPasteboard(disabledRTFDPasteboard)
        let disabledRTFDTypeRejected = capturedClip(from: disabledRTFDPasteboard, frontmostBundleIdentifier: nil) == nil

        report["allDisabledStoreTypesRejectString"] = allDisabledStoreTypesRejectString
        report["allDisabledStoreTypesRejectPDF"] = allDisabledStoreTypesRejectPDF
        report["pdfOnlyStoreTypesRejectString"] = pdfOnlyStoreTypesRejectString
        report["pdfOnlyStoreTypesAcceptPDF"] = pdfOnlyStoreTypesAcceptPDF
        report["rtfOnlyStoreTypesRejectString"] = rtfOnlyStoreTypesRejectString
        report["rtfOnlyStoreTypesAcceptRTF"] = rtfOnlyStoreTypesAcceptRTF
        report["tiffOnlyStoreTypesRejectString"] = tiffOnlyStoreTypesRejectString
        report["tiffOnlyStoreTypesAcceptImage"] = tiffOnlyStoreTypesAcceptImage
        report["disabledTIFFTypeRejected"] = disabledTIFFTypeRejected
        report["disabledRTFDTypeRejected"] = disabledRTFDTypeRejected
        report["matchesExpected"] = allDisabledStoreTypesRejectString
            && allDisabledStoreTypesRejectPDF
            && pdfOnlyStoreTypesRejectString
            && pdfOnlyStoreTypesAcceptPDF
            && rtfOnlyStoreTypesRejectString
            && rtfOnlyStoreTypesAcceptRTF
            && tiffOnlyStoreTypesRejectString
            && tiffOnlyStoreTypesAcceptImage
            && disabledTIFFTypeRejected
            && disabledRTFDTypeRejected

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugTypedRenderingReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugTypedRenderingReportPath")
            ?? "/tmp/clipmenu-typed-rendering-report.json")
        var report: [String: Any] = [
            "usedIsolatedSupportDirectory": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let originalShowImage = defaults.object(forKey: CMPrefShowImageInTheMenuKey)
        let originalShowIcon = defaults.object(forKey: CMPrefShowIconInTheMenuKey)
        let originalThumbnailWidth = defaults.object(forKey: CMPrefThumbnailWidthKey)
        let originalThumbnailHeight = defaults.object(forKey: CMPrefThumbnailHeightKey)
        let originalMenuIconSize = defaults.object(forKey: CMPrefMenuIconSizeKey)

        defer {
            restoreDefault(originalShowImage, forKey: CMPrefShowImageInTheMenuKey)
            restoreDefault(originalShowIcon, forKey: CMPrefShowIconInTheMenuKey)
            restoreDefault(originalThumbnailWidth, forKey: CMPrefThumbnailWidthKey)
            restoreDefault(originalThumbnailHeight, forKey: CMPrefThumbnailHeightKey)
            restoreDefault(originalMenuIconSize, forKey: CMPrefMenuIconSizeKey)
            NSApp.terminate(nil)
        }

        func makeDeterministicDate(_ seconds: TimeInterval) -> Date {
            Date(timeIntervalSinceReferenceDate: seconds)
        }

        let visibleImageClip = ClipItem(
            types: [NSPasteboard.PasteboardType.tiff.rawValue],
            createdAt: makeDeterministicDate(500),
            lastUsedAt: makeDeterministicDate(500),
            text: "",
            imageData: debugImageData()
        )
        let iconFallbackPDFClip = ClipItem(
            types: [NSPasteboard.PasteboardType.pdf.rawValue],
            createdAt: makeDeterministicDate(600),
            lastUsedAt: makeDeterministicDate(600),
            text: "",
            pdfData: Data("pdf-icon-smoke".utf8)
        )

        defaults.set(true, forKey: CMPrefShowImageInTheMenuKey)
        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        defaults.set(4, forKey: CMPrefThumbnailWidthKey)
        defaults.set(6, forKey: CMPrefThumbnailHeightKey)
        let visibleImageItem = makeClipMenuItem(clip: visibleImageClip, globalIndex: 0, listNumber: 1)
        let showImageEnabledHasThumbnail = visibleImageItem.image != nil
        let showImageEnabledThumbnailFitsBounds = {
            guard let size = visibleImageItem.image?.size else { return false }
            return size.width <= 4.0 && size.height <= 6.0
        }()

        defaults.set(false, forKey: CMPrefShowImageInTheMenuKey)
        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        let hiddenImageItem = makeClipMenuItem(clip: visibleImageClip, globalIndex: 0, listNumber: 1)
        let showImageDisabledSuppressesImageClipImage = hiddenImageItem.image == nil

        defaults.set(false, forKey: CMPrefShowImageInTheMenuKey)
        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        let iconFallbackPDFItem = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let nonImageClipStillUsesIconWhenIconsEnabled = iconFallbackPDFItem.image != nil

        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        defaults.set(16, forKey: CMPrefMenuIconSizeKey)
        let icon16Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconSize16MatchesExpected = {
            guard let size = icon16Item.image?.size else { return false }
            return size.width == 16 && size.height == 16
        }()

        defaults.set(32, forKey: CMPrefMenuIconSizeKey)
        let icon32Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconSize32MatchesExpected = {
            guard let size = icon32Item.image?.size else { return false }
            return size.width == 32 && size.height == 32
        }()

        defaults.set(48, forKey: CMPrefMenuIconSizeKey)
        let icon48Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconSize48MatchesExpected = {
            guard let size = icon48Item.image?.size else { return false }
            return size.width == 48 && size.height == 48
        }()

        defaults.set(24, forKey: CMPrefMenuIconSizeKey)
        let icon24Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconSize24NormalizesToLegacy16 = {
            guard let size = icon24Item.image?.size else { return false }
            return size.width == 16 && size.height == 16
        }()

        defaults.set(false, forKey: CMPrefShowIconInTheMenuKey)
        let iconsDisabledItem = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        let menuIconsDisabledSuppressesNonImageIcon = iconsDisabledItem.image == nil

        report["showImageEnabledHasThumbnail"] = showImageEnabledHasThumbnail
        report["showImageEnabledThumbnailFitsBounds"] = showImageEnabledThumbnailFitsBounds
        report["showImageDisabledSuppressesImageClipImage"] = showImageDisabledSuppressesImageClipImage
        report["nonImageClipStillUsesIconWhenIconsEnabled"] = nonImageClipStillUsesIconWhenIconsEnabled
        report["menuIconSize16MatchesExpected"] = menuIconSize16MatchesExpected
        report["menuIconSize32MatchesExpected"] = menuIconSize32MatchesExpected
        report["menuIconSize48MatchesExpected"] = menuIconSize48MatchesExpected
        report["menuIconSize24NormalizesToLegacy16"] = menuIconSize24NormalizesToLegacy16
        report["menuIconsDisabledSuppressesNonImageIcon"] = menuIconsDisabledSuppressesNonImageIcon
        report["matchesExpected"] = showImageEnabledHasThumbnail
            && showImageEnabledThumbnailFitsBounds
            && showImageDisabledSuppressesImageClipImage
            && nonImageClipStillUsesIconWhenIconsEnabled
            && menuIconSize16MatchesExpected
            && menuIconSize32MatchesExpected
            && menuIconSize48MatchesExpected
            && menuIconSize24NormalizesToLegacy16
            && menuIconsDisabledSuppressesNonImageIcon

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugTypeIconRoutingReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugTypeIconRoutingReportPath")
            ?? "/tmp/clipmenu-type-icon-routing-report.json")
        var report: [String: Any] = [
            "usedIsolatedSupportDirectory": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let originalTIFFTag = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForTIFFKey)
        let originalTIFFType = defaults.object(forKey: CMPrefMenuIconOfFileTypeForTIFFKey)
        let originalPICTTag = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForPICTKey)
        let originalPICTType = defaults.object(forKey: CMPrefMenuIconOfFileTypeForPICTKey)
        let originalFilenamesTag = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey)
        let originalFilenamesType = defaults.object(forKey: CMPrefMenuIconOfFileTypeForFilenamesKey)
        let originalURLTag = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForURLKey)
        let originalURLType = defaults.object(forKey: CMPrefMenuIconOfFileTypeForURLKey)
        let originalStringTag = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForStringKey)
        let originalStringType = defaults.object(forKey: CMPrefMenuIconOfFileTypeForStringKey)
        let originalRTFTag = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForRTFKey)
        let originalRTFType = defaults.object(forKey: CMPrefMenuIconOfFileTypeForRTFKey)
        let originalRTFDTag = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForRTFDKey)
        let originalRTFDType = defaults.object(forKey: CMPrefMenuIconOfFileTypeForRTFDKey)
        let originalPDFTag = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForPDFKey)
        let originalPDFType = defaults.object(forKey: CMPrefMenuIconOfFileTypeForPDFKey)

        defer {
            restoreDefault(originalTIFFTag, forKey: CMPrefMenuIconOfFileTypeTagForTIFFKey)
            restoreDefault(originalTIFFType, forKey: CMPrefMenuIconOfFileTypeForTIFFKey)
            restoreDefault(originalPICTTag, forKey: CMPrefMenuIconOfFileTypeTagForPICTKey)
            restoreDefault(originalPICTType, forKey: CMPrefMenuIconOfFileTypeForPICTKey)
            restoreDefault(originalFilenamesTag, forKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey)
            restoreDefault(originalFilenamesType, forKey: CMPrefMenuIconOfFileTypeForFilenamesKey)
            restoreDefault(originalURLTag, forKey: CMPrefMenuIconOfFileTypeTagForURLKey)
            restoreDefault(originalURLType, forKey: CMPrefMenuIconOfFileTypeForURLKey)
            restoreDefault(originalStringTag, forKey: CMPrefMenuIconOfFileTypeTagForStringKey)
            restoreDefault(originalStringType, forKey: CMPrefMenuIconOfFileTypeForStringKey)
            restoreDefault(originalRTFTag, forKey: CMPrefMenuIconOfFileTypeTagForRTFKey)
            restoreDefault(originalRTFType, forKey: CMPrefMenuIconOfFileTypeForRTFKey)
            restoreDefault(originalRTFDTag, forKey: CMPrefMenuIconOfFileTypeTagForRTFDKey)
            restoreDefault(originalRTFDType, forKey: CMPrefMenuIconOfFileTypeForRTFDKey)
            restoreDefault(originalPDFTag, forKey: CMPrefMenuIconOfFileTypeTagForPDFKey)
            restoreDefault(originalPDFType, forKey: CMPrefMenuIconOfFileTypeForPDFKey)
            NSApp.terminate(nil)
        }

        func debugImageFingerprint(_ image: NSImage?) -> Data? {
            guard let tiffRepresentation = image?.tiffRepresentation,
                  let bitmap = NSBitmapImageRep(data: tiffRepresentation) else {
                return nil
            }
            return bitmap.representation(using: .png, properties: [:])
        }

        defaults.set(0, forKey: CMPrefMenuIconOfFileTypeTagForTIFFKey)
        defaults.set("pdf", forKey: CMPrefMenuIconOfFileTypeForTIFFKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForPICTKey)
        defaults.set("fold", forKey: CMPrefMenuIconOfFileTypeForPICTKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey)
        defaults.set("fold", forKey: CMPrefMenuIconOfFileTypeForFilenamesKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForURLKey)
        defaults.set("gurl", forKey: CMPrefMenuIconOfFileTypeForURLKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForStringKey)
        defaults.set("TEXT", forKey: CMPrefMenuIconOfFileTypeForStringKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForRTFKey)
        defaults.set("fold", forKey: CMPrefMenuIconOfFileTypeForRTFKey)
        defaults.set(0, forKey: CMPrefMenuIconOfFileTypeTagForRTFDKey)
        defaults.set("rtfd", forKey: CMPrefMenuIconOfFileTypeForRTFDKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForPDFKey)
        defaults.set("PDF ", forKey: CMPrefMenuIconOfFileTypeForPDFKey)

        let runtimeStringIcon = fileTypeIcon(for: .string)
        let runtimeRTFIcon = fileTypeIcon(for: .rtf)
        let runtimeRTFDIcon = fileTypeIcon(for: .rtfd)
        let runtimePDFIcon = fileTypeIcon(for: .pdf)
        let runtimeTIFFIcon = fileTypeIcon(for: .tiff)
        let runtimePICTIcon = fileTypeIcon(for: .clipMenuPICT)
        let runtimeFilenamesIcon = fileTypeIcon(for: .clipMenuFilenames)
        let runtimeURLIcon = fileTypeIcon(for: .clipMenuURL)

        let expectedStringIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "TEXT"))
        )
        let expectedRTFIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "fold"))
        )
        let expectedRTFDIcon = NSWorkspace.shared.icon(forFileType: "rtfd")
        let expectedPDFIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "PDF "))
        )
        let expectedTIFFIcon = NSWorkspace.shared.icon(forFileType: "pdf")
        let expectedPICTIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "fold"))
        )
        let expectedFilenamesIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "fold"))
        )
        let expectedURLIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "gurl"))
        )

        let runtimeStringFingerprint = debugImageFingerprint(runtimeStringIcon)
        let runtimeRTFFingerprint = debugImageFingerprint(runtimeRTFIcon)
        let runtimeRTFDFingerprint = debugImageFingerprint(runtimeRTFDIcon)
        let runtimePDFFingerprint = debugImageFingerprint(runtimePDFIcon)
        let runtimeTIFFFingerprint = debugImageFingerprint(runtimeTIFFIcon)
        let runtimePICTFingerprint = debugImageFingerprint(runtimePICTIcon)
        let runtimeFilenamesFingerprint = debugImageFingerprint(runtimeFilenamesIcon)
        let runtimeURLFingerprint = debugImageFingerprint(runtimeURLIcon)

        let stringRuntimeUsesStringPreference =
            runtimeStringFingerprint == debugImageFingerprint(expectedStringIcon)
        let rtfRuntimeUsesRTFPreference =
            runtimeRTFFingerprint == debugImageFingerprint(expectedRTFIcon)
        let rtfdRuntimeUsesRTFDPreference =
            runtimeRTFDFingerprint == debugImageFingerprint(expectedRTFDIcon)
        let pdfRuntimeUsesPDFPreference =
            runtimePDFFingerprint == debugImageFingerprint(expectedPDFIcon)
        let rtfRuntimeDiffersFromStringPreference =
            runtimeRTFFingerprint != runtimeStringFingerprint
        let rtfdRuntimeDiffersFromRTFPreference =
            runtimeRTFDFingerprint != runtimeRTFFingerprint
        let pdfRuntimeDiffersFromRTFDPreference =
            runtimePDFFingerprint != runtimeRTFDFingerprint
        let tiffRuntimeUsesTIFFPreference =
            runtimeTIFFFingerprint == debugImageFingerprint(expectedTIFFIcon)
        let pictRuntimeUsesPICTPreference =
            runtimePICTFingerprint == debugImageFingerprint(expectedPICTIcon)
        let pictRuntimeDiffersFromTIFFPreference =
            runtimePICTFingerprint != runtimeTIFFFingerprint
        let filenamesRuntimeUsesFilenamesPreference =
            runtimeFilenamesFingerprint == debugImageFingerprint(expectedFilenamesIcon)
        let urlRuntimeUsesURLPreference =
            runtimeURLFingerprint == debugImageFingerprint(expectedURLIcon)
        let urlRuntimeDiffersFromFilenamesPreference =
            runtimeURLFingerprint != runtimeFilenamesFingerprint

        report["stringRuntimeUsesStringPreference"] = stringRuntimeUsesStringPreference
        report["rtfRuntimeUsesRTFPreference"] = rtfRuntimeUsesRTFPreference
        report["rtfdRuntimeUsesRTFDPreference"] = rtfdRuntimeUsesRTFDPreference
        report["pdfRuntimeUsesPDFPreference"] = pdfRuntimeUsesPDFPreference
        report["rtfRuntimeDiffersFromStringPreference"] = rtfRuntimeDiffersFromStringPreference
        report["rtfdRuntimeDiffersFromRTFPreference"] = rtfdRuntimeDiffersFromRTFPreference
        report["pdfRuntimeDiffersFromRTFDPreference"] = pdfRuntimeDiffersFromRTFDPreference
        report["tiffRuntimeUsesTIFFPreference"] = tiffRuntimeUsesTIFFPreference
        report["pictRuntimeUsesPICTPreference"] = pictRuntimeUsesPICTPreference
        report["pictRuntimeDiffersFromTIFFPreference"] = pictRuntimeDiffersFromTIFFPreference
        report["filenamesRuntimeUsesFilenamesPreference"] = filenamesRuntimeUsesFilenamesPreference
        report["urlRuntimeUsesURLPreference"] = urlRuntimeUsesURLPreference
        report["urlRuntimeDiffersFromFilenamesPreference"] = urlRuntimeDiffersFromFilenamesPreference
        report["matchesExpected"] = stringRuntimeUsesStringPreference
            && rtfRuntimeUsesRTFPreference
            && rtfdRuntimeUsesRTFDPreference
            && pdfRuntimeUsesPDFPreference
            && rtfRuntimeDiffersFromStringPreference
            && rtfdRuntimeDiffersFromRTFPreference
            && pdfRuntimeDiffersFromRTFDPreference
            && tiffRuntimeUsesTIFFPreference
            && pictRuntimeUsesPICTPreference
            && pictRuntimeDiffersFromTIFFPreference
            && filenamesRuntimeUsesFilenamesPreference
            && urlRuntimeUsesURLPreference
            && urlRuntimeDiffersFromFilenamesPreference

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugMenuFontSizeReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugMenuFontSizeReportPath")
            ?? "/tmp/clipmenu-menu-font-size-report.json")
        let originalChangeFontSize = defaults.object(forKey: CMPrefChangeFontSizeKey)
        let originalHowToChangeFontSize = defaults.object(forKey: CMPrefHowToChangeFontSizeKey)
        let originalShowIconInMenu = defaults.object(forKey: CMPrefShowIconInTheMenuKey)
        let originalMenuIconSize = defaults.object(forKey: CMPrefMenuIconSizeKey)
        let originalSelectedFontSize = defaults.object(forKey: CMPrefSelectedFontSizeKey)
        let originalShowLabels = defaults.object(forKey: CMPrefShowLabelsInMenuKey)
        let originalMarkNumbers = defaults.object(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        let originalStartsFromZero = defaults.object(forKey: CMPrefMenuItemsTitleStartWithZeroKey)

        defer {
            restoreDefault(originalChangeFontSize, forKey: CMPrefChangeFontSizeKey)
            restoreDefault(originalHowToChangeFontSize, forKey: CMPrefHowToChangeFontSizeKey)
            restoreDefault(originalShowIconInMenu, forKey: CMPrefShowIconInTheMenuKey)
            restoreDefault(originalMenuIconSize, forKey: CMPrefMenuIconSizeKey)
            restoreDefault(originalSelectedFontSize, forKey: CMPrefSelectedFontSizeKey)
            restoreDefault(originalShowLabels, forKey: CMPrefShowLabelsInMenuKey)
            restoreDefault(originalMarkNumbers, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
            restoreDefault(originalStartsFromZero, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
            NSApp.terminate(nil)
        }

        defaults.set(true, forKey: CMPrefChangeFontSizeKey)
        defaults.set(false, forKey: CMPrefShowLabelsInMenuKey)
        defaults.set(true, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        defaults.set(false, forKey: CMPrefMenuItemsTitleStartWithZeroKey)

        let clip = ClipItem(
            text: "font-size-smoke",
            createdAt: Date(timeIntervalSinceReferenceDate: 100),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 100)
        )

        func reportedFontSize(mode: Int, showIcons: Bool, iconSize: Int, selectedSize: Float) -> Double? {
            defaults.set(mode, forKey: CMPrefHowToChangeFontSizeKey)
            defaults.set(showIcons, forKey: CMPrefShowIconInTheMenuKey)
            defaults.set(iconSize, forKey: CMPrefMenuIconSizeKey)
            defaults.set(selectedSize, forKey: CMPrefSelectedFontSizeKey)
            let item = makeClipMenuItem(clip: clip, globalIndex: 0, listNumber: 1)
            guard
                let attributedTitle = item.attributedTitle,
                attributedTitle.length > 0,
                let font = attributedTitle.attribute(.font, at: 0, effectiveRange: nil) as? NSFont
            else {
                return nil
            }
            return Double(font.pointSize)
        }

        let iconHiddenSize = reportedFontSize(mode: 0, showIcons: false, iconSize: 16, selectedSize: 17)
        let icon16Size = reportedFontSize(mode: 0, showIcons: true, iconSize: 16, selectedSize: 17)
        let icon32Size = reportedFontSize(mode: 0, showIcons: true, iconSize: 32, selectedSize: 17)
        let icon48Size = reportedFontSize(mode: 0, showIcons: true, iconSize: 48, selectedSize: 17)
        let selectedPointSize = reportedFontSize(mode: 1, showIcons: true, iconSize: 48, selectedSize: 19)
        let verificationItem = makeClipMenuItem(clip: clip, globalIndex: 0, listNumber: 1)
        let actualState: [String: Any] = [
            "iconHiddenFontSize": iconHiddenSize ?? NSNull(),
            "icon16FontSize": icon16Size ?? NSNull(),
            "icon32FontSize": icon32Size ?? NSNull(),
            "icon48FontSize": icon48Size ?? NSNull(),
            "selectedPointFontSize": selectedPointSize ?? NSNull(),
            "verificationTitle": verificationItem.title,
            "verificationAction": verificationItem.action.map(NSStringFromSelector) ?? ""
        ]
        let expectedState: [String: Any] = [
            "iconHiddenFontSize": 14.0,
            "icon16FontSize": 14.0,
            "icon32FontSize": 28.0,
            "icon48FontSize": 42.0,
            "selectedPointFontSize": 16.0,
            "verificationTitle": "1. font-size-smoke",
            "verificationAction": "selectMenuItem:"
        ]

        let report: [String: Any] = [
            "iconHiddenFontSize": iconHiddenSize ?? NSNull(),
            "icon16FontSize": icon16Size ?? NSNull(),
            "icon32FontSize": icon32Size ?? NSNull(),
            "icon48FontSize": icon48Size ?? NSNull(),
            "selectedPointFontSize": selectedPointSize ?? NSNull(),
            "verificationTitle": verificationItem.title,
            "verificationAction": verificationItem.action.map(NSStringFromSelector) ?? "",
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpected": (actualState as NSDictionary).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

