    private func runDebugMenuFolderItemsNormalizationReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugMenuFolderItemsNormalizationReportPath")
            ?? "/tmp/clipmenu-menu-folder-items-normalization-report.json")
        let originalClips = clipsStore.clips
        let originalFolderItems = defaults.object(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        let originalInlineItems = defaults.object(forKey: CMPrefNumberOfItemsPlaceInlineKey)
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)
        let originalMarkNumbers = defaults.object(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        let originalStartsFromZero = defaults.object(forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        let originalShowLabels = defaults.object(forKey: CMPrefShowLabelsInMenuKey)

        defer {
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalFolderItems, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
            restoreDefault(originalInlineItems, forKey: CMPrefNumberOfItemsPlaceInlineKey)
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            restoreDefault(originalMarkNumbers, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
            restoreDefault(originalStartsFromZero, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
            restoreDefault(originalShowLabels, forKey: CMPrefShowLabelsInMenuKey)
            rebuildMenu()
            NSApp.terminate(nil)
        }

        defaults.set(0, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        defaults.set(0, forKey: CMPrefNumberOfItemsPlaceInlineKey)
        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        defaults.set(true, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        defaults.set(false, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        defaults.set(false, forKey: CMPrefShowLabelsInMenuKey)
        clipsStore.clear()
        ["alpha", "beta", "gamma"].enumerated().forEach { index, text in
            let seconds = TimeInterval((index + 1) * 100)
            clipsStore.add(
                ClipItem(
                    text: text,
                    createdAt: Date(timeIntervalSinceReferenceDate: seconds),
                    lastUsedAt: Date(timeIntervalSinceReferenceDate: seconds)
                )
            )
        }

        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))

        let historyMenu = makeHistoryMenu()
        let topLevelTitles = historyMenu.items.map(\.title)
        let actualState: [String: Any] = [
            "normalizedStoredFolderItems": defaults.integer(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey),
            "topLevelTitles": topLevelTitles
        ]
        let expectedState: [String: Any] = [
            "normalizedStoredFolderItems": 1,
            "topLevelTitles": ["1 - 1", "2 - 2", "3 - 3"]
        ]

        let report: [String: Any] = [
            "normalizedStoredFolderItems": defaults.integer(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey),
            "topLevelTitles": topLevelTitles,
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpected": (actualState as NSDictionary).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

