            "matchesExpected": NSDictionary(dictionary: actualState).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugHistoryMenuLayoutReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugHistoryMenuLayoutReportPath")
            ?? "/tmp/clipmenu-history-menu-layout-report.json")
        let originalClips = clipsStore.clips
        let snippetStore = SnippetFileStore.shared
        let originalSnippetFolders = snippetStore.folders
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)
        let originalInlineCount = defaults.object(forKey: CMPrefNumberOfItemsPlaceInlineKey)
        let originalFolderCount = defaults.object(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        let originalShowLabels = defaults.object(forKey: CMPrefShowLabelsInMenuKey)
        let originalMarkNumbers = defaults.object(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        let originalStartsFromZero = defaults.object(forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        let originalNumericKeys = defaults.object(forKey: CMPrefAddNumericKeyEquivalentsKey)
        let originalSnippetPosition = defaults.object(forKey: CMPrefPositionOfSnippetsKey)

        defer {
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            snippetStore.folders = originalSnippetFolders
            snippetStore.save()
            snippetStore.reload()
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            restoreDefault(originalInlineCount, forKey: CMPrefNumberOfItemsPlaceInlineKey)
            restoreDefault(originalFolderCount, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
            restoreDefault(originalShowLabels, forKey: CMPrefShowLabelsInMenuKey)
            restoreDefault(originalMarkNumbers, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
            restoreDefault(originalStartsFromZero, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
            restoreDefault(originalNumericKeys, forKey: CMPrefAddNumericKeyEquivalentsKey)
            restoreDefault(originalSnippetPosition, forKey: CMPrefPositionOfSnippetsKey)
            rebuildMenu()
            NSApp.terminate(nil)
        }

        defaults.set(8, forKey: CMPrefMaxHistorySizeKey)
        defaults.set(2, forKey: CMPrefNumberOfItemsPlaceInlineKey)
        defaults.set(3, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        defaults.set(false, forKey: CMPrefShowLabelsInMenuKey)
        defaults.set(true, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        defaults.set(false, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        defaults.set(false, forKey: CMPrefAddNumericKeyEquivalentsKey)

        clipsStore.clear()
        for index in 1...8 {
            clipsStore.add(
                ClipItem(
                    text: "menu-\(index)",
                    createdAt: Date(timeIntervalSinceReferenceDate: TimeInterval(index)),
                    lastUsedAt: Date(timeIntervalSinceReferenceDate: TimeInterval(index))
                )
            )
        }

        let orderedClipTexts = clipsStore.orderedClips.map(\.text)
        let maxHistorySize = max(0, defaults.integer(forKey: CMPrefMaxHistorySizeKey))
        let normalizedInlineCount = CMNormalizedLegacyMenuInlineItemsCount(
            defaults.integer(forKey: CMPrefNumberOfItemsPlaceInlineKey)
        )
        let normalizedFolderCount = CMNormalizedLegacyMenuFolderItemsCount(
            defaults.integer(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        )
        let historyMenu = makeHistoryMenu()
        let historyTopLevelTitles = historyMenu.items.map(\.title)
        let historySubmenuTitles = historyMenu.items.compactMap { item -> [String]? in
            item.submenu?.items.map(\.title)
        }
        let historySubmenuCounts = historyMenu.items.compactMap { $0.submenu?.items.count }

        snippetStore.folders = [
            SnippetFolder(
                title: "QA",
                isEnabled: true,
                snippets: [
                    Snippet(title: "Greeting", content: "Hello", isEnabled: true)
                ]
            )
        ]
        snippetStore.save()
        snippetStore.reload()
        defaults.set(CMPositionOfSnippets.aboveClips.rawValue, forKey: CMPrefPositionOfSnippetsKey)
        let mainMenu = makeMainMenu()
        let snippetSubmenuTitles = mainMenu.items.first(where: { $0.title == "QA" })?.submenu?.items.map(\.title) ?? []

        let expectedHistoryTopLevelTitles = [
            "1. menu-8",
            "2. menu-7",
            "3 - 5",
            "6 - 8"
        ]
        let expectedHistorySubmenuTitles = [
            ["1. menu-6", "2. menu-5", "3. menu-4"],
            ["1. menu-3", "2. menu-2", "3. menu-1"]
        ]
        let expectedSnippetSubmenuTitles = ["1. Greeting"]
        let actualState: [String: Any] = [
            "historyClipTexts": orderedClipTexts,
            "historyClipCount": orderedClipTexts.count,
            "maxHistorySize": maxHistorySize,
            "normalizedInlineCount": normalizedInlineCount,
            "normalizedFolderCount": normalizedFolderCount,
            "folderedHistoryTopLevelTitles": historyTopLevelTitles,
            "folderedHistorySubmenuTitles": historySubmenuTitles,
            "folderedHistorySubmenuCounts": historySubmenuCounts,
            "snippetSubmenuTitles": snippetSubmenuTitles
        ]
        let expectedState: [String: Any] = [
            "historyClipTexts": [
                "menu-8",
                "menu-7",
                "menu-6",
                "menu-5",
                "menu-4",
                "menu-3",
                "menu-2",
                "menu-1"
            ],
            "historyClipCount": 8,
            "maxHistorySize": 8,
            "normalizedInlineCount": 2,
            "normalizedFolderCount": 3,
            "folderedHistoryTopLevelTitles": expectedHistoryTopLevelTitles,
            "folderedHistorySubmenuTitles": expectedHistorySubmenuTitles,
            "folderedHistorySubmenuCounts": [3, 3],
            "snippetSubmenuTitles": expectedSnippetSubmenuTitles
        ]

        let report: [String: Any] = [
            "folderedHistoryTopLevelTitles": historyTopLevelTitles,
            "folderedHistorySubmenuTitles": historySubmenuTitles,
            "folderedHistorySubmenuCounts": historySubmenuCounts,
            "snippetSubmenuTitles": snippetSubmenuTitles,
            "state": actualState,
            "expectedState": expectedState,
            "folderedHistoryMatchesExpected": historyTopLevelTitles == expectedHistoryTopLevelTitles
                && historySubmenuTitles == expectedHistorySubmenuTitles
                && historySubmenuCounts == [3, 3],
            "numberedSnippetMatchesExpected": snippetSubmenuTitles == expectedSnippetSubmenuTitles,
            "matchesExpected": (actualState as NSDictionary).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugActionBehaviorReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugActionBehaviorReportPath")
            ?? "/tmp/clipmenu-action-behavior-report.json")
        let actionsURL = clipMenuApplicationSupportDirectory().appendingPathComponent("actions.plist")
        let originalActionData = try? Data(contentsOf: actionsURL)
        let originalClips = clipsStore.clips
        let originalEnableAction = defaults.object(forKey: CMPrefEnableActionKey)
        let originalInputPasteCommand = defaults.object(forKey: CMPrefInputPasteCommandKey)
        let originalShowTooltips = defaults.object(forKey: CMPrefShowToolTipOnMenuItemKey)
        let originalActionTarget = actionTarget

        defer {
            if let originalActionData {
                try? originalActionData.write(to: actionsURL, options: .atomic)
            } else {
                try? FileManager.default.removeItem(at: actionsURL)
            }
            CMReloadActionPreferences()
            actionTarget = originalActionTarget
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalEnableAction, forKey: CMPrefEnableActionKey)
            restoreDefault(originalInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            restoreDefault(originalShowTooltips, forKey: CMPrefShowToolTipOnMenuItemKey)
            rebuildMenu()
            NSApp.terminate(nil)
        }

        guard let fixtureData = actionBehaviorFixtureData() else {
            let report = ["error": "Could not construct action fixture"]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        defaults.set(true, forKey: CMPrefEnableActionKey)
        defaults.set(false, forKey: CMPrefInputPasteCommandKey)
        defaults.set(true, forKey: CMPrefShowToolTipOnMenuItemKey)

        try? fixtureData.write(to: actionsURL, options: .atomic)
        CMReloadActionPreferences()
        pasteboard.clearContents()
        clipsStore.clear()

        let textClip = ClipItem(
            types: [NSPasteboard.PasteboardType.string.rawValue, NSPasteboard.PasteboardType.rtf.rawValue],
            createdAt: Date(timeIntervalSinceReferenceDate: 100),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 100),
            text: "Styled Input"
        )
        let fileClip = ClipItem(
            types: [NSPasteboard.PasteboardType.clipMenuFilenames.rawValue],
            createdAt: Date(timeIntervalSinceReferenceDate: 200),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 200),
            text: "",
            filenames: ["/tmp/example-a.txt", "/tmp/example-b.txt"]
        )

        let snippetTarget = SnippetActionReference(
            folderID: UUID(),
            snippetID: UUID(),
            content: "Snippet body"
        )

        func actionTitles(for target: ActionTarget) -> [String] {
            actionTarget = target
            return flattenedActionTitles(from: makeActionMenu())
        }

        clipsStore.add(textClip)
        let textTitles = actionTitles(for: .clip(textClip.id))
        clipsStore.clear()

        clipsStore.add(fileClip)
        let fileTitles = actionTitles(for: .clip(fileClip.id))
        clipsStore.clear()

        let snippetTitles = actionTitles(for: .snippet(snippetTarget))

        clipsStore.clear()
        clipsStore.add(textClip)
        actionTarget = .clip(textClip.id)
        if let plainTextItem = menuItem(withTitle: NSLocalizedString("Paste as Plain Text", comment: ""), in: makeActionMenu()) {
            selectAction(plainTextItem)
        }
        let plainTextPasteboard = pasteboard.string(forType: .string) ?? ""

        clipsStore.clear()
        pasteboard.clearContents()
        clipsStore.add(fileClip)
        actionTarget = .clip(fileClip.id)
        if let posixItem = menuItem(withTitle: NSLocalizedString("Paste as File Path", comment: ""), in: makeActionMenu()) {
            selectAction(posixItem)
        }
        let posixPasteboard = pasteboard.string(forType: .string) ?? ""

        pasteboard.clearContents()
        actionTarget = .clip(fileClip.id)
        if let hfsItem = menuItem(withTitle: NSLocalizedString("Paste as HFS File Path", comment: ""), in: makeActionMenu()) {
            selectAction(hfsItem)
        }
        let hfsPasteboard = pasteboard.string(forType: .string) ?? ""

        clipsStore.clear()
        clipsStore.add(textClip)
        let countBeforeRemove = clipsStore.orderedClips.count
        actionTarget = .clip(textClip.id)
        if let removeItem = menuItem(withTitle: NSLocalizedString("Remove", comment: ""), in: makeActionMenu()) {
            selectAction(removeItem)
        }
        let countAfterRemove = clipsStore.orderedClips.count

        let plainTextTitle = NSLocalizedString("Paste as Plain Text", comment: "")
        let filePathTitle = NSLocalizedString("Paste as File Path", comment: "")
        let hfsPathTitle = NSLocalizedString("Paste as HFS File Path", comment: "")
        let removeTitle = NSLocalizedString("Remove", comment: "")
        let jsTitle = "UPPERCASE.js"
        let actionBehaviorMatchesExpected = textTitles.contains(plainTextTitle)
            && textTitles.contains(removeTitle)
            && textTitles.contains(jsTitle)
            && !textTitles.contains(filePathTitle)
            && !textTitles.contains(hfsPathTitle)
            && fileTitles.contains(filePathTitle)
            && fileTitles.contains(hfsPathTitle)
            && fileTitles.contains(removeTitle)
            && !fileTitles.contains(plainTextTitle)
            && !fileTitles.contains(jsTitle)
            && snippetTitles.contains(plainTextTitle)
            && snippetTitles.contains(removeTitle)
            && snippetTitles.contains(jsTitle)
            && !snippetTitles.contains(filePathTitle)
            && !snippetTitles.contains(hfsPathTitle)
            && plainTextPasteboard == "Styled Input"
            && posixPasteboard == "/tmp/example-a.txt\n/tmp/example-b.txt"
            && !hfsPasteboard.isEmpty
            && countBeforeRemove == 1
            && countAfterRemove == 0

        let report: [String: Any] = [
            "textActionTitles": textTitles,
            "fileActionTitles": fileTitles,
            "snippetActionTitles": snippetTitles,
            "textFilteringMatchesExpected": textTitles.contains(plainTextTitle)
                && textTitles.contains(removeTitle)
                && textTitles.contains(jsTitle)
                && !textTitles.contains(filePathTitle)
                && !textTitles.contains(hfsPathTitle),
            "fileFilteringMatchesExpected": fileTitles.contains(filePathTitle)
                && fileTitles.contains(hfsPathTitle)
                && fileTitles.contains(removeTitle)
                && !fileTitles.contains(plainTextTitle)
                && !fileTitles.contains(jsTitle),
            "snippetFilteringMatchesExpected": snippetTitles.contains(plainTextTitle)
                && snippetTitles.contains(removeTitle)
                && snippetTitles.contains(jsTitle)
                && !snippetTitles.contains(filePathTitle)
                && !snippetTitles.contains(hfsPathTitle),
            "plainTextPasteboard": plainTextPasteboard,
            "plainTextInvocationMatchesExpected": plainTextPasteboard == "Styled Input",
            "posixPasteboard": posixPasteboard,
            "posixInvocationMatchesExpected": posixPasteboard == "/tmp/example-a.txt\n/tmp/example-b.txt",
            "hfsPasteboard": hfsPasteboard,
            "hfsInvocationMatchesExpected": !hfsPasteboard.isEmpty && hfsPasteboard.contains("example-a.txt") && hfsPasteboard.contains("example-b.txt"),
            "removeCountBefore": countBeforeRemove,
            "removeCountAfter": countAfterRemove,
            "removeInvocationMatchesExpected": countBeforeRemove == 1 && countAfterRemove == 0,
            "actionBehaviorMatchesExpected": actionBehaviorMatchesExpected,
            "matchesExpected": actionBehaviorMatchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugModifiedClickBehaviorReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugModifiedClickBehaviorReportPath")
            ?? "/tmp/clipmenu-modified-click-behavior-report.json")
        let actionsURL = clipMenuApplicationSupportDirectory().appendingPathComponent("actions.plist")
        let originalActionData = try? Data(contentsOf: actionsURL)
        let originalClips = clipsStore.clips
        let originalEnableAction = defaults.object(forKey: CMPrefEnableActionKey)
        let originalInvokeImmediate = defaults.object(forKey: CMPrefInvokeActionImmediatelyKey)
        let originalControlBehavior = defaults.object(forKey: CMPrefContorlClickBehaviorKey)
        let originalShiftBehavior = defaults.object(forKey: CMPrefShiftClickBehaviorKey)
        let originalOptionBehavior = defaults.object(forKey: CMPrefOptionClickBehaviorKey)
        let originalCommandBehavior = defaults.object(forKey: CMPrefCommandClickBehaviorKey)
        let originalInputPasteCommand = defaults.object(forKey: CMPrefInputPasteCommandKey)
        let originalActionTarget = actionTarget
        let originalPopupFlags = lastPopupInteractionFlags
        let originalPopupType = lastPopupInteractionType
        let originalDebugCapturePopupMenus = debugCapturePopupMenus
        let originalDebugCapturedPopupMenuSummaries = debugCapturedPopupMenuSummaries

        defer {
            if let originalActionData {
                try? originalActionData.write(to: actionsURL, options: .atomic)
            } else {
                try? FileManager.default.removeItem(at: actionsURL)
            }
            CMReloadActionPreferences()
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalEnableAction, forKey: CMPrefEnableActionKey)
            restoreDefault(originalInvokeImmediate, forKey: CMPrefInvokeActionImmediatelyKey)
            restoreDefault(originalControlBehavior, forKey: CMPrefContorlClickBehaviorKey)
            restoreDefault(originalShiftBehavior, forKey: CMPrefShiftClickBehaviorKey)
            restoreDefault(originalOptionBehavior, forKey: CMPrefOptionClickBehaviorKey)
            restoreDefault(originalCommandBehavior, forKey: CMPrefCommandClickBehaviorKey)
            restoreDefault(originalInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            actionTarget = originalActionTarget
            lastPopupInteractionFlags = originalPopupFlags
            lastPopupInteractionType = originalPopupType
            debugCapturePopupMenus = originalDebugCapturePopupMenus
            debugCapturedPopupMenuSummaries = originalDebugCapturedPopupMenuSummaries
            rebuildMenu()
            NSApp.terminate(nil)
        }

        guard let uppercaseNode = runtimeBundledScriptNode(relativePath: "Case/UPPERCASE.js", includeExtensionInTitle: true),
          let uppercaseAction = uppercaseNode.action,
              let singleRemoveData = singleRemoveActionFixtureData(),
              let singleFolderData = singleFolderActionFixtureData() else {
            let report = ["error": "Could not construct modified-click fixture"]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        func simulateModifiedSelection(
            clip: ClipItem,
            flags: NSEvent.ModifierFlags,
            type: NSEvent.EventType = .leftMouseUp
        ) -> NSMenuItem {
            clipsStore.clear()
            clipsStore.add(clip)
            pasteboard.clearContents()
            lastPopupInteractionFlags = flags
            lastPopupInteractionType = type
            let item = makeClipMenuItem(clip: clip, globalIndex: 0, listNumber: 1)
            selectClip(item)
            return item
        }

        let styledClip = ClipItem(
            types: [NSPasteboard.PasteboardType.string.rawValue, NSPasteboard.PasteboardType.rtf.rawValue],
            createdAt: Date(timeIntervalSinceReferenceDate: 100),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 100),
            text: "Styled Input"
        )

        defaults.set(false, forKey: CMPrefInputPasteCommandKey)

        defaults.set(false, forKey: CMPrefEnableActionKey)
        defaults.set(["type": "builtin", "name": "remove:"] as NSDictionary, forKey: CMPrefShiftClickBehaviorKey)
        let disabledItem = simulateModifiedSelection(clip: styledClip, flags: [.shift])
        let disabledPasteboard = pasteboard.string(forType: .string) ?? ""
        let disabledCountAfter = clipsStore.orderedClips.count

        defaults.set(true, forKey: CMPrefEnableActionKey)
        defaults.set("popUpActionMenu", forKey: CMPrefContorlClickBehaviorKey)
        defaults.set(true, forKey: CMPrefInvokeActionImmediatelyKey)
        try? singleRemoveData.write(to: actionsURL, options: .atomic)
        CMReloadActionPreferences()
        let immediateItem = simulateModifiedSelection(clip: styledClip, flags: [.control], type: .rightMouseUp)
        let immediatePasteboard = pasteboard.string(forType: .string) ?? ""
        let immediateCountAfter = clipsStore.orderedClips.count

        debugCapturePopupMenus = true
        debugCapturedPopupMenuSummaries.removeAll()
        defaults.set(true, forKey: CMPrefInvokeActionImmediatelyKey)
        try? singleFolderData.write(to: actionsURL, options: .atomic)
        CMReloadActionPreferences()
        let folderImmediateItem = simulateModifiedSelection(clip: styledClip, flags: [.control], type: .rightMouseUp)
        let folderImmediatePasteboard = pasteboard.string(forType: .string) ?? ""
        let folderImmediateCountAfter = clipsStore.orderedClips.count
        let folderImmediateCapturedPopupCount = debugCapturedPopupMenuSummaries.count
        debugCapturePopupMenus = false
        debugCapturedPopupMenuSummaries.removeAll()

        defaults.set(["type": "builtin", "name": "remove:"] as NSDictionary, forKey: CMPrefShiftClickBehaviorKey)
        defaults.set(["type": "builtin", "name": "pasteAsPlainText:"] as NSDictionary, forKey: CMPrefOptionClickBehaviorKey)
        defaults.set(uppercaseAction as NSDictionary, forKey: CMPrefCommandClickBehaviorKey)
        defaults.set(false, forKey: CMPrefInvokeActionImmediatelyKey)

        _ = simulateModifiedSelection(clip: styledClip, flags: [.shift])
        let shiftCountAfter = clipsStore.orderedClips.count

        _ = simulateModifiedSelection(clip: styledClip, flags: [.option])
        let optionPasteboard = pasteboard.string(forType: .string) ?? ""
        let optionCountAfter = clipsStore.orderedClips.count

        _ = simulateModifiedSelection(clip: styledClip, flags: [.command])
        let commandPasteboard = pasteboard.string(forType: .string) ?? ""
        let commandCountAfter = clipsStore.orderedClips.count
        let modifiedClickBehaviorMatchesExpected = disabledPasteboard == "Styled Input"
            && disabledCountAfter == 1
            && immediatePasteboard.isEmpty
            && immediateCountAfter == 0
            && folderImmediatePasteboard.isEmpty
            && folderImmediateCountAfter == 1
            && folderImmediateCapturedPopupCount == 0
            && shiftCountAfter == 0
            && optionPasteboard == "Styled Input"
            && optionCountAfter == 1
            && commandPasteboard == "STYLED INPUT"
            && commandCountAfter == 1

        let report: [String: Any] = [
            "disabledActionsItemTitle": disabledItem.title,
            "disabledActionsPasteboard": disabledPasteboard,
            "disabledActionsClipCountAfter": disabledCountAfter,
            "disabledActionsMatchesExpected": disabledPasteboard == "Styled Input" && disabledCountAfter == 1,
            "immediateActionItemTitle": immediateItem.title,
            "immediateActionPasteboard": immediatePasteboard,
            "immediateActionClipCountAfter": immediateCountAfter,
            "immediateActionMatchesExpected": immediatePasteboard.isEmpty && immediateCountAfter == 0,
            "folderImmediateActionItemTitle": folderImmediateItem.title,
            "folderImmediateActionPasteboard": folderImmediatePasteboard,
            "folderImmediateActionClipCountAfter": folderImmediateCountAfter,
            "folderImmediateCapturedPopupCount": folderImmediateCapturedPopupCount,
            "folderImmediateActionMatchesExpected": folderImmediatePasteboard.isEmpty
                && folderImmediateCountAfter == 1
                && folderImmediateCapturedPopupCount == 0,
            "shiftActionClipCountAfter": shiftCountAfter,
            "shiftActionMatchesExpected": shiftCountAfter == 0,
            "optionActionPasteboard": optionPasteboard,
            "optionActionClipCountAfter": optionCountAfter,
            "optionActionMatchesExpected": optionPasteboard == "Styled Input" && optionCountAfter == 1,
            "commandActionPasteboard": commandPasteboard,
            "commandActionClipCountAfter": commandCountAfter,
            "commandActionMatchesExpected": commandPasteboard == "STYLED INPUT" && commandCountAfter == 1,
            "modifiedClickBehaviorMatchesExpected": modifiedClickBehaviorMatchesExpected,
            "matchesExpected": modifiedClickBehaviorMatchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugPasteSelectionBehaviorReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugPasteSelectionBehaviorReportPath")
            ?? "/tmp/clipmenu-paste-selection-behavior-report.json")
        let actionsURL = clipMenuApplicationSupportDirectory().appendingPathComponent("actions.plist")
        let originalActionData = try? Data(contentsOf: actionsURL)
        let originalClips = clipsStore.clips
        let originalInputPasteCommand = defaults.object(forKey: CMPrefInputPasteCommandKey)
        let originalEnableAction = defaults.object(forKey: CMPrefEnableActionKey)
        let originalActionTarget = actionTarget

        defer {
            if let originalActionData {
                try? originalActionData.write(to: actionsURL, options: .atomic)
            } else {
                try? FileManager.default.removeItem(at: actionsURL)
            }
            CMReloadActionPreferences()
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            restoreDefault(originalInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            restoreDefault(originalEnableAction, forKey: CMPrefEnableActionKey)
            actionTarget = originalActionTarget
            debugResetPasteSynthesisTracking()
            rebuildMenu()
            NSApp.terminate(nil)
        }

        guard let fixtureData = actionBehaviorFixtureData() else {
            let report = ["error": "Could not construct paste selection fixture"]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        let clip = ClipItem(
            types: [NSPasteboard.PasteboardType.string.rawValue],
            createdAt: Date(timeIntervalSinceReferenceDate: 100),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 100),
            text: "Paste Flow Input"
        )

        defaults.set(false, forKey: CMPrefEnableActionKey)
        clipsStore.clear()
        clipsStore.add(clip)
        pasteboard.clearContents()

        defaults.set(false, forKey: CMPrefInputPasteCommandKey)
        debugResetPasteSynthesisTracking()
        let disabledPasteItem = makeClipMenuItem(clip: clip, globalIndex: 0, listNumber: 1)
        selectClip(disabledPasteItem)
        let disabledPasteboard = pasteboard.string(forType: .string) ?? ""
        let disabledSynthesisCount = debugPasteSynthesisRequestCount
        let disabledSynthesisSource = debugLastPasteSynthesisSource

        defaults.set(true, forKey: CMPrefInputPasteCommandKey)
        debugResetPasteSynthesisTracking()
        let enabledPasteItem = makeClipMenuItem(clip: clip, globalIndex: 0, listNumber: 1)
        selectClip(enabledPasteItem)
        let enabledPasteboard = pasteboard.string(forType: .string) ?? ""
        let enabledSynthesisCount = debugPasteSynthesisRequestCount
        let enabledSynthesisSource = debugLastPasteSynthesisSource

        defaults.set(true, forKey: CMPrefEnableActionKey)
        try? fixtureData.write(to: actionsURL, options: .atomic)
        CMReloadActionPreferences()
        clipsStore.clear()
        clipsStore.add(clip)
        pasteboard.clearContents()
        actionTarget = .clip(clip.id)
        debugResetPasteSynthesisTracking()
        if let actionItem = menuItem(withTitle: NSLocalizedString("Paste as Plain Text", comment: ""), in: makeActionMenu()) {
            selectAction(actionItem)
        }
        let actionPasteboard = pasteboard.string(forType: .string) ?? ""
        let actionSynthesisCount = debugPasteSynthesisRequestCount
        let actionSynthesisSource = debugLastPasteSynthesisSource

        let richScratchPasteboard = NSPasteboard(name: NSPasteboard.Name("clipmenu-debug-richSelection-\(UUID().uuidString)"))
        let richSelectionString: String
        let richSelectionHasRTFType: Bool
        let richSelectionRTFLength: Int
        let richSelectionSynthesisCount: Int
        let richSelectionSynthesisSource: String
        let richSelectionMatchesExpected: Bool

        if writeDebugRTFPasteboard(richScratchPasteboard),
           let richClip = capturedClip(from: richScratchPasteboard, frontmostBundleIdentifier: nil) {
            defaults.set(false, forKey: CMPrefEnableActionKey)
            defaults.set(false, forKey: CMPrefInputPasteCommandKey)
            clipsStore.clear()
            clipsStore.add(richClip)
            pasteboard.clearContents()
            debugResetPasteSynthesisTracking()
            let richPasteItem = makeClipMenuItem(clip: richClip, globalIndex: 0, listNumber: 1)
            selectClip(richPasteItem)

            richSelectionString = pasteboard.string(forType: .string) ?? ""
            let richRTFData = pasteboard.data(forType: .rtf)
            richSelectionHasRTFType = pasteboard.types?.contains(.rtf) == true
            richSelectionRTFLength = richRTFData?.count ?? 0
            richSelectionSynthesisCount = debugPasteSynthesisRequestCount
            richSelectionSynthesisSource = debugLastPasteSynthesisSource

            if let richRTFData,
               let attributed = NSAttributedString(rtf: richRTFData, documentAttributes: nil) {
                richSelectionMatchesExpected = richSelectionString == "Rich Smoke"
                    && attributed.string == "Rich Smoke"
                    && richSelectionHasRTFType
                    && richSelectionRTFLength > 0
                    && richSelectionSynthesisCount == 0
            } else {
                richSelectionMatchesExpected = false
            }
        } else {
            richSelectionString = ""
            richSelectionHasRTFType = false
            richSelectionRTFLength = 0
            richSelectionSynthesisCount = 0
            richSelectionSynthesisSource = ""
            richSelectionMatchesExpected = false
        }

        let richDirectoryScratchPasteboard = NSPasteboard(name: NSPasteboard.Name("clipmenu-debug-richDirectorySelection-\(UUID().uuidString)"))
        let richDirectorySelectionString: String
        let richDirectorySelectionHasRTFDType: Bool
        let richDirectorySelectionRTFDLength: Int
        let richDirectorySelectionSynthesisCount: Int
        let richDirectorySelectionSynthesisSource: String
        let richDirectorySelectionMatchesExpected: Bool

        if writeDebugRTFDPasteboard(richDirectoryScratchPasteboard),
           let richDirectoryClip = capturedClip(from: richDirectoryScratchPasteboard, frontmostBundleIdentifier: nil) {
            defaults.set(false, forKey: CMPrefEnableActionKey)
            defaults.set(false, forKey: CMPrefInputPasteCommandKey)
            clipsStore.clear()
            clipsStore.add(richDirectoryClip)
            pasteboard.clearContents()
            debugResetPasteSynthesisTracking()
            let richDirectoryPasteItem = makeClipMenuItem(clip: richDirectoryClip, globalIndex: 0, listNumber: 1)
            selectClip(richDirectoryPasteItem)

            richDirectorySelectionString = pasteboard.string(forType: .string) ?? ""
            let richDirectoryData = pasteboard.data(forType: .rtfd)
            richDirectorySelectionHasRTFDType = pasteboard.types?.contains(.rtfd) == true
            richDirectorySelectionRTFDLength = richDirectoryData?.count ?? 0
            richDirectorySelectionSynthesisCount = debugPasteSynthesisRequestCount
            richDirectorySelectionSynthesisSource = debugLastPasteSynthesisSource

            if let richDirectoryData,
               let attributed = NSAttributedString(rtfd: richDirectoryData, documentAttributes: nil) {
                richDirectorySelectionMatchesExpected = richDirectorySelectionString == "Rich Directory Smoke"
                    && attributed.string == "Rich Directory Smoke"
                    && richDirectorySelectionHasRTFDType
                    && richDirectorySelectionRTFDLength > 0
                    && richDirectorySelectionSynthesisCount == 0
            } else {
                richDirectorySelectionMatchesExpected = false
            }
        } else {
            richDirectorySelectionString = ""
            richDirectorySelectionHasRTFDType = false
            richDirectorySelectionRTFDLength = 0
            richDirectorySelectionSynthesisCount = 0
            richDirectorySelectionSynthesisSource = ""
            richDirectorySelectionMatchesExpected = false
        }
        let pasteSelectionBehaviorMatchesExpected = disabledPasteboard == "Paste Flow Input"
            && disabledSynthesisCount == 0
            && enabledPasteboard == "Paste Flow Input"
            && enabledSynthesisCount == 1
            && enabledSynthesisSource == "selection"
            && actionPasteboard == "Paste Flow Input"
            && actionSynthesisCount == 1
            && actionSynthesisSource == "action"
            && richSelectionMatchesExpected
            && richDirectorySelectionMatchesExpected

        let report: [String: Any] = [
            "clipSelectionAutoPasteDisabledPasteboard": disabledPasteboard,
            "clipSelectionAutoPasteDisabledSynthesisCount": disabledSynthesisCount,
            "clipSelectionAutoPasteDisabledSynthesisSource": disabledSynthesisSource,
            "clipSelectionAutoPasteDisabledMatchesExpected": disabledPasteboard == "Paste Flow Input"
                && disabledSynthesisCount == 0,
            "clipSelectionAutoPasteEnabledPasteboard": enabledPasteboard,
            "clipSelectionAutoPasteEnabledSynthesisCount": enabledSynthesisCount,
            "clipSelectionAutoPasteEnabledSynthesisSource": enabledSynthesisSource,
            "clipSelectionAutoPasteEnabledMatchesExpected": enabledPasteboard == "Paste Flow Input"
                && enabledSynthesisCount == 1
                && enabledSynthesisSource == "selection",
            "actionPasteboard": actionPasteboard,
            "actionSynthesisCount": actionSynthesisCount,
            "actionSynthesisSource": actionSynthesisSource,
            "actionPasteMatchesExpected": actionPasteboard == "Paste Flow Input"
                && actionSynthesisCount == 1
                && actionSynthesisSource == "action",
            "richTextSelectionPasteboardString": richSelectionString,
            "richTextSelectionPasteboardHasRTFType": richSelectionHasRTFType,
            "richTextSelectionPasteboardRTFLength": richSelectionRTFLength,
            "richTextSelectionSynthesisCount": richSelectionSynthesisCount,
            "richTextSelectionSynthesisSource": richSelectionSynthesisSource,
            "richTextSelectionMatchesExpected": richSelectionMatchesExpected,
            "richDirectorySelectionPasteboardString": richDirectorySelectionString,
            "richDirectorySelectionPasteboardHasRTFDType": richDirectorySelectionHasRTFDType,
            "richDirectorySelectionPasteboardRTFDLength": richDirectorySelectionRTFDLength,
            "richDirectorySelectionSynthesisCount": richDirectorySelectionSynthesisCount,
            "richDirectorySelectionSynthesisSource": richDirectorySelectionSynthesisSource,
            "richDirectorySelectionMatchesExpected": richDirectorySelectionMatchesExpected,
            "pasteSelectionBehaviorMatchesExpected": pasteSelectionBehaviorMatchesExpected,
            "matchesExpected": pasteSelectionBehaviorMatchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugHotKeyCustomizationReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugHotKeyCustomizationReportPath")
            ?? "/tmp/clipmenu-hotkey-customization-report.json")
        let originalPersistentDomain = Bundle.main.bundleIdentifier.flatMap { defaults.persistentDomain(forName: $0) }

        defer {
            unregisterHotKey()
            if let bundleIdentifier = Bundle.main.bundleIdentifier {
                if let originalPersistentDomain {
                    defaults.setPersistentDomain(originalPersistentDomain, forName: bundleIdentifier)
                } else {
                    defaults.removePersistentDomain(forName: bundleIdentifier)
                }
            }
            AppController.registerDefaults()
            AppController.migrateLegacyHotKeyDefaultsIfNeeded()
            registerHotKey()
            NSApp.terminate(nil)
        }

        guard let bundleIdentifier = Bundle.main.bundleIdentifier else {
            let report: [String: Any] = ["error": "Missing bundle identifier", "matchesExpected": false]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        unregisterHotKey()

        let baselineDomain: [String: Any] = [
            CMPrefLegacyHotKeysKey: [
                "ClipMenu": [
                    "keyCode": 9,
                    "modifiers": cmdKey | shiftKey
                ],
                "HistoryMenu": [
                    "keyCode": 9,
                    "modifiers": cmdKey | controlKey
                ],
                "SnippetsMenu": [
                    "keyCode": 11,
                    "modifiers": cmdKey | shiftKey
                ]
            ]
        ]
        defaults.setPersistentDomain(baselineDomain, forName: bundleIdentifier)
        AppController.registerDefaults()
        AppController.migrateLegacyHotKeyDefaultsIfNeeded()
        registerHotKey()

        let beforeRefs = debugHotKeyRefAddresses()
        let beforeGeneration = hotKeyRegistrationGeneration
        let beforeIDs = hotKeyRefs.keys.sorted()

        defaults.set(8, forKey: CMPrefHotKeyKeyCodeKey)
        defaults.set(Int(NSEvent.ModifierFlags([.command, .option]).rawValue), forKey: CMPrefHotKeyModifierFlagsKey)
        defaults.set(7, forKey: CMPrefSnippetsHotKeyKeyCodeKey)
        defaults.set(Int(NSEvent.ModifierFlags([.command, .control]).rawValue), forKey: CMPrefSnippetsHotKeyModifierFlagsKey)
        registerHotKey()

        let afterRefs = debugHotKeyRefAddresses()
        let afterGeneration = hotKeyRegistrationGeneration
        let afterIDs = hotKeyRefs.keys.sorted()
        let historyDefaults: [String: Any] = [
            "enabled": defaults.bool(forKey: CMPrefHistoryHotKeyEnabledKey),
            "keyCode": defaults.integer(forKey: CMPrefHistoryHotKeyKeyCodeKey),
            "modifierFlags": defaults.integer(forKey: CMPrefHistoryHotKeyModifierFlagsKey)
        ]
        let visibleDefaults: [String: Any] = [
            "clipMenuKeyCode": defaults.integer(forKey: CMPrefHotKeyKeyCodeKey),
            "clipMenuModifierFlags": defaults.integer(forKey: CMPrefHotKeyModifierFlagsKey),
            "snippetsKeyCode": defaults.integer(forKey: CMPrefSnippetsHotKeyKeyCodeKey),
            "snippetsModifierFlags": defaults.integer(forKey: CMPrefSnippetsHotKeyModifierFlagsKey)
        ]
        let customizationMatchesExpected = beforeIDs == HotKeyKind.allCases.map(\.rawValue).sorted()
            && afterIDs == HotKeyKind.allCases.map(\.rawValue).sorted()
            && defaults.integer(forKey: CMPrefHotKeyKeyCodeKey) == 8
            && defaults.integer(forKey: CMPrefSnippetsHotKeyKeyCodeKey) == 7
            && defaults.integer(forKey: CMPrefHistoryHotKeyKeyCodeKey) == 9
            && hotKeyRefs[HotKeyKind.historyMenu.rawValue] != nil
            && afterGeneration > beforeGeneration

        let report: [String: Any] = [
            "beforeRegisteredHotKeyIDs": beforeIDs,
            "beforeHotKeyRefs": beforeRefs,
            "afterRegisteredHotKeyIDs": afterIDs,
            "afterHotKeyRefs": afterRefs,
            "beforeHotKeyRegistrationGeneration": beforeGeneration,
            "afterHotKeyRegistrationGeneration": afterGeneration,
            "visibleShortcutDefaultsAfterCustomization": visibleDefaults,
            "historyShortcutDefaultsAfterCustomization": historyDefaults,
            "historyHotKeyStillRegistered": hotKeyRefs[HotKeyKind.historyMenu.rawValue] != nil,
            "allHotKeysRegisteredAfterCustomization": afterIDs == HotKeyKind.allCases.map(\.rawValue).sorted(),
            "visibleHotKeysChanged": defaults.integer(forKey: CMPrefHotKeyKeyCodeKey) == 8
                && defaults.integer(forKey: CMPrefSnippetsHotKeyKeyCodeKey) == 7,
            "hotKeyRefsRecreated": beforeRefs != afterRefs,
            "hotKeyRegistrationAdvanced": afterGeneration > beforeGeneration,
            "customizationMatchesExpected": customizationMatchesExpected,
            "matchesExpected": customizationMatchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugHotKeyMenuPresentationReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugHotKeyMenuPresentationReportPath")
            ?? "/tmp/clipmenu-hotkey-menu-presentation-report.json")
        let originalPersistentDomain = Bundle.main.bundleIdentifier.flatMap { defaults.persistentDomain(forName: $0) }
        let originalSnippetFolders = SnippetFileStore.shared.folders

        defer {
#if DEBUG
            debugCapturePopupMenus = false
            debugCapturedPopupMenuSummaries.removeAll()
#endif
            if let bundleIdentifier = Bundle.main.bundleIdentifier {
                if let originalPersistentDomain {
                    defaults.setPersistentDomain(originalPersistentDomain, forName: bundleIdentifier)
                } else {
                    defaults.removePersistentDomain(forName: bundleIdentifier)
                }
            }
            SnippetFileStore.shared.folders = originalSnippetFolders
            SnippetFileStore.shared.save()
            SnippetFileStore.shared.reload()
            clipsStore.load()
            configureStatusItem()
            rebuildMenu()
            NSApp.terminate(nil)
        }

        defaults.set(true, forKey: CMPrefAddClearHistoryMenuItemKey)
        defaults.set(false, forKey: CMPrefShowLabelsInMenuKey)
        defaults.set(true, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        defaults.set(false, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        defaults.set(false, forKey: CMPrefAddNumericKeyEquivalentsKey)
        defaults.set(1, forKey: CMPrefMaxHistorySizeKey)
        defaults.set(10, forKey: CMPrefNumberOfItemsPlaceInlineKey)
        defaults.set(10, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        defaults.set(CMPositionOfSnippets.belowClips.rawValue, forKey: CMPrefPositionOfSnippetsKey)
        defaults.set(1, forKey: CMPrefShowStatusItemKey)

        clipsStore.clear()
        clipsStore.add(ClipItem(text: "hotkey-clip"))

        let snippetStore = SnippetFileStore.shared
        snippetStore.folders = [
            SnippetFolder(
                title: "Hotkey Snippets",
                isEnabled: true,
                snippets: [
                    Snippet(title: "Hotkey Greeting", content: "Hello from hotkey", isEnabled: true)
                ]
            )
        ]
        snippetStore.save()
        snippetStore.reload()
        configureStatusItem()
        rebuildMenu()

#if DEBUG
        debugCapturePopupMenus = true
        debugCapturedPopupMenuSummaries.removeAll()
#endif

        let beforeAttachedMenuTitle = statusItem?.menu?.title ?? ""
        showMenu(for: .mainMenu)
#if DEBUG
        let mainCapture = debugCapturedPopupMenuSummaries.last ?? [:]
#else
        let mainCapture: [String: Any] = [:]
#endif
        let afterMainAttachedMenuTitle = statusItem?.menu?.title ?? ""

        showMenu(for: .historyMenu)
#if DEBUG
        let historyCapture = debugCapturedPopupMenuSummaries.last ?? [:]
#else
        let historyCapture: [String: Any] = [:]
#endif
        let afterHistoryAttachedMenuTitle = statusItem?.menu?.title ?? ""

        showMenu(for: .snippetsMenu)
#if DEBUG
        let snippetsCapture = debugCapturedPopupMenuSummaries.last ?? [:]
#else
        let snippetsCapture: [String: Any] = [:]
#endif
        let afterSnippetsAttachedMenuTitle = statusItem?.menu?.title ?? ""

        let mainTopLevelTitles = mainCapture["topLevelTitles"] as? [String] ?? []
        let historyTopLevelTitles = historyCapture["topLevelTitles"] as? [String] ?? []
        let snippetsTopLevelTitles = snippetsCapture["topLevelTitles"] as? [String] ?? []
        let snippetsSubmenuTitlesByParent = snippetsCapture["submenuTitlesByParent"] as? [String: [String]] ?? [:]

        let expectedMainTopLevelTitles = [
            "1. hotkey-clip",
            "<separator>",
            "Hotkey Snippets",
            "<separator>",
            NSLocalizedString("Clear History", comment: ""),
            NSLocalizedString("Edit Snippets...", comment: ""),
            NSLocalizedString("Preferences...", comment: ""),
            "<separator>",
            NSLocalizedString("Quit ClipMenu", comment: "")
        ]
        let expectedHistoryTopLevelTitles = ["1. hotkey-clip"]
        let expectedSnippetsTopLevelTitles = ["Hotkey Snippets"]
        let expectedSnippetSubmenuTitles = ["1. Hotkey Greeting"]
        let capturedPopupCount: Int
#if DEBUG
        capturedPopupCount = debugCapturedPopupMenuSummaries.count
#else
        capturedPopupCount = 0
#endif
        let allHotKeyMenusMatchExpected = mainTopLevelTitles == expectedMainTopLevelTitles
            && historyTopLevelTitles == expectedHistoryTopLevelTitles
            && snippetsTopLevelTitles == expectedSnippetsTopLevelTitles
            && snippetsSubmenuTitlesByParent["Hotkey Snippets"] == expectedSnippetSubmenuTitles
            && afterMainAttachedMenuTitle == "ClipMenu"

        let report: [String: Any] = [
            "beforeAttachedStatusMenuTitle": beforeAttachedMenuTitle,
            "afterMainAttachedStatusMenuTitle": afterMainAttachedMenuTitle,
            "afterHistoryAttachedStatusMenuTitle": afterHistoryAttachedMenuTitle,
            "afterSnippetsAttachedStatusMenuTitle": afterSnippetsAttachedMenuTitle,
            "capturedPopupCount": capturedPopupCount,
            "mainHotKeyMenu": mainCapture,
            "historyHotKeyMenu": historyCapture,
            "snippetsHotKeyMenu": snippetsCapture,
            "mainHotKeyShowsExpectedSurface": mainTopLevelTitles == expectedMainTopLevelTitles
                && afterMainAttachedMenuTitle == "ClipMenu",
            "historyHotKeyShowsExpectedSurface": historyTopLevelTitles == expectedHistoryTopLevelTitles
                && !historyTopLevelTitles.contains("Clear History"),
            "snippetsHotKeyShowsExpectedSurface": snippetsTopLevelTitles == expectedSnippetsTopLevelTitles
                && snippetsSubmenuTitlesByParent["Hotkey Snippets"] == expectedSnippetSubmenuTitles,
            "allHotKeyMenusMatchExpected": allHotKeyMenusMatchExpected,
            "matchesExpected": allHotKeyMenusMatchExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

