    private func runDebugLaunchSurfaceReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugLaunchSurfaceReportPath")
            ?? "/tmp/clipmenu-launch-surface-report.json")
        let visibleWindows = NSApp.windows.filter(\.isVisible)
        let visibleWindowTitles = visibleWindows.map(\.title)
        let visibleWindowClassNames = visibleWindows.map { NSStringFromClass(type(of: $0)) }
        let appVisibleWindows = visibleWindows.filter { window in
            let className = NSStringFromClass(type(of: window))
            return !className.localizedCaseInsensitiveContains("StatusBar")
                && !window.title.hasPrefix("Item-")
        }
        let appVisibleWindowTitles = appVisibleWindows.map(\.title)
        let orderedVisibleWindowTitles = NSApp.orderedWindows
            .filter(\.isVisible)
            .map(\.title)
        let activationPolicy: String
        switch NSApp.activationPolicy() {
        case .regular:
            activationPolicy = "regular"
        case .accessory:
            activationPolicy = "accessory"
        case .prohibited:
            activationPolicy = "prohibited"
        @unknown default:
            activationPolicy = "unknown"
        }

        let bundleLSUIElementValue = Bundle.main.object(forInfoDictionaryKey: "LSUIElement")
        let bundleLSUIElement = (bundleLSUIElementValue as? NSNumber)?.intValue
            ?? (bundleLSUIElementValue as? NSString)?.integerValue
        let expectedVisibleWindowTitles = ["Item-0"]
        let expectedVisibleWindowClassNames = ["NSStatusBarWindow"]
        let expectedOrderedVisibleWindowTitles: [String] = []
        let expectedAppVisibleWindowTitles: [String] = []
        let actualState: [String: Any] = [
            "activationPolicy": activationPolicy,
            "bundleLSUIElement": bundleLSUIElement as Any,
            "statusItemPresent": statusItem != nil,
            "statusItemMenuTitle": statusItem?.menu?.title ?? "",
            "visibleWindowTitles": visibleWindowTitles,
            "visibleWindowClassNames": visibleWindowClassNames,
            "appVisibleWindowTitles": appVisibleWindowTitles,
            "orderedVisibleWindowTitles": orderedVisibleWindowTitles,
            "mainWindowTitle": NSApp.mainWindow?.title as Any,
            "keyWindowTitle": NSApp.keyWindow?.title as Any
        ]
        let expectedState: [String: Any] = [
            "activationPolicy": "accessory",
            "bundleLSUIElement": 1,
            "statusItemPresent": true,
            "statusItemMenuTitle": "ClipMenu",
            "visibleWindowTitles": expectedVisibleWindowTitles,
            "visibleWindowClassNames": expectedVisibleWindowClassNames,
            "appVisibleWindowTitles": expectedAppVisibleWindowTitles,
            "orderedVisibleWindowTitles": expectedOrderedVisibleWindowTitles,
            "mainWindowTitle": NSNull(),
            "keyWindowTitle": NSNull()
        ]
        let launchSurfaceMatchesExpected = (actualState as NSDictionary).isEqual(to: expectedState)
        let report: [String: Any] = [
            "activationPolicy": activationPolicy,
            "bundleLSUIElement": bundleLSUIElement as Any,
            "statusItemPresent": statusItem != nil,
            "statusItemMenuTitle": statusItem?.menu?.title ?? "",
            "visibleWindowCount": visibleWindowTitles.count,
            "visibleWindowTitles": visibleWindowTitles,
            "visibleWindowClassNames": visibleWindowClassNames,
            "appVisibleWindowCount": appVisibleWindowTitles.count,
            "appVisibleWindowTitles": appVisibleWindowTitles,
            "orderedVisibleWindowTitles": orderedVisibleWindowTitles,
            "mainWindowTitle": NSApp.mainWindow?.title as Any,
            "keyWindowTitle": NSApp.keyWindow?.title as Any,
            "expectedVisibleWindowTitles": expectedVisibleWindowTitles,
            "expectedVisibleWindowClassNames": expectedVisibleWindowClassNames,
            "expectedAppVisibleWindowTitles": expectedAppVisibleWindowTitles,
            "expectedOrderedVisibleWindowTitles": expectedOrderedVisibleWindowTitles,
            "state": actualState,
            "expectedState": expectedState,
            "launchSurfaceMatchesExpected": launchSurfaceMatchesExpected,
            "matchesExpected": launchSurfaceMatchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        NSApp.terminate(nil)
    }

