    private func flattenedActionTitles(from menu: NSMenu) -> [String] {
        var titles: [String] = []
        for item in menu.items {
            titles.append(item.title)
            if let submenu = item.submenu {
                titles.append(contentsOf: flattenedActionTitles(from: submenu))
            }
        }
        return titles
    }

