    private func runDebugStatusItemIconReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugStatusItemIconReportPath")
            ?? "/tmp/clipmenu-status-item-icon-report.json")
        let originalTag = UserDefaults.standard.integer(forKey: CMPrefShowStatusItemKey)

        defer {
            UserDefaults.standard.set(originalTag, forKey: CMPrefShowStatusItemKey)
            configureStatusItem()
            NSApp.terminate(nil)
        }

        func entryKey(for tag: Int) -> String {
            switch tag {
            case 0:
                return "noneTag"
            case 1:
                return "defaultTag"
            case 2:
                return "originalTag"
            case 3:
                return "scissors1LeftTag"
            case 4:
                return "scissors1RightTag"
            case 5:
                return "scissors1LeftColorTag"
            case 6:
                return "scissors1RightColorTag"
            case 7:
                return "diagonalTag"
            case 8:
                return "diagonalColorTag"
            case 9:
                return "scissors2LeftTag"
            case 10:
                return "scissors2RightTag"
            case 11:
                return "scissors2LeftColorTag"
            case 12:
                return "scissors2RightColorTag"
            default:
                return "tag\(tag)"
            }
        }

        func reportEntry(for tag: Int) -> [String: Any] {
            UserDefaults.standard.set(tag, forKey: CMPrefShowStatusItemKey)
            configureStatusItem()
            rebuildMenu()

            let normalizedStoredTag = UserDefaults.standard.integer(forKey: CMPrefShowStatusItemKey)
            let baseImage = statusItemImage(forTag: tag, pressed: false)
            let pressedImage = statusItemImage(forTag: tag, pressed: true)
            let usesTemplateRendering = statusItemUsesTemplateRendering(forTag: tag)
            let attachedMenuTitle = statusItem?.menu?.title ?? ""

            return [
                "tag": tag,
                "normalizedStoredTag": normalizedStoredTag,
                "statusItemPresent": statusItem != nil,
                "baseImageName": statusItemImageName(forTag: tag),
                "usesTemplateRendering": usesTemplateRendering,
                "baseImageAvailable": baseImage != nil,
                "pressedImageAvailable": pressedImage != nil,
                "buttonImageIsTemplate": statusItem?.button?.image?.isTemplate as Any,
                "buttonAlternateImageIsTemplate": statusItem?.button?.alternateImage?.isTemplate as Any,
                "buttonToolTip": statusItem?.button?.toolTip as Any,
                "attachedMenuTitle": attachedMenuTitle
            ]
        }

        let visibleTags = Array(1...12)
        let allTags = [0] + visibleTags
        var report: [String: Any] = [:]
        var entriesByTag: [Int: [String: Any]] = [:]
        var statusItemIdentifiersByTag: [Int: String] = [:]
        let expectedVisibleBaseImageNames: [Int: String] = [
            1: "StatusMenuIcon",
            2: "StatusMenuIconFirst",
            3: "StatusMenuIconByDaveUlrich-scissors1-bw-left",
            4: "StatusMenuIconByDaveUlrich-scissors1-bw-right",
            5: "StatusMenuIconByDaveUlrich-scissors1-color-left",
            6: "StatusMenuIconByDaveUlrich-scissors1-color-right",
            7: "StatusMenuIconByDaveUlrich-diagonal-bw",
            8: "StatusMenuIconByDaveUlrich-diagonal-color",
            9: "StatusMenuIconByDaveUlrich-scissors2-bw-left",
            10: "StatusMenuIconByDaveUlrich-scissors2-bw-right",
            11: "StatusMenuIconByDaveUlrich-scissors2-color-left",
            12: "StatusMenuIconByDaveUlrich-scissors2-color-right"
        ]
        let expectedToolTip = statusItemToolTip()

        for tag in allTags {
            let entry = reportEntry(for: tag)
            report[entryKey(for: tag)] = entry
            entriesByTag[tag] = entry
            if let statusItem {
                statusItemIdentifiersByTag[tag] = String(ObjectIdentifier(statusItem).hashValue)
            }
        }

        let visibleTagsKeepMenuAttached = visibleTags.allSatisfy { tag in
            entriesByTag[tag]?["statusItemPresent"] as? Bool == true
                && entriesByTag[tag]?["baseImageAvailable"] as? Bool == true
                && entriesByTag[tag]?["pressedImageAvailable"] as? Bool == true
                && entriesByTag[tag]?["attachedMenuTitle"] as? String == "ClipMenu"
                && entriesByTag[tag]?["baseImageName"] as? String == expectedVisibleBaseImageNames[tag]
                && entriesByTag[tag]?["buttonImageIsTemplate"] as? Bool == statusItemUsesTemplateRendering(forTag: tag)
                && entriesByTag[tag]?["buttonAlternateImageIsTemplate"] as? Bool == statusItemUsesTemplateRendering(forTag: tag)
                && entriesByTag[tag]?["buttonToolTip"] as? String == expectedToolTip
        }

        let noneTagDetachesStatusItem = entriesByTag[0]?["statusItemPresent"] as? Bool == false
            && (entriesByTag[0]?["attachedMenuTitle"] as? String)?.isEmpty == true

        UserDefaults.standard.set(99, forKey: CMPrefShowStatusItemKey)
        configureStatusItem()
        rebuildMenu()
        let malformedTagNormalizesToDefault = UserDefaults.standard.integer(forKey: CMPrefShowStatusItemKey) == 1
            && statusItem != nil
            && statusItem?.button?.image?.isTemplate == true
            && statusItemImageName(forTag: 99) == "StatusMenuIcon"

        let visibleTagTransitionsRecreateStatusItem = zip(visibleTags, visibleTags.dropFirst()).allSatisfy { previousTag, nextTag in
            guard let previousIdentifier = statusItemIdentifiersByTag[previousTag],
                  let nextIdentifier = statusItemIdentifiersByTag[nextTag] else {
                return false
            }
            return previousIdentifier != nextIdentifier
        }

        report["visibleTagsKeepMenuAttached"] = visibleTagsKeepMenuAttached
        report["noneTagDetachesStatusItem"] = noneTagDetachesStatusItem
        report["malformedTagNormalizesToDefault"] = malformedTagNormalizesToDefault
        report["visibleTagTransitionsRecreateStatusItem"] = visibleTagTransitionsRecreateStatusItem
        report["matchesExpected"] = noneTagDetachesStatusItem
            && visibleTagsKeepMenuAttached
            && malformedTagNormalizesToDefault
            && visibleTagTransitionsRecreateStatusItem

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

