    private func runDebugSnippetStoreRoundTrip() {
        let store = SnippetFileStore.shared
        let baselineFolders = store.folders
        let baselineTitles = baselineFolders.map(\.title)
        let baselineFirstFolderID = baselineFolders.first?.id
        let baselineSecondFolderID = baselineFolders.dropFirst().first?.id

        var multiSelectionAddCollapsedToPrimary = false
        var multiSelectionAddSelectedSnippet = false
        var multiSelectionAddTargetedPrimaryFolder = false
        if let baselineFirstFolderID, let baselineSecondFolderID,
           let firstFolderIndex = store.folders.firstIndex(where: { $0.id == baselineFirstFolderID }) {
            let originalSnippetCount = store.folders[firstFolderIndex].snippets.count
            store.notePrimaryFolder(baselineFirstFolderID)
            store.selectedFolderIDs = [baselineFirstFolderID, baselineSecondFolderID]
            let addedSnippetID = store.addSnippet()
            multiSelectionAddCollapsedToPrimary = store.selectedFolderIDs == [baselineFirstFolderID]
            multiSelectionAddSelectedSnippet = (addedSnippetID != nil && store.selectedSnippetID == addedSnippetID)
            if let updatedFirstFolderIndex = store.folders.firstIndex(where: { $0.id == baselineFirstFolderID }) {
                multiSelectionAddTargetedPrimaryFolder = store.folders[updatedFirstFolderIndex].snippets.count == originalSnippetCount + 1
            }
            store.reload()
        }

        let addedFolderID = store.addFolder()
        let addedFolder = store.folders.first { $0.id == addedFolderID }
        let afterAddCount = store.folders.count
        let afterAddUnsavedChanges = store.hasUnsavedChanges

        store.reload()
        let revertedMatchesBaseline = store.folders == baselineFolders
        let afterReloadCount = store.folders.count
        let afterReloadUnsavedChanges = store.hasUnsavedChanges

        let savedFolderTitle = "debug saved folder"
        let savedFolderID = store.addFolder()
        if let folder = store.folders.first(where: { $0.id == savedFolderID }) {
            var renamedFolder = folder
            renamedFolder.title = savedFolderTitle
            store.updateFolder(id: savedFolderID, to: renamedFolder)
        }
        store.save()
        let afterSaveUnsavedChanges = store.hasUnsavedChanges
        store.reload()
        let afterSaveReloadTitles = store.folders.map(\.title)
        let savedFolderPersisted = afterSaveReloadTitles.contains(savedFolderTitle)

        let report: [String: Any] = [
            "baselineCount": baselineFolders.count,
            "baselineTitles": baselineTitles,
            "multiSelectionAddCollapsedToPrimary": multiSelectionAddCollapsedToPrimary,
            "multiSelectionAddSelectedSnippet": multiSelectionAddSelectedSnippet,
            "multiSelectionAddTargetedPrimaryFolder": multiSelectionAddTargetedPrimaryFolder,
            "afterAddCount": afterAddCount,
            "afterAddUnsavedChanges": afterAddUnsavedChanges,
            "addedFolderTitle": addedFolder?.title ?? "",
            "afterReloadCount": afterReloadCount,
            "afterReloadUnsavedChanges": afterReloadUnsavedChanges,
            "revertedMatchesBaseline": revertedMatchesBaseline,
            "afterSaveUnsavedChanges": afterSaveUnsavedChanges,
            "afterSaveReloadTitles": afterSaveReloadTitles,
            "savedFolderPersisted": savedFolderPersisted
        ]

        let reportURL = URL(fileURLWithPath: debugStringValue(forKey: "debugSnippetStoreRoundTripReportPath")
            ?? "/tmp/clipmenu-snippet-store-roundtrip.json")
        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        NSApp.terminate(nil)
    }

