    private func runDebugClipStoreRoundTrip() {
        let reportURL = URL(fileURLWithPath: debugStringValue(forKey: "debugClipStoreRoundTripReportPath")
            ?? "/tmp/clipmenu-clip-store-roundtrip.json")
        var report: [String: Any] = [
