        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let defaults = UserDefaults.standard
        let originalMaxHistorySizeObject = defaults.object(forKey: CMPrefMaxHistorySizeKey)
        let originalSaveHistoryOnQuitObject = defaults.object(forKey: CMPrefSaveHistoryOnQuitKey)
        let originalReorderClipsAfterPastingObject = defaults.object(forKey: CMPrefReorderClipsAfterPasting)
