        let originalInlineCountObject = defaults.object(forKey: CMPrefNumberOfItemsPlaceInlineKey)
        let originalFolderCountObject = defaults.object(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        let originalShowLabelsInMenuObject = defaults.object(forKey: CMPrefShowLabelsInMenuKey)
        let originalExportSeparatorObject = defaults.object(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        let originalSnippetsPositionObject = defaults.object(forKey: CMPrefPositionOfSnippetsKey)
        let originalMarkedWithNumbersObject = defaults.object(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        let originalStartWithZeroObject = defaults.object(forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        let originalAddNumericKeyEquivalentsObject = defaults.object(forKey: CMPrefAddNumericKeyEquivalentsKey)
        defer {
            if let originalMaxHistorySizeObject {
                defaults.set(originalMaxHistorySizeObject, forKey: CMPrefMaxHistorySizeKey)
            } else {
                defaults.removeObject(forKey: CMPrefMaxHistorySizeKey)
            }
            if let originalSaveHistoryOnQuitObject {
                defaults.set(originalSaveHistoryOnQuitObject, forKey: CMPrefSaveHistoryOnQuitKey)
            } else {
                defaults.removeObject(forKey: CMPrefSaveHistoryOnQuitKey)
            }
            if let originalReorderClipsAfterPastingObject {
                defaults.set(originalReorderClipsAfterPastingObject, forKey: CMPrefReorderClipsAfterPasting)
            } else {
                defaults.removeObject(forKey: CMPrefReorderClipsAfterPasting)
            }
            if let originalInputPasteCommandObject {
                defaults.set(originalInputPasteCommandObject, forKey: CMPrefInputPasteCommandKey)
            } else {
                defaults.removeObject(forKey: CMPrefInputPasteCommandKey)
            }
            if let originalStoreTypesObject {
                defaults.set(originalStoreTypesObject, forKey: CMPrefStoreTypesKey)
            } else {
                defaults.removeObject(forKey: CMPrefStoreTypesKey)
            }
            if let originalExcludeAppsObject {
                defaults.set(originalExcludeAppsObject, forKey: CMPrefExcludeAppsKey)
            } else {
                defaults.removeObject(forKey: CMPrefExcludeAppsKey)
            }
            if let originalInlineCountObject {
                defaults.set(originalInlineCountObject, forKey: CMPrefNumberOfItemsPlaceInlineKey)
            } else {
                defaults.removeObject(forKey: CMPrefNumberOfItemsPlaceInlineKey)
            }
            if let originalFolderCountObject {
                defaults.set(originalFolderCountObject, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
            } else {
                defaults.removeObject(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
            }
            if let originalShowLabelsInMenuObject {
                defaults.set(originalShowLabelsInMenuObject, forKey: CMPrefShowLabelsInMenuKey)
            } else {
                defaults.removeObject(forKey: CMPrefShowLabelsInMenuKey)
            }
            if let originalExportSeparatorObject {
                defaults.set(originalExportSeparatorObject, forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
            } else {
                defaults.removeObject(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
            }
            if let originalSnippetsPositionObject {
                defaults.set(originalSnippetsPositionObject, forKey: CMPrefPositionOfSnippetsKey)
            } else {
                defaults.removeObject(forKey: CMPrefPositionOfSnippetsKey)
            }
            if let originalMarkedWithNumbersObject {
                defaults.set(originalMarkedWithNumbersObject, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
