        func makeDeterministicClip(text: String, seconds: TimeInterval) -> ClipItem {
            let date = Date(timeIntervalSinceReferenceDate: seconds)
            return ClipItem(text: text, createdAt: date, lastUsedAt: date)
        }

        func seedSelectionVerificationClips() {
            clipsStore.clear()
            clipsStore.add(makeDeterministicClip(text: "select-alpha", seconds: 100))
            clipsStore.add(makeDeterministicClip(text: "select-beta", seconds: 200))
            clipsStore.add(makeDeterministicClip(text: "select-gamma", seconds: 300))
        }

        func seedBaselineHistoryVerificationClips() {
            clipsStore.clear()
            clipsStore.add(makeDeterministicClip(text: "fixture-alpha", seconds: 100))
            clipsStore.add(makeDeterministicClip(text: "fixture-beta", seconds: 200))
            clipsStore.add(makeDeterministicClip(text: "fixture-gamma", seconds: 300))
            clipsStore.add(makeDeterministicClip(text: "fixture-delta", seconds: 400))
        }

        func seedHistoryMenuVerificationClips() {
            clipsStore.clear()
            for index in 1...8 {
                let seconds = TimeInterval(index * 100)
                clipsStore.add(makeDeterministicClip(text: "menu-\(index)", seconds: seconds))
            }
        }

        func seedExportVerificationClips() {
            clipsStore.clear()
            clipsStore.add(makeDeterministicClip(text: "export-old", seconds: 100))
            clipsStore.add(
                ClipItem(
                    types: [NSPasteboard.PasteboardType.pdf.rawValue],
                    createdAt: Date(timeIntervalSinceReferenceDate: 200),
                    lastUsedAt: Date(timeIntervalSinceReferenceDate: 200),
                    text: "",
                    pdfData: Data("pdf-smoke".utf8)
                )
            )
            clipsStore.add(makeDeterministicClip(text: "export-new", seconds: 300))
        }

        func seedNumericVerificationClips() {
            clipsStore.clear()
            for index in 1...11 {
                let seconds = TimeInterval(index * 100)
                clipsStore.add(makeDeterministicClip(text: "num-\(index)", seconds: seconds))
            }
        }

        func makeDeterministicDate(_ seconds: TimeInterval) -> Date {
            Date(timeIntervalSinceReferenceDate: seconds)
        }

        func topLevelTitles(from menu: NSMenu) -> [String] {
            menu.items.map { $0.isSeparatorItem ? "<separator>" : $0.title }
        }

        func topLevelEnabledStates(from menu: NSMenu) -> [Bool] {
            menu.items.map(\.isEnabled)
        }

        func makeScratchPasteboard(suffix: String) -> NSPasteboard {
            NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.\(suffix).\(UUID().uuidString)"))
        }

        func debugImageFingerprint(_ image: NSImage?) -> Data? {
            guard let tiffRepresentation = image?.tiffRepresentation,
                  let bitmap = NSBitmapImageRep(data: tiffRepresentation) else {
                return nil
            }
            return bitmap.representation(using: .png, properties: [:])
        }

        defaults.set(true, forKey: CMPrefReorderClipsAfterPasting)

        if clipsStore.orderedClips.isEmpty {
            seedBaselineHistoryVerificationClips()
            report["seededBaselineHistoryFixture"] = true
        } else {
            report["seededBaselineHistoryFixture"] = false
        }

        let baselineOrderedClips = clipsStore.orderedClips
        let baselineOrderedTexts = baselineOrderedClips.map(\.text)
        report["baselineCount"] = baselineOrderedClips.count
        report["baselineOrderedTexts"] = baselineOrderedTexts

        let duplicateTarget = baselineOrderedClips.last ?? baselineOrderedClips.first
        var duplicatePromotedToTop = false
        var duplicateKeptCount = false
        var duplicateTargetText = ""
        if let duplicateTarget {
            let countBeforeDuplicate = clipsStore.clips.count
            clipsStore.add(duplicateTarget)
            duplicateTargetText = duplicateTarget.text
            duplicatePromotedToTop = clipsStore.orderedClips.first?.text == duplicateTarget.text
            duplicateKeptCount = clipsStore.clips.count == countBeforeDuplicate
        }
        report["duplicateTargetText"] = duplicateTargetText
        report["duplicatePromotedToTop"] = duplicatePromotedToTop
        report["duplicateKeptCount"] = duplicateKeptCount
        report["afterDuplicateOrderedTexts"] = clipsStore.orderedClips.map(\.text)
        report["afterDuplicateUnsavedChanges"] = clipsStore.debugHasUnsavedChanges

        defaults.set(2, forKey: CMPrefMaxHistorySizeKey)
        clipsStore.trimToCurrentHistoryLimit()
        let trimmedOrderedTexts = clipsStore.orderedClips.map(\.text)
        report["trimmedCount"] = clipsStore.clips.count
        report["trimmedOrderedTexts"] = trimmedOrderedTexts
        report["trimmedToTwoNewest"] = clipsStore.clips.count == min(2, baselineOrderedClips.count)
        report["afterTrimUnsavedChanges"] = clipsStore.debugHasUnsavedChanges

        let saveSucceeded = clipsStore.save()
        report["saveSucceeded"] = saveSucceeded
        report["afterSaveUnsavedChanges"] = clipsStore.debugHasUnsavedChanges

        let reloadedStore = ClipStore()
        reloadedStore.load()
        let reloadedOrderedTexts = reloadedStore.orderedClips.map(\.text)
        report["reloadedCount"] = reloadedStore.clips.count
        report["reloadedOrderedTexts"] = reloadedOrderedTexts
        report["reloadMatchesTrimmedState"] = reloadedOrderedTexts == trimmedOrderedTexts
        report["reloadedUnsavedChanges"] = reloadedStore.debugHasUnsavedChanges

        defaults.set(false, forKey: CMPrefInputPasteCommandKey)
        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        defaults.set(true, forKey: CMPrefReorderClipsAfterPasting)
        seedSelectionVerificationClips()
        let reorderEnabledBeforeTexts = clipsStore.orderedClips.map(\.text)
        var reorderEnabledAfterTexts = reorderEnabledBeforeTexts
        var reorderEnabledSelectedText = ""
        if let reorderEnabledClip = clipsStore.orderedClips.last {
            let item = makeClipMenuItem(clip: reorderEnabledClip, globalIndex: 2, listNumber: 3)
            reorderEnabledSelectedText = reorderEnabledClip.text
            selectClip(item)
            reorderEnabledAfterTexts = clipsStore.orderedClips.map(\.text)
