        defaults.set(32, forKey: CMPrefMenuIconSizeKey)
        let icon32Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        report["menuIconSize32MatchesExpected"] = {
            guard let size = icon32Item.image?.size else { return false }
            return size.width == 32 && size.height == 32
        }()

        defaults.set(48, forKey: CMPrefMenuIconSizeKey)
        let icon48Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        report["menuIconSize48MatchesExpected"] = {
            guard let size = icon48Item.image?.size else { return false }
            return size.width == 48 && size.height == 48
        }()

        defaults.set(24, forKey: CMPrefMenuIconSizeKey)
        let icon24Item = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        report["menuIconSize24NormalizesToLegacy16"] = {
            guard let size = icon24Item.image?.size else { return false }
            return size.width == 16 && size.height == 16
        }()

        defaults.set(0, forKey: CMPrefMenuIconOfFileTypeTagForTIFFKey)
        defaults.set("pdf", forKey: CMPrefMenuIconOfFileTypeForTIFFKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForPICTKey)
        defaults.set("fold", forKey: CMPrefMenuIconOfFileTypeForPICTKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey)
        defaults.set("fold", forKey: CMPrefMenuIconOfFileTypeForFilenamesKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForURLKey)
        defaults.set("gurl", forKey: CMPrefMenuIconOfFileTypeForURLKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForStringKey)
        defaults.set("TEXT", forKey: CMPrefMenuIconOfFileTypeForStringKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForRTFKey)
        defaults.set("fold", forKey: CMPrefMenuIconOfFileTypeForRTFKey)
        defaults.set(0, forKey: CMPrefMenuIconOfFileTypeTagForRTFDKey)
        defaults.set("rtfd", forKey: CMPrefMenuIconOfFileTypeForRTFDKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForPDFKey)
        defaults.set("PDF ", forKey: CMPrefMenuIconOfFileTypeForPDFKey)
        let runtimeStringIcon = fileTypeIcon(for: .string)
        let runtimeRTFIcon = fileTypeIcon(for: .rtf)
        let runtimeRTFDIcon = fileTypeIcon(for: .rtfd)
        let runtimePDFIcon = fileTypeIcon(for: .pdf)
        let runtimeTIFFIcon = fileTypeIcon(for: .tiff)
        let runtimePICTIcon = fileTypeIcon(for: .clipMenuPICT)
        let runtimeFilenamesIcon = fileTypeIcon(for: .clipMenuFilenames)
        let runtimeURLIcon = fileTypeIcon(for: .clipMenuURL)
        let expectedStringIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "TEXT"))
        )
        let expectedRTFIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "fold"))
        )
        let expectedRTFDIcon = NSWorkspace.shared.icon(forFileType: "rtfd")
        let expectedPDFIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "PDF "))
        )
        let expectedTIFFIcon = NSWorkspace.shared.icon(forFileType: "pdf")
        let expectedPICTIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "fold"))
        )
        let expectedFilenamesIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "fold"))
        )
        let expectedURLIcon = NSWorkspace.shared.icon(
            forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: "gurl"))
        )
        let runtimeStringFingerprint = debugImageFingerprint(runtimeStringIcon)
        let runtimeRTFFingerprint = debugImageFingerprint(runtimeRTFIcon)
        let runtimeRTFDFingerprint = debugImageFingerprint(runtimeRTFDIcon)
        let runtimePDFFingerprint = debugImageFingerprint(runtimePDFIcon)
        let runtimeTIFFFingerprint = debugImageFingerprint(runtimeTIFFIcon)
        let runtimePICTFingerprint = debugImageFingerprint(runtimePICTIcon)
        let runtimeFilenamesFingerprint = debugImageFingerprint(runtimeFilenamesIcon)
        let runtimeURLFingerprint = debugImageFingerprint(runtimeURLIcon)
        report["stringRuntimeUsesStringPreference"] =
            runtimeStringFingerprint == debugImageFingerprint(expectedStringIcon)
        report["rtfRuntimeUsesRTFPreference"] =
            runtimeRTFFingerprint == debugImageFingerprint(expectedRTFIcon)
        report["rtfdRuntimeUsesRTFDPreference"] =
            runtimeRTFDFingerprint == debugImageFingerprint(expectedRTFDIcon)
        report["pdfRuntimeUsesPDFPreference"] =
            runtimePDFFingerprint == debugImageFingerprint(expectedPDFIcon)
        report["rtfRuntimeDiffersFromStringPreference"] =
            runtimeRTFFingerprint != runtimeStringFingerprint
        report["rtfdRuntimeDiffersFromRTFPreference"] =
            runtimeRTFDFingerprint != runtimeRTFFingerprint
        report["pdfRuntimeDiffersFromRTFDPreference"] =
            runtimePDFFingerprint != runtimeRTFDFingerprint
        report["tiffRuntimeUsesTIFFPreference"] = runtimeTIFFFingerprint == debugImageFingerprint(expectedTIFFIcon)
        report["pictRuntimeUsesPICTPreference"] = runtimePICTFingerprint == debugImageFingerprint(expectedPICTIcon)
        report["pictRuntimeDiffersFromTIFFPreference"] = runtimePICTFingerprint != runtimeTIFFFingerprint
        report["filenamesRuntimeUsesFilenamesPreference"] =
            runtimeFilenamesFingerprint == debugImageFingerprint(expectedFilenamesIcon)
        report["urlRuntimeUsesURLPreference"] =
            runtimeURLFingerprint == debugImageFingerprint(expectedURLIcon)
        report["urlRuntimeDiffersFromFilenamesPreference"] =
            runtimeURLFingerprint != runtimeFilenamesFingerprint

        defaults.set(false, forKey: CMPrefShowIconInTheMenuKey)
        let iconsDisabledItem = makeClipMenuItem(clip: iconFallbackPDFClip, globalIndex: 1, listNumber: 2)
        report["menuIconsDisabledSuppressesNonImageIcon"] = iconsDisabledItem.image == nil

        defaults.set(ClipItem.defaultStoreTypes(), forKey: CMPrefStoreTypesKey)
        let excludedBundleIdentifier = "com.naotaka.ClipMenu.debug.excluded-app"
        defaults.set([[kCMBundleIdentifierKey: excludedBundleIdentifier, kCMNameKey: "Debug Excluded"]], forKey: CMPrefExcludeAppsKey)
        let excludedPasteboard = makeScratchPasteboard(suffix: "excludedApp")
        excludedPasteboard.clearContents()
        excludedPasteboard.declareTypes([.string], owner: nil)
        excludedPasteboard.setString("excluded-app-clip", forType: .string)
        report["excludedAppRejected"] = capturedClip(from: excludedPasteboard, frontmostBundleIdentifier: excludedBundleIdentifier) == nil
        report["nonExcludedAppAccepted"] = capturedClip(from: excludedPasteboard, frontmostBundleIdentifier: "com.naotaka.ClipMenu.debug.allowed-app")?.text == "excluded-app-clip"

        reloadedStore.removeSavedHistory()
        let clearedStore = ClipStore()
        clearedStore.load()
        report["clearedReloadCount"] = clearedStore.clips.count
        report["clearedReloadEmpty"] = clearedStore.clips.isEmpty

        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        clipsStore.clear()
        clipsStore.add(ClipItem(text: "quit-save-alpha"))
        clipsStore.add(ClipItem(text: "quit-save-beta"))
        let quitSaveExpectedTexts = clipsStore.orderedClips.map(\.text)
        defaults.set(true, forKey: CMPrefSaveHistoryOnQuitKey)
        let quitSavePersistSucceeded = persistHistoryForTermination()
        let quitSaveReloadStore = ClipStore()
        quitSaveReloadStore.load()
        let quitSaveReloadTexts = quitSaveReloadStore.orderedClips.map(\.text)
        report["quitSavePersistSucceeded"] = quitSavePersistSucceeded
        report["quitSaveExpectedTexts"] = quitSaveExpectedTexts
        report["quitSaveReloadTexts"] = quitSaveReloadTexts
        report["quitSaveReloadMatchesExpected"] = quitSaveReloadTexts == quitSaveExpectedTexts

        clipsStore.clear()
        clipsStore.add(ClipItem(text: "quit-discard-alpha"))
        defaults.set(false, forKey: CMPrefSaveHistoryOnQuitKey)
        let quitDiscardPersistSucceeded = persistHistoryForTermination()
        let quitDiscardReloadStore = ClipStore()
        quitDiscardReloadStore.load()
        report["quitDiscardPersistSucceeded"] = quitDiscardPersistSucceeded
        report["quitDiscardReloadCount"] = quitDiscardReloadStore.clips.count
        report["quitDiscardReloadEmpty"] = quitDiscardReloadStore.clips.isEmpty

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        NSApp.terminate(nil)
    }

