    private func runDebugActionMenuSelection() {
        let itemTitle = UserDefaults.standard.string(forKey: "debugRunActionMenuSelectionTitle") ?? "UPPERCASE.js"
        let text = UserDefaults.standard.string(forKey: "debugRunActionMenuSelectionText") ?? "clipmenu action menu smoke"
        let clip = ClipItem(text: text)
        clipsStore.add(clip)
        actionTarget = .clip(clip.id)
        let oldInputPasteCommand = UserDefaults.standard.object(forKey: CMPrefInputPasteCommandKey)
        let allowsPaste = UserDefaults.standard.bool(forKey: "debugRunActionMenuSelectionAllowsPaste")
        if allowsPaste {
            rememberPasteTargetApplication()
        }
        if !allowsPaste {
            UserDefaults.standard.set(false, forKey: CMPrefInputPasteCommandKey)
        }
        defer {
            actionTarget = nil
            clipsStore.remove(clip.id)
            rebuildMenu()
            if let oldInputPasteCommand {
                UserDefaults.standard.set(oldInputPasteCommand, forKey: CMPrefInputPasteCommandKey)
            } else {
                UserDefaults.standard.removeObject(forKey: CMPrefInputPasteCommandKey)
            }
        }

        let menu = makeActionMenu()
        debugPasteFlow("runDebugActionMenuSelection menuItems=\(menu.numberOfItems) title=\(itemTitle)")
        guard let item = menuItem(withTitle: itemTitle, in: menu) else {
            debugPasteFlow("runDebugActionMenuSelection missing title=\(itemTitle)")
            return
        }

        debugPasteFlow("runDebugActionMenuSelection firing title=\(item.title)")
        selectAction(item)
        let pasteboardText = NSPasteboard.general.string(forType: .string) ?? ""
        debugPasteFlow("runDebugActionMenuSelection pasteboardText=\(pasteboardText)")
    }

