    private func menuItem(withTitle title: String, in menu: NSMenu) -> NSMenuItem? {
        for item in menu.items {
            if normalizedMenuItemTitle(item.title) == normalizedMenuItemTitle(title) {
                return item
            }
            if let submenu = item.submenu,
               let child = menuItem(withTitle: title, in: submenu) {
                return child
            }
        }
        return nil
    }

    private func visiblePreferencesMenuTitle() -> String {
        NSLocalizedString("Preferences...", comment: "")
    }

    private func storedPreferencesMenuTitle() -> String {
        visiblePreferencesMenuTitle() + "\u{200B}"
    }

    private func normalizedMenuItemTitle(_ title: String) -> String {
        title.replacingOccurrences(of: "\u{200B}", with: "")
    }

    private func visibleMenuItemTitle(_ item: NSMenuItem) -> String {
        if let attributedTitle = item.attributedTitle,
           !attributedTitle.string.isEmpty {
            return attributedTitle.string
        }
        return normalizedMenuItemTitle(item.title)
    }

    private func menuItem(withAction action: Selector, in menu: NSMenu) -> NSMenuItem? {
        for item in menu.items {
            if item.action == action {
                return item
            }
            if let submenu = item.submenu,
               let child = menuItem(withAction: action, in: submenu) {
                return child
            }
        }
        return nil
    }

    private func enforceLegacyMainMenuTitles() {
        guard let mainMenu = NSApp.mainMenu,
              let preferencesItem = menuItem(withAction: #selector(showPreferencePanel(_:)), in: mainMenu) else {
            return
        }

        let visibleTitle = visiblePreferencesMenuTitle()
        let storedTitle = storedPreferencesMenuTitle()
        if preferencesItem.title != storedTitle {
            preferencesItem.title = storedTitle
        }
        preferencesItem.attributedTitle = NSAttributedString(string: visibleTitle)
    }

    private func scheduleDebugPasteboardRoundTripIfNeeded() {
        let delay = UserDefaults.standard.double(forKey: "debugRunPasteboardRoundTripAfterLaunchDelay")
        guard delay > 0 else { return }

        DispatchQueue.main.asyncAfter(deadline: .now() + delay) { [weak self] in
            self?.runDebugPasteboardRoundTrip()
        }
    }

    private func runDebugPasteboardRoundTrip() {
        let cases: [(String, (NSPasteboard) -> Bool, (ClipItem, NSPasteboard) -> Bool)] = [
            ("rtf", writeDebugRTFPasteboard, verifyDebugRTFRoundTrip),
            ("pdf", writeDebugPDFPasteboard, verifyDebugPDFRoundTrip),
            ("fileURL", writeDebugFileURLPasteboard, verifyDebugFileURLRoundTrip),
            ("url", writeDebugURLPasteboard, verifyDebugURLRoundTrip),
            ("image", writeDebugImagePasteboard, verifyDebugImageRoundTrip)
        ]

        for testCase in cases {
            let input = NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.input.\(UUID().uuidString)"))
            let output = NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.output.\(UUID().uuidString)"))
            guard testCase.1(input) else {
                debugPasteFlow("runDebugPasteboardRoundTrip \(testCase.0) setup=false")
                continue
            }
            guard let clip = ClipItem.fromPasteboard(input) else {
                debugPasteFlow("runDebugPasteboardRoundTrip \(testCase.0) captured=false inputTypes=\((input.types ?? []).map(\.rawValue).joined(separator: ","))")
                continue
            }

            clip.write(to: output)
            let passed = testCase.2(clip, output)
            debugPasteFlow("runDebugPasteboardRoundTrip \(testCase.0) passed=\(passed) clipTypes=\(clip.types.joined(separator: ",")) outputTypes=\((output.types ?? []).map(\.rawValue).joined(separator: ",")) text=\(clip.text)")
        }
    }

