    private func runDebugLegacyUpdateDefaultsSyncReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugLegacyUpdateDefaultsSyncReportPath")
            ?? "/tmp/clipmenu-legacy-update-defaults-sync-report.json")
        let originalPersistentDomain = Bundle.main.bundleIdentifier.flatMap { defaults.persistentDomain(forName: $0) }

        defer {
            if let bundleIdentifier = Bundle.main.bundleIdentifier {
                if let originalPersistentDomain {
                    defaults.setPersistentDomain(originalPersistentDomain, forName: bundleIdentifier)
                } else {
                    defaults.removePersistentDomain(forName: bundleIdentifier)
                }
            }
            AppController.registerDefaults()
            AppController.migrateLegacyUpdateDefaultsIfNeeded()
            AppController.syncLegacyUpdateDefaultsFromModernPreferencesIfNeeded()
            UpdateCoordinator.shared.configureFromDefaults()
            NSApp.terminate(nil)
        }

        guard let bundleIdentifier = Bundle.main.bundleIdentifier else {
            let report: [String: Any] = ["error": "Missing bundle identifier", "matchesExpected": false]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        let importedLegacyDomain: [String: Any] = [
            CMLegacyAutomaticChecksEnabledOldKey: false,
            CMLegacyUpdateCheckIntervalKey: 604800,
            CMAutomaticallyInstallUpdatesKey: true
        ]

        func captureState(label: String) -> [String: Any] {
            let persistentDefaults = defaults.persistentDomain(forName: bundleIdentifier) ?? [:]
            let paneSnapshot = CMUpdatesPreferencesSnapshotForDebug()
            let snapshotStates = paneSnapshot["states"] as? [String: Any] ?? [:]
            return [
                "label": label,
                "effectiveAutomaticChecks": defaults.bool(forKey: CMEnableAutomaticCheckKey),
                "effectiveUpdateInterval": defaults.integer(forKey: CMUpdateCheckIntervalKey),
                "effectiveAutomaticallyInstallUpdates": defaults.bool(forKey: CMAutomaticallyInstallUpdatesKey),
                "persistentAutomaticChecks": persistentDefaults[CMEnableAutomaticCheckKey] as Any,
                "persistentLegacyAutomaticChecks": persistentDefaults[CMLegacyAutomaticChecksEnabledKey] as Any,
                "persistentLegacyAutomaticChecksOld": persistentDefaults[CMLegacyAutomaticChecksEnabledOldKey] as Any,
                "persistentLegacyAllowsAutomaticUpdates": persistentDefaults[CMLegacyAllowsAutomaticUpdatesKey] as Any,
                "persistentLegacyInterval": persistentDefaults[CMLegacyUpdateCheckIntervalKey] as Any,
                "persistentAutomaticallyInstallUpdates": persistentDefaults[CMAutomaticallyInstallUpdatesKey] as Any,
                "snapshotAutomaticChecks": snapshotStates["automaticChecks"] as? Bool as Any,
                "snapshotAutomaticallyInstallUpdates": snapshotStates["automaticallyInstallUpdates"] as? Bool as Any,
                "snapshotInterval": snapshotStates["interval"] as? Int as Any,
                "snapshotVisibleIntervalSelection": snapshotStates["visibleIntervalSelection"] as? Int as Any,
                "snapshotShowsImportedIntervalNotice": snapshotStates["showsImportedIntervalNotice"] as? Bool as Any
            ]
        }

        defaults.setPersistentDomain(importedLegacyDomain, forName: bundleIdentifier)
        AppController.registerDefaults()
        AppController.migrateLegacyUpdateDefaultsIfNeeded()
        AppController.syncLegacyUpdateDefaultsFromModernPreferencesIfNeeded()
        UpdateCoordinator.shared.configureFromDefaults()
        let migratedState = captureState(label: "migratedLegacyDomain")

        defaults.set(true, forKey: CMEnableAutomaticCheckKey)
        defaults.set(2592000, forKey: CMUpdateCheckIntervalKey)
        defaults.set(false, forKey: CMAutomaticallyInstallUpdatesKey)
        userDefaultsDidChange(Notification(name: UserDefaults.didChangeNotification))
        UpdateCoordinator.shared.configureFromDefaults()
        let syncedState = captureState(label: "syncedFromModernPreferences")

        let migratedExpectedState: [String: Any] = [
            "label": "migratedLegacyDomain",
            "effectiveAutomaticChecks": false,
            "effectiveUpdateInterval": 604800,
            "effectiveAutomaticallyInstallUpdates": true,
            "persistentAutomaticChecks": false,
            "persistentLegacyAutomaticChecks": false,
            "persistentLegacyAutomaticChecksOld": false,
            "persistentLegacyAllowsAutomaticUpdates": false,
            "persistentLegacyInterval": 604800,
            "persistentAutomaticallyInstallUpdates": true,
            "snapshotAutomaticChecks": false,
            "snapshotAutomaticallyInstallUpdates": true,
            "snapshotInterval": 604800,
            "snapshotVisibleIntervalSelection": 604800,
            "snapshotShowsImportedIntervalNotice": false
        ]
        let syncedExpectedState: [String: Any] = [
            "label": "syncedFromModernPreferences",
            "effectiveAutomaticChecks": true,
            "effectiveUpdateInterval": 2592000,
            "effectiveAutomaticallyInstallUpdates": false,
            "persistentAutomaticChecks": true,
            "persistentLegacyAutomaticChecks": true,
            "persistentLegacyAutomaticChecksOld": true,
            "persistentLegacyAllowsAutomaticUpdates": true,
            "persistentLegacyInterval": 2592000,
            "persistentAutomaticallyInstallUpdates": false,
            "snapshotAutomaticChecks": true,
            "snapshotAutomaticallyInstallUpdates": false,
            "snapshotInterval": 2592000,
            "snapshotVisibleIntervalSelection": 2592000,
            "snapshotShowsImportedIntervalNotice": false
        ]

        let report: [String: Any] = [
            "state": [
                "migratedState": migratedState,
                "syncedState": syncedState
            ],
            "expectedState": [
                "migratedState": migratedExpectedState,
                "syncedState": syncedExpectedState
            ],
            "matchesExpected": NSDictionary(dictionary: migratedState).isEqual(to: migratedExpectedState)
                && NSDictionary(dictionary: syncedState).isEqual(to: syncedExpectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugOpenRecentMenuReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugOpenRecentMenuReportPath")
            ?? "/tmp/clipmenu-open-recent-menu-report.json")
        let documentController = NSDocumentController.shared
        let testURL = URL(fileURLWithPath: "/tmp/clipmenu-open-recent-smoke.txt")
        let originalRecentDocumentURLs = documentController.recentDocumentURLs
        try? "open recent smoke".write(to: testURL, atomically: true, encoding: .utf8)

        func openRecentSubmenu(from menu: NSMenu?) -> NSMenu? {
            menu?.items
                .first(where: { $0.title == NSLocalizedString("File", comment: "") })?
                .submenu?
                .items
                .first(where: { $0.title == NSLocalizedString("Open Recent", comment: "") })?
                .submenu
        }

        func menuTitles(_ menu: NSMenu?) -> [String] {
            menu?.items.map { $0.isSeparatorItem ? "<separator>" : $0.title } ?? []
        }

        defer {
            restoreRecentDocumentURLs(originalRecentDocumentURLs, documentController: documentController)
            try? FileManager.default.removeItem(at: testURL)
            NSApp.terminate(nil)
        }

        let beforeURLs = documentController.recentDocumentURLs.map { $0.resolvingSymlinksInPath().path }
        documentController.clearRecentDocuments(nil)
        installMainMenu()
        let openRecentMenuBefore = openRecentSubmenu(from: NSApp.mainMenu)
        let openRecentTitlesBefore = menuTitles(openRecentMenuBefore)
        let clearMenuEnabledBefore = openRecentMenuBefore?
            .items
            .first(where: { $0.title == NSLocalizedString("Clear Menu", comment: "") })?
            .isEnabled

        documentController.noteNewRecentDocumentURL(testURL)
        refreshMainMenuDocumentItems(nil)
        let afterURLs = documentController.recentDocumentURLs.map { $0.resolvingSymlinksInPath().path }
        let openRecentMenuAfter = openRecentSubmenu(from: NSApp.mainMenu)
        let openRecentTitlesAfter = menuTitles(openRecentMenuAfter)
        let clearMenuItem = openRecentMenuAfter?
            .items
            .first(where: { $0.title == NSLocalizedString("Clear Menu", comment: "") })
        let clearMenuEnabledAfter = clearMenuItem?.isEnabled
        clearMenuItem.map(clearRecentSnippetDocuments(_:))
        let afterClearURLs = documentController.recentDocumentURLs.map { $0.resolvingSymlinksInPath().path }
        let openRecentMenuAfterClear = openRecentSubmenu(from: NSApp.mainMenu)
        let openRecentTitlesAfterClear = menuTitles(openRecentMenuAfterClear)
        let clearMenuEnabledAfterClear = openRecentMenuAfterClear?
            .items
            .first(where: { $0.title == NSLocalizedString("Clear Menu", comment: "") })?
            .isEnabled
        installMainMenu()
        let rebuiltOpenRecentTitlesAfter = menuTitles(openRecentSubmenu(from: NSApp.mainMenu))
        let expectedBeforeURLs: [String] = []
        let expectedAfterURLs = [testURL.resolvingSymlinksInPath().path]
        let expectedAfterClearURLs: [String] = []
        let expectedOpenRecentTitlesBefore = [NSLocalizedString("Clear Menu", comment: "")]
        let expectedOpenRecentTitlesAfter = [testURL.lastPathComponent, "<separator>", NSLocalizedString("Clear Menu", comment: "")]
        let expectedOpenRecentTitlesAfterClear = [NSLocalizedString("Clear Menu", comment: "")]
        let expectedRebuiltOpenRecentTitlesAfter = [NSLocalizedString("Clear Menu", comment: "")]

        let report: [String: Any] = [
            "beforeURLs": beforeURLs,
            "afterURLs": afterURLs,
            "afterClearURLs": afterClearURLs,
            "openRecentTitlesBefore": openRecentTitlesBefore,
            "openRecentTitlesAfter": openRecentTitlesAfter,
            "openRecentTitlesAfterClear": openRecentTitlesAfterClear,
            "rebuiltOpenRecentTitlesAfter": rebuiltOpenRecentTitlesAfter,
            "clearMenuEnabledBefore": clearMenuEnabledBefore as Any,
            "clearMenuEnabledAfter": clearMenuEnabledAfter as Any,
            "clearMenuEnabledAfterClear": clearMenuEnabledAfterClear as Any,
            "expectedBeforeURLs": expectedBeforeURLs,
            "expectedAfterURLs": expectedAfterURLs,
            "expectedAfterClearURLs": expectedAfterClearURLs,
            "expectedOpenRecentTitlesBefore": expectedOpenRecentTitlesBefore,
            "expectedOpenRecentTitlesAfter": expectedOpenRecentTitlesAfter,
            "expectedOpenRecentTitlesAfterClear": expectedOpenRecentTitlesAfterClear,
            "expectedRebuiltOpenRecentTitlesAfter": expectedRebuiltOpenRecentTitlesAfter,
            "recentDocumentsContainsTestURL": afterURLs.contains(testURL.resolvingSymlinksInPath().path),
            "menuContainsRecentEntry": openRecentTitlesAfter.contains(testURL.lastPathComponent),
            "rebuiltMenuContainsRecentEntry": rebuiltOpenRecentTitlesAfter.contains(testURL.lastPathComponent),
            "clearMenuItemPresent": openRecentTitlesAfter.contains(NSLocalizedString("Clear Menu", comment: "")),
            "matchesExpected": beforeURLs == expectedBeforeURLs
                && afterURLs == expectedAfterURLs
                && afterClearURLs == expectedAfterClearURLs
                && openRecentTitlesBefore == expectedOpenRecentTitlesBefore
                && openRecentTitlesAfter == expectedOpenRecentTitlesAfter
                && openRecentTitlesAfterClear == expectedOpenRecentTitlesAfterClear
                && rebuiltOpenRecentTitlesAfter == expectedRebuiltOpenRecentTitlesAfter
                && clearMenuEnabledBefore == false
                && clearMenuEnabledAfter == true
                && clearMenuEnabledAfterClear == false
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugOpenRecentImportReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugOpenRecentImportReportPath")
            ?? "/tmp/clipmenu-open-recent-import-report.json")
        let documentController = NSDocumentController.shared
        let snippetStore = SnippetFileStore.shared
        let originalFolders = snippetStore.folders
        let originalRecentDocumentURLs = documentController.recentDocumentURLs
        let testURL = URL(fileURLWithPath: "/tmp/clipmenu-open-recent-import.xml")
        let xml = """
        <?xml version="1.0" encoding="UTF-8"?>
        <folders>
          <folder>
            <title>Recent Imports</title>
            <snippets>
              <snippet>
                <title>Recent Greeting</title>
                <content>Hello from Open Recent</content>
              </snippet>
            </snippets>
          </folder>
        </folders>
        """

        func openRecentSubmenu() -> NSMenu? {
            NSApp.mainMenu?.items
                .first(where: { $0.title == NSLocalizedString("File", comment: "") })?
                .submenu?
                .items
                .first(where: { $0.title == NSLocalizedString("Open Recent", comment: "") })?
                .submenu
        }

        defer {
            snippetStore.folders = originalFolders
            snippetStore.save()
            snippetStore.reload()
            restoreRecentDocumentURLs(originalRecentDocumentURLs, documentController: documentController)
            try? FileManager.default.removeItem(at: testURL)
            snippetEditorController?.close()
            NSApp.terminate(nil)
        }

        documentController.clearRecentDocuments(nil)
        snippetStore.folders = []
        snippetStore.save()
        snippetStore.reload()
        try? xml.write(to: testURL, atomically: true, encoding: .utf8)

        documentController.noteNewRecentDocumentURL(testURL)
        refreshMainMenuDocumentItems(nil)
        let openRecentMenu = openRecentSubmenu()
        let recentItem = openRecentMenu?.items.first(where: { $0.title == testURL.lastPathComponent })
        recentItem.map(openRecentSnippetDocument(_:))

        let importedFolderTitles = snippetStore.folders.map(\.title)
        let importedSnippetTitles = snippetStore.folders.flatMap { $0.snippets.map(\.title) }
        let importedSnippetContents = snippetStore.folders.flatMap { $0.snippets.map(\.content) }
        let recentMenuTitles = openRecentMenu?.items.map { $0.isSeparatorItem ? "<separator>" : $0.title } ?? []
        let expectedRecentMenuTitles = [
            testURL.lastPathComponent,
            "<separator>",
            NSLocalizedString("Clear Menu", comment: "")
        ]
        let expectedRecentItemRepresentedPath = testURL.resolvingSymlinksInPath().path

        let report: [String: Any] = [
            "recentMenuTitles": recentMenuTitles,
            "recentItemFound": recentItem != nil,
            "recentItemRepresentedPath": (recentItem?.representedObject as? URL)?.path as Any,
            "importedFolderTitles": importedFolderTitles,
            "importedSnippetTitles": importedSnippetTitles,
            "importedSnippetContents": importedSnippetContents,
            "expectedRecentMenuTitles": expectedRecentMenuTitles,
            "expectedRecentItemRepresentedPath": expectedRecentItemRepresentedPath,
            "matchesExpected": recentMenuTitles == expectedRecentMenuTitles
                && recentItem != nil
                && (((recentItem?.representedObject as? URL)?.resolvingSymlinksInPath().path) == expectedRecentItemRepresentedPath)
                && importedFolderTitles == ["Recent Imports"]
                && importedSnippetTitles == ["Recent Greeting"]
                && importedSnippetContents == ["Hello from Open Recent"]
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugControllerPublicActionsReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugControllerPublicActionsReportPath")
            ?? "/tmp/clipmenu-controller-public-actions-report.json")
        let defaults = UserDefaults.standard
        let actionsURL = clipMenuApplicationSupportDirectory().appendingPathComponent("actions.plist")
        let originalActionData = try? Data(contentsOf: actionsURL)
        let originalClips = clipsStore.clips
        let originalFolders = SnippetFileStore.shared.folders
        let originalDebugCapturePopupMenus = debugCapturePopupMenus
        let originalDebugCapturedPopupMenuSummaries = debugCapturedPopupMenuSummaries
        let originalActionTarget = actionTarget
        let originalPreviousPasteTargetApplication = previousPasteTargetApplication
        let originalPreviousFrontProcessSerialNumber = previousFrontProcessSerialNumber
        let originalShowLabels = defaults.object(forKey: CMPrefShowLabelsInMenuKey)
        let originalAddClearHistory = defaults.object(forKey: CMPrefAddClearHistoryMenuItemKey)
        let originalPositionOfSnippets = defaults.object(forKey: CMPrefPositionOfSnippetsKey)
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)
        let originalInlineCount = defaults.object(forKey: CMPrefNumberOfItemsPlaceInlineKey)
        let originalFolderCount = defaults.object(forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        let originalMarkNumbers = defaults.object(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        let originalStartsFromZero = defaults.object(forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        let originalNumericKeys = defaults.object(forKey: CMPrefAddNumericKeyEquivalentsKey)

        defer {
            if let originalActionData {
                try? originalActionData.write(to: actionsURL, options: .atomic)
            } else {
                try? FileManager.default.removeItem(at: actionsURL)
            }
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            SnippetFileStore.shared.folders = originalFolders
            SnippetFileStore.shared.save()
            SnippetFileStore.shared.reload()
            restoreDefault(originalShowLabels, forKey: CMPrefShowLabelsInMenuKey)
            restoreDefault(originalAddClearHistory, forKey: CMPrefAddClearHistoryMenuItemKey)
            restoreDefault(originalPositionOfSnippets, forKey: CMPrefPositionOfSnippetsKey)
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            restoreDefault(originalInlineCount, forKey: CMPrefNumberOfItemsPlaceInlineKey)
            restoreDefault(originalFolderCount, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
            restoreDefault(originalMarkNumbers, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
            restoreDefault(originalStartsFromZero, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
            restoreDefault(originalNumericKeys, forKey: CMPrefAddNumericKeyEquivalentsKey)
            debugCapturePopupMenus = originalDebugCapturePopupMenus
            debugCapturedPopupMenuSummaries = originalDebugCapturedPopupMenuSummaries
            actionTarget = originalActionTarget
            previousPasteTargetApplication = originalPreviousPasteTargetApplication
            previousFrontProcessSerialNumber = originalPreviousFrontProcessSerialNumber
            CMReloadActionPreferences()
            rebuildMenu()
            NSApp.terminate(nil)
        }

        defaults.set(true, forKey: CMPrefShowLabelsInMenuKey)
        defaults.set(true, forKey: CMPrefAddClearHistoryMenuItemKey)
        defaults.set(CMPositionOfSnippets.aboveClips.rawValue, forKey: CMPrefPositionOfSnippetsKey)
        defaults.set(1, forKey: CMPrefMaxHistorySizeKey)
        defaults.set(1, forKey: CMPrefNumberOfItemsPlaceInlineKey)
        defaults.set(10, forKey: CMPrefNumberOfItemsPlaceInsideFolderKey)
        defaults.set(true, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        defaults.set(false, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        defaults.set(false, forKey: CMPrefAddNumericKeyEquivalentsKey)
        try? FileManager.default.removeItem(at: actionsURL)
        CMReloadActionPreferences()
        clipsStore.clear()
        let textClip = ClipItem(
            types: [NSPasteboard.PasteboardType.string.rawValue],
            createdAt: Date(timeIntervalSinceReferenceDate: 100),
            lastUsedAt: Date(timeIntervalSinceReferenceDate: 100),
            text: "public-action-clip"
        )
        clipsStore.add(textClip)
        SnippetFileStore.shared.folders = [
            SnippetFolder(
                title: "Public Actions",
                isEnabled: true,
                snippets: [
                    Snippet(title: "Public Greeting", content: "Hello from public action", isEnabled: true)
                ]
            )
        ]
        SnippetFileStore.shared.save()
        SnippetFileStore.shared.reload()

        debugCapturePopupMenus = true
        debugCapturedPopupMenuSummaries.removeAll()
        popUpClipMenu(nil)
        let mainCapture = debugCapturedPopupMenuSummaries.last ?? [:]

        debugCapturedPopupMenuSummaries.removeAll()
        popUpHistoryMenu(nil)
        let historyCapture = debugCapturedPopupMenuSummaries.last ?? [:]

        debugCapturedPopupMenuSummaries.removeAll()
        popUpSnippetsMenu(nil)
        let snippetsCapture = debugCapturedPopupMenuSummaries.last ?? [:]

        let actionSender = makeClipMenuItem(clip: textClip, globalIndex: 0, listNumber: 1)
        debugCapturedPopupMenuSummaries.removeAll()
        popUpActionMenu(actionSender)
        let actionCapture = debugCapturedPopupMenuSummaries.last ?? [:]

        let popUpClipMenuSelector = #selector(popUpClipMenu(_:))
        let popUpActionMenuSelector = #selector(popUpActionMenu(_:))
        let popUpHistoryMenuSelector = #selector(popUpHistoryMenu(_:))
        let popUpSnippetsMenuSelector = #selector(popUpSnippetsMenu(_:))
        let keepCurrentFrontProcessSelector = #selector(keepCurrentFrontProcessAndActivate)
        let restorePreviousFrontProcessSelector = #selector(restorePreviousFrontProcess)

        resetPreviousFrontProcessSerialNumber()
        let restoreWithoutStoredTarget = restorePreviousFrontProcess()
        let storedFrontProcessBeforeActivate = hasStoredPreviousFrontProcessSerialNumber()
        keepCurrentFrontProcessAndActivate()
        let storedFrontProcessAfterActivate = hasStoredPreviousFrontProcessSerialNumber()
        let restoreAfterStoredTarget = restorePreviousFrontProcess()
        let storedFrontProcessAfterRestore = hasStoredPreviousFrontProcessSerialNumber()
        let localizedSnippetsTitle = NSLocalizedString("Snippets", comment: "")
        let localizedHistoryTitle = NSLocalizedString("History", comment: "")
        let localizedClearHistoryTitle = NSLocalizedString("Clear History", comment: "")
        let localizedEditSnippetsTitle = NSLocalizedString("Edit Snippets...", comment: "")
        let localizedPreferencesTitle = NSLocalizedString("Preferences...", comment: "")
        let localizedQuitTitle = NSLocalizedString("Quit ClipMenu", comment: "")
        let localizedPasteAsPlainTextTitle = NSLocalizedString("Paste as Plain Text", comment: "")
        let localizedRemoveTitle = NSLocalizedString("Remove", comment: "")
        let expectedMainMenuCapture: [String: Any] = [
            "menuTitle": "ClipMenu",
            "style": "hotKey",
            "topLevelCount": 11,
            "topLevelTitles": [
                localizedSnippetsTitle,
                "Public Actions",
                "<separator>",
                localizedHistoryTitle,
                "1. public-action-clip",
                "<separator>",
                localizedClearHistoryTitle,
                localizedEditSnippetsTitle,
                localizedPreferencesTitle,
                "<separator>",
                localizedQuitTitle
            ],
            "submenuTitlesByParent": [
                "Public Actions": ["1. Public Greeting"]
            ]
        ]
        let expectedHistoryMenuCapture: [String: Any] = [
            "menuTitle": "HistoryMenu",
            "style": "hotKey",
            "topLevelCount": 2,
            "topLevelTitles": [
                localizedHistoryTitle,
                "1. public-action-clip"
            ],
            "submenuTitlesByParent": [String: [String]]()
        ]
        let expectedSnippetsMenuCapture: [String: Any] = [
            "menuTitle": "SnippetsMenu",
            "style": "hotKey",
            "topLevelCount": 2,
            "topLevelTitles": [
                localizedSnippetsTitle,
                "Public Actions"
            ],
            "submenuTitlesByParent": [
                "Public Actions": ["1. Public Greeting"]
            ]
        ]
        let expectedActionMenuCapture: [String: Any] = [
            "menuTitle": "ActionMenu",
            "style": "action",
            "topLevelCount": 4,
            "topLevelTitles": [
                localizedPasteAsPlainTextTitle,
                "Case",
                "Trim",
                localizedRemoveTitle
            ],
            "submenuTitlesByParent": [
                "Case": [
                    "Capitalize.js",
                    "lowercase.js",
                    "Title Case.js",
                    "UPPERCASE.js"
                ],
                "Trim": [
                    "LTrim.js",
                    "RTrim.js",
                    "Trim.js"
                ]
            ]
        ]
        let mainScreenLocation = mainCapture["screenLocation"] as? [String: Any]
        let historyScreenLocation = historyCapture["screenLocation"] as? [String: Any]
        let snippetsScreenLocation = snippetsCapture["screenLocation"] as? [String: Any]
        let actionScreenLocation = actionCapture["screenLocation"] as? [String: Any]
        let sharedScreenLocationMatchesExpected = {
            guard let mainX = mainScreenLocation?["x"] as? NSNumber,
                  let mainY = mainScreenLocation?["y"] as? NSNumber,
                  let historyX = historyScreenLocation?["x"] as? NSNumber,
                  let historyY = historyScreenLocation?["y"] as? NSNumber,
                  let snippetsX = snippetsScreenLocation?["x"] as? NSNumber,
                  let snippetsY = snippetsScreenLocation?["y"] as? NSNumber,
                  let actionX = actionScreenLocation?["x"] as? NSNumber,
                  let actionY = actionScreenLocation?["y"] as? NSNumber else {
                return false
            }

            return mainX == historyX
                && mainY == historyY
                && mainX == snippetsX
                && mainY == snippetsY
                && mainX == actionX
                && mainY == actionY
        }()

        let report: [String: Any] = [
            "respondsToPopUpClipMenu": responds(to: popUpClipMenuSelector),
            "respondsToPopUpActionMenu": responds(to: popUpActionMenuSelector),
            "respondsToPopUpHistoryMenu": responds(to: popUpHistoryMenuSelector),
            "respondsToPopUpSnippetsMenu": responds(to: popUpSnippetsMenuSelector),
            "respondsToKeepCurrentFrontProcessAndActivate": responds(to: keepCurrentFrontProcessSelector),
            "respondsToRestorePreviousFrontProcess": responds(to: restorePreviousFrontProcessSelector),
            "restorePreviousFrontProcessWithoutStoredTargetReturnsTrue": restoreWithoutStoredTarget,
            "storedFrontProcessBeforeActivate": storedFrontProcessBeforeActivate,
            "storedFrontProcessAfterActivate": storedFrontProcessAfterActivate,
            "restorePreviousFrontProcessAfterStoredTargetReturnsTrue": restoreAfterStoredTarget,
            "storedFrontProcessAfterRestore": storedFrontProcessAfterRestore,
            "mainMenuCapture": mainCapture,
            "historyMenuCapture": historyCapture,
            "snippetsMenuCapture": snippetsCapture,
            "actionMenuCapture": actionCapture,
            "expectedMainMenuCapture": expectedMainMenuCapture,
            "expectedHistoryMenuCapture": expectedHistoryMenuCapture,
            "expectedSnippetsMenuCapture": expectedSnippetsMenuCapture,
            "expectedActionMenuCapture": expectedActionMenuCapture,
            "sharedScreenLocationMatchesExpected": sharedScreenLocationMatchesExpected,
            "matchesExpected": NSDictionary(dictionary: mainCapture).dictionaryWithValues(forKeys: ["menuTitle", "style", "topLevelCount", "topLevelTitles", "submenuTitlesByParent"]) as NSDictionary == expectedMainMenuCapture as NSDictionary
                && NSDictionary(dictionary: historyCapture).dictionaryWithValues(forKeys: ["menuTitle", "style", "topLevelCount", "topLevelTitles", "submenuTitlesByParent"]) as NSDictionary == expectedHistoryMenuCapture as NSDictionary
                && NSDictionary(dictionary: snippetsCapture).dictionaryWithValues(forKeys: ["menuTitle", "style", "topLevelCount", "topLevelTitles", "submenuTitlesByParent"]) as NSDictionary == expectedSnippetsMenuCapture as NSDictionary
                && NSDictionary(dictionary: actionCapture).dictionaryWithValues(forKeys: ["menuTitle", "style", "topLevelCount", "topLevelTitles", "submenuTitlesByParent"]) as NSDictionary == expectedActionMenuCapture as NSDictionary
                && responds(to: popUpClipMenuSelector)
                && responds(to: popUpActionMenuSelector)
                && responds(to: popUpHistoryMenuSelector)
                && responds(to: popUpSnippetsMenuSelector)
                && responds(to: keepCurrentFrontProcessSelector)
                && responds(to: restorePreviousFrontProcessSelector)
                && sharedScreenLocationMatchesExpected
                && restoreWithoutStoredTarget
                && !storedFrontProcessBeforeActivate
                && storedFrontProcessAfterActivate
                && restoreAfterStoredTarget
                && !storedFrontProcessAfterRestore
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugUpdatePreferencesAvailabilityReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugUpdatePreferencesAvailabilityReportPath")
            ?? "/tmp/clipmenu-update-preferences-availability-report.json")
        let originalAutomaticChecks = defaults.object(forKey: CMEnableAutomaticCheckKey)
        let originalPreReleases = defaults.object(forKey: CMEnableAutomaticCheckPreReleaseKey)
        let originalAutomaticallyInstallUpdates = defaults.object(forKey: CMAutomaticallyInstallUpdatesKey)

        defer {
            restoreDefault(originalAutomaticChecks, forKey: CMEnableAutomaticCheckKey)
            restoreDefault(originalPreReleases, forKey: CMEnableAutomaticCheckPreReleaseKey)
            restoreDefault(originalAutomaticallyInstallUpdates, forKey: CMAutomaticallyInstallUpdatesKey)
            NSApp.terminate(nil)
        }

        showPreferencePanel(nil)

        let feedURLPresent = UpdateCoordinator.shared.feedURL != nil
        defaults.set(false, forKey: CMEnableAutomaticCheckKey)
        let disabledState = CMUpdatePreferencesAvailabilityReport(
            automaticChecks: false,
            feedURLPresent: feedURLPresent,
            isChecking: false
        )

        defaults.set(true, forKey: CMEnableAutomaticCheckKey)
        let enabledState = CMUpdatePreferencesAvailabilityReport(
            automaticChecks: true,
            feedURLPresent: feedURLPresent,
            isChecking: false
        )

        let checkingState = CMUpdatePreferencesAvailabilityReport(
            automaticChecks: true,
            feedURLPresent: feedURLPresent,
            isChecking: true
        )
        let expectedDisabledState: [String: Bool] = [
            "preReleasesEnabled": false,
            "automaticallyInstallUpdatesEnabled": false,
            "intervalEnabled": false,
            "checkNowEnabled": false
        ]
        let expectedEnabledState: [String: Bool] = [
            "preReleasesEnabled": true,
            "automaticallyInstallUpdatesEnabled": true,
            "intervalEnabled": true,
            "checkNowEnabled": feedURLPresent
        ]
        let expectedCheckingState: [String: Bool] = [
            "preReleasesEnabled": true,
            "automaticallyInstallUpdatesEnabled": true,
            "intervalEnabled": true,
            "checkNowEnabled": false
        ]

        let report: [String: Any] = [
            "feedURLPresent": feedURLPresent,
            "disabledState": disabledState,
            "enabledState": enabledState,
            "checkingState": checkingState,
            "expectedDisabledState": expectedDisabledState,
            "expectedEnabledState": expectedEnabledState,
            "expectedCheckingState": expectedCheckingState,
            "automaticChecksOffDisablesDependentControls": (disabledState as NSDictionary) == (expectedDisabledState as NSDictionary),
            "automaticChecksOnEnablesDependentControlsWhenFeedPresent": (enabledState as NSDictionary) == (expectedEnabledState as NSDictionary),
            "checkingStateDisablesCheckNow": (checkingState as NSDictionary) == (expectedCheckingState as NSDictionary),
            "matchesExpected": (disabledState as NSDictionary) == (expectedDisabledState as NSDictionary)
                && (enabledState as NSDictionary) == (expectedEnabledState as NSDictionary)
                && (checkingState as NSDictionary) == (expectedCheckingState as NSDictionary)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

