    private func runDebugInstalledSparkleCompatibilityReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugInstalledSparkleCompatibilityReportPath")
            ?? "/tmp/clipmenu-installed-sparkle-compatibility-report.json")
        let sparkleURL = URL(fileURLWithPath: "/Applications/ClipMenu.app/Contents/Frameworks/Sparkle.framework/Versions/A/Sparkle")
        let sparkleExists = FileManager.default.fileExists(atPath: sparkleURL.path)
        let currentArchitecture = currentDebugArchitecture()
        let lipoResult = debugCommandResult(
            launchPath: "/usr/bin/lipo",
            arguments: ["-archs", sparkleURL.path]
        )
        let architectures = lipoResult.output
            .split(whereSeparator: \.isWhitespace)
            .map(String.init)

        dlerror()
        let handle = dlopen(sparkleURL.path, RTLD_NOW | RTLD_LOCAL)
        let dlopenSucceeded = handle != nil
        let dlopenError = dlopenSucceeded ? "" : String(cString: dlerror())
        if let handle {
            dlclose(handle)
        }

        let containsCurrentArchitecture = currentArchitecture.map { architectures.contains($0) } ?? false
        let hostIsArm64 = currentArchitecture == "arm64"
        let actualState: [String: Any] = [
            "sparkleExists": sparkleExists,
            "currentArchitecture": currentArchitecture as Any,
            "containsCurrentArchitecture": containsCurrentArchitecture,
            "dlopenSucceeded": dlopenSucceeded
        ]
        let expectedState: [String: Any] = hostIsArm64
            ? [
                "sparkleExists": true,
                "currentArchitecture": "arm64",
                "containsCurrentArchitecture": false,
                "dlopenSucceeded": false
            ]
            : [
                "sparkleExists": sparkleExists,
                "currentArchitecture": currentArchitecture as Any,
                "containsCurrentArchitecture": containsCurrentArchitecture,
                "dlopenSucceeded": dlopenSucceeded
            ]
        let matchesExpectedOnCurrentHost = hostIsArm64
            ? (actualState as NSDictionary).isEqual(to: expectedState)
            : sparkleExists

        let report: [String: Any] = [
            "sparklePath": sparkleURL.path,
            "sparkleExists": sparkleExists,
            "currentArchitecture": currentArchitecture as Any,
            "architectures": architectures,
            "containsCurrentArchitecture": containsCurrentArchitecture,
            "lipoExitStatus": lipoResult.status as Any,
            "lipoError": lipoResult.error,
            "dlopenSucceeded": dlopenSucceeded,
            "dlopenError": dlopenError,
            "hostIsArm64": hostIsArm64,
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpectedOnCurrentHost": matchesExpectedOnCurrentHost,
            "matchesExpected": matchesExpectedOnCurrentHost
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
        NSApp.terminate(nil)
    }

    private func runDebugDefaultsShapeReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugDefaultsShapeReportPath")
            ?? "/tmp/clipmenu-defaults-shape-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        let legacyHotKeys = defaults.object(forKey: CMPrefLegacyHotKeysKey) as? [String: [String: Int]] ?? [:]
        let legacyActions = defaults.array(forKey: CMPrefLegacyActionsKey) as? [[String: Any]] ?? []
        let persistentDefaults = Bundle.main.bundleIdentifier.flatMap { defaults.persistentDomain(forName: $0) } ?? [:]
        let actionsPlistExists = FileManager.default.fileExists(atPath: supportDirectory.appendingPathComponent("actions.plist").path)

        let modernSplitHotKeys: [String: Any] = [
            "clipMenuEnabled": defaults.bool(forKey: CMPrefHotKeyEnabledKey),
            "clipMenuKeyCode": defaults.integer(forKey: CMPrefHotKeyKeyCodeKey),
            "clipMenuModifierFlags": defaults.integer(forKey: CMPrefHotKeyModifierFlagsKey),
            "historyEnabled": defaults.bool(forKey: CMPrefHistoryHotKeyEnabledKey),
            "historyKeyCode": defaults.integer(forKey: CMPrefHistoryHotKeyKeyCodeKey),
            "historyModifierFlags": defaults.integer(forKey: CMPrefHistoryHotKeyModifierFlagsKey),
            "snippetsEnabled": defaults.bool(forKey: CMPrefSnippetsHotKeyEnabledKey),
            "snippetsKeyCode": defaults.integer(forKey: CMPrefSnippetsHotKeyKeyCodeKey),
            "snippetsModifierFlags": defaults.integer(forKey: CMPrefSnippetsHotKeyModifierFlagsKey)
        ]
        let expectedLegacyActionPlaceholder: [String: Any] = [
            "name": "removeAction",
            "path": ""
        ]
        let expectedModernSplitHotKeys: [String: Any] = [
            "clipMenuEnabled": true,
            "clipMenuKeyCode": 9,
            "clipMenuModifierFlags": Int(NSEvent.ModifierFlags([.command, .shift]).rawValue),
            "historyEnabled": true,
            "historyKeyCode": 9,
            "historyModifierFlags": Int(NSEvent.ModifierFlags([.command, .control]).rawValue),
            "snippetsEnabled": true,
            "snippetsKeyCode": 11,
            "snippetsModifierFlags": Int(NSEvent.ModifierFlags([.command, .shift]).rawValue)
        ]
        let actualState: [String: Any] = [
            "legacyHotKeys": legacyHotKeys,
            "legacyActions": legacyActions,
            "modernSplitHotKeys": modernSplitHotKeys,
            "persistentDefaultsContainLegacyHotKeys": persistentDefaults[CMPrefLegacyHotKeysKey] != nil,
            "persistentDefaultsContainLegacyActions": persistentDefaults[CMPrefLegacyActionsKey] != nil,
            "actionsPlistExists": actionsPlistExists
        ]
        let expectedState: [String: Any] = [
            "legacyHotKeys": AppController.defaultLegacyHotKeys(),
            "legacyActions": [expectedLegacyActionPlaceholder],
            "modernSplitHotKeys": expectedModernSplitHotKeys,
            "persistentDefaultsContainLegacyHotKeys": false,
            "persistentDefaultsContainLegacyActions": false,
            "actionsPlistExists": true
        ]
        let matchesExpected = NSDictionary(dictionary: actualState).isEqual(to: expectedState)

        let report: [String: Any] = [
            "legacyHotKeys": legacyHotKeys,
            "legacyActions": legacyActions,
            "legacyHotKeysMatchExpected": legacyHotKeys == AppController.defaultLegacyHotKeys(),
            "legacyActionsMatchExpected": legacyActions.count == 1
                && NSDictionary(dictionary: legacyActions[0]).isEqual(to: expectedLegacyActionPlaceholder),
            "modernSplitHotKeys": modernSplitHotKeys,
            "expectedModernSplitHotKeys": expectedModernSplitHotKeys,
            "modernSplitHotKeysMatchExpected": NSDictionary(dictionary: modernSplitHotKeys).isEqual(to: expectedModernSplitHotKeys),
            "persistentDefaultsContainLegacyHotKeys": persistentDefaults[CMPrefLegacyHotKeysKey] != nil,
            "persistentDefaultsContainLegacyActions": persistentDefaults[CMPrefLegacyActionsKey] != nil,
            "actionsPlistExists": actionsPlistExists,
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
        NSApp.terminate(nil)
    }

    private func currentDebugArchitecture() -> String? {
        var systemInfo = utsname()
        guard uname(&systemInfo) == 0 else { return nil }
        return withUnsafePointer(to: &systemInfo.machine) {
            $0.withMemoryRebound(to: CChar.self, capacity: Int(_SYS_NAMELEN)) {
                String(cString: $0)
            }
        }
    }

    private func debugCommandResult(launchPath: String, arguments: [String]) -> (status: Int32?, output: String, error: String) {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: launchPath)
        process.arguments = arguments

        let outputPipe = Pipe()
        let errorPipe = Pipe()
        process.standardOutput = outputPipe
        process.standardError = errorPipe

        do {
            try process.run()
            process.waitUntilExit()
        } catch {
            return (nil, "", error.localizedDescription)
        }

        let outputData = outputPipe.fileHandleForReading.readDataToEndOfFile()
        let errorData = errorPipe.fileHandleForReading.readDataToEndOfFile()
        let output = String(data: outputData, encoding: .utf8)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let error = String(data: errorData, encoding: .utf8)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return (process.terminationStatus, output, error)
    }

    private func writeDebugRTFPasteboard(_ pasteboard: NSPasteboard) -> Bool {
        let string = NSAttributedString(
            string: "Rich Smoke",
            attributes: [
                .font: NSFont.boldSystemFont(ofSize: 13),
                .foregroundColor: NSColor.systemRed
            ]
        )
        guard let data = string.rtf(from: NSRange(location: 0, length: string.length), documentAttributes: [:]) else {
            return false
        }
        pasteboard.clearContents()
        pasteboard.declareTypes([.rtf, .string], owner: nil)
        pasteboard.setData(data, forType: .rtf)
        pasteboard.setString("Rich Smoke", forType: .string)
        return true
    }

