    private func runDebugSnippetMenuLiveStateReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugSnippetMenuLiveStateReportPath")
            ?? "/tmp/clipmenu-snippet-menu-live-state-report.json")
        let store = SnippetFileStore.shared
        store.reload()

        defer {
            store.reload()
            NSApp.terminate(nil)
        }

        let firstFolderID = store.folders.first?.id ?? store.addFolder()
        guard let firstFolderIndex = store.folders.firstIndex(where: { $0.id == firstFolderID }) else {
            let report = ["error": "Could not create or locate a snippet folder"]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        var updatedFolder = store.folders[firstFolderIndex]
        let unsavedFolderTitle = "debug unsaved folder"
        updatedFolder.title = unsavedFolderTitle
        store.updateFolder(id: firstFolderID, to: updatedFolder)

        store.notePrimaryFolder(firstFolderID)
        store.selectedFolderIDs = [firstFolderID]

        let snippetID: UUID
        if let existingSnippetID = store.folders[firstFolderIndex].snippets.first?.id {
            snippetID = existingSnippetID
        } else if let addedSnippetID = store.addSnippet() {
            snippetID = addedSnippetID
        } else {
            let report = ["error": "Could not create or select a snippet for the first folder"]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        guard let mutatedFolderIndex = store.folders.firstIndex(where: { $0.id == firstFolderID }),
              let mutatedSnippetIndex = store.folders[mutatedFolderIndex].snippets.firstIndex(where: { $0.id == snippetID }) else {
            let report = ["error": "Could not locate mutated snippet state"]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        var updatedSnippet = store.folders[mutatedFolderIndex].snippets[mutatedSnippetIndex]
        let unsavedSnippetTitle = "debug unsaved snippet"
        updatedSnippet.title = unsavedSnippetTitle
        updatedSnippet.content = "debug unsaved snippet content"
        store.updateSnippet(folderID: firstFolderID, snippetID: snippetID, to: updatedSnippet)

        let menu = NSMenu(title: "DebugSnippetsMenu")
        let addedSnippets = addSnippets(to: menu)
        let folderItems = menu.items.filter { $0.submenu != nil }
        let menuFolderTitles = folderItems.map(\.title)
        let menuSnippetItems = folderItems.flatMap { item in
            item.submenu?.items ?? []
        }
        let menuSnippetTitles = menuSnippetItems.map(\.title)
        let menuSnippetTooltips = menuSnippetItems.compactMap(\.toolTip)
        let matchesExpected =
            addedSnippets
            && store.hasUnsavedChanges
            && menuFolderTitles.contains(unsavedFolderTitle)
            && menuSnippetTitles.contains { $0.contains(trimmedSnippetMenuTitle(for: unsavedSnippetTitle)) }
            && menuSnippetTooltips.contains(updatedSnippet.content)

        let report: [String: Any] = [
            "addedSnippets": addedSnippets,
            "storeHasUnsavedChanges": store.hasUnsavedChanges,
            "unsavedFolderTitle": unsavedFolderTitle,
            "unsavedSnippetTitle": unsavedSnippetTitle,
            "menuFolderTitles": menuFolderTitles,
            "menuSnippetTitles": menuSnippetTitles,
            "menuSnippetTooltips": menuSnippetTooltips,
            "menuContainsUnsavedFolderTitle": menuFolderTitles.contains(unsavedFolderTitle),
            "menuContainsUnsavedSnippetTitle": menuSnippetTitles.contains { $0.contains(trimmedSnippetMenuTitle(for: unsavedSnippetTitle)) },
            "menuContainsUnsavedSnippetContent": menuSnippetTooltips.contains(updatedSnippet.content),
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

