    private func runDebugHomeIsolationReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugHomeIsolationReportPath")
            ?? "/tmp/clipmenu-home-isolation-report.json")
        let environment = ProcessInfo.processInfo.environment
        let supportDirectory = clipMenuApplicationSupportDirectory()
        let fileManager = FileManager.default
        let expectedHomePath = (environment["CFFIXED_USER_HOME"] ?? environment["HOME"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let standardizedExpectedHomePath = expectedHomePath.isEmpty
            ? ""
            : URL(fileURLWithPath: expectedHomePath, isDirectory: true).standardizedFileURL.path
        let standardizedSupportDirectoryPath = supportDirectory.standardizedFileURL.path
        let usedSupportDirectoryOverride = debugHasSupportDirectoryOverride()
        let supportDirectoryIsInsideExpectedHome = standardizedExpectedHomePath.isEmpty
            ? false
            : standardizedSupportDirectoryPath == standardizedExpectedHomePath
                || standardizedSupportDirectoryPath.hasPrefix(standardizedExpectedHomePath + "/")
        let clipsDataExists = fileManager.fileExists(atPath: supportDirectory.appendingPathComponent("clips.data").path)
        let clipsJSONExists = fileManager.fileExists(atPath: supportDirectory.appendingPathComponent("clips.json").path)
        let snippetsJSONExists = fileManager.fileExists(atPath: supportDirectory.appendingPathComponent("snippets.json").path)
        let actionsPlistExists = fileManager.fileExists(atPath: supportDirectory.appendingPathComponent("actions.plist").path)
        let matchesExpected = usedSupportDirectoryOverride
            ? !supportDirectoryIsInsideExpectedHome
            : supportDirectoryIsInsideExpectedHome

        let report: [String: Any] = [
            "environmentHOME": environment["HOME"] as Any,
            "environmentCFFIXED_USER_HOME": environment["CFFIXED_USER_HOME"] as Any,
            "supportDirectory": standardizedSupportDirectoryPath,
            "usedSupportDirectoryOverride": usedSupportDirectoryOverride,
            "supportDirectoryIsInsideExpectedHome": supportDirectoryIsInsideExpectedHome,
            "clipsCountAfterLaunch": clipsStore.clips.count,
            "clipsDataExists": clipsDataExists,
            "clipsJSONExists": clipsJSONExists,
            "snippetsJSONExists": snippetsJSONExists,
            "actionsPlistExists": actionsPlistExists,
            "matchesExpected": matchesExpected
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        NSApp.terminate(nil)
    }

