    private func runDebugHiddenStatusItemHotKeyReport() {
        let defaults = UserDefaults.standard
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugHiddenStatusItemHotKeyReportPath")
            ?? "/tmp/clipmenu-hidden-status-item-hotkey-report.json")
        let originalTag = defaults.integer(forKey: CMPrefShowStatusItemKey)

        defer {
            defaults.set(originalTag, forKey: CMPrefShowStatusItemKey)
            configureStatusItem()
            rebuildMenu()
            NSApp.terminate(nil)
        }

        defaults.set(0, forKey: CMPrefShowStatusItemKey)
        configureStatusItem()

        let statusItemPresentBefore = statusItem != nil
        let attachedMenuTitleBefore = statusItem?.menu?.title ?? ""

        let menu = makeMainMenu()
        if defaults.integer(forKey: CMPrefShowStatusItemKey) != 0 {
            if statusItem == nil {
                configureStatusItem()
            }
            statusItem?.menu = menu
        }

        let statusItemPresentAfter = statusItem != nil
        let attachedMenuTitleAfter = statusItem?.menu?.title ?? ""

        let report: [String: Any] = [
            "statusItemPresentBeforeSimulatedHotKeyBranch": statusItemPresentBefore,
            "statusItemPresentAfterSimulatedHotKeyBranch": statusItemPresentAfter,
            "attachedMenuTitleBeforeSimulatedHotKeyBranch": attachedMenuTitleBefore,
            "attachedMenuTitleAfterSimulatedHotKeyBranch": attachedMenuTitleAfter,
            "menuTopLevelCount": menu.items.count,
            "showStatusItemTag": defaults.integer(forKey: CMPrefShowStatusItemKey),
            "statusItemRemainsDetachedWhenHidden": !statusItemPresentBefore && !statusItemPresentAfter && attachedMenuTitleAfter.isEmpty,
            "matchesExpected": !statusItemPresentBefore && !statusItemPresentAfter && attachedMenuTitleAfter.isEmpty
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

