    private func runDebugBundledActionTransformReport() {
        struct BundledActionCase {
            let category: String
            let relativePath: String
            let input: String
            let expectedOutput: String
            let trimOutput: Bool
        }

        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugBundledActionTransformReportPath")
            ?? "/tmp/clipmenu-bundled-action-transform-report.json")
        let cases: [BundledActionCase] = [
            .init(category: "case", relativePath: "Case/UPPERCASE.js", input: "alpha Beta\nMiXeD", expectedOutput: "ALPHA BETA\nMIXED", trimOutput: false),
            .init(category: "case", relativePath: "Case/lowercase.js", input: "Alpha Beta\nMiXeD", expectedOutput: "alpha beta\nmixed", trimOutput: false),
            .init(category: "case", relativePath: "Case/Capitalize.js", input: "hELLO wORLD\nmULTI line", expectedOutput: "Hello world\nMulti line", trimOutput: false),
            .init(category: "case", relativePath: "Case/Title Case.js", input: "message properties\nwar and peace", expectedOutput: "Message Properties\nWar and Peace", trimOutput: false),
            .init(category: "trim", relativePath: "Trim/Trim.js", input: "  padded text  ", expectedOutput: "padded text", trimOutput: false),
            .init(category: "trim", relativePath: "Trim/LTrim.js", input: "  padded text  ", expectedOutput: "padded text  ", trimOutput: false),
            .init(category: "trim", relativePath: "Trim/RTrim.js", input: "  padded text  ", expectedOutput: "  padded text", trimOutput: false),
            .init(category: "trim", relativePath: "Collapse Spaces.js", input: "  too   many    spaces  ", expectedOutput: "too many spaces", trimOutput: false),
            .init(category: "surround", relativePath: "Surround with/\" \".js", input: "clip", expectedOutput: "\"clip\"", trimOutput: false),
            .init(category: "surround", relativePath: "Surround with/[ ].js", input: "clip", expectedOutput: "[clip]", trimOutput: false),
            .init(category: "surround", relativePath: "Surround with/{ }.js", input: "clip", expectedOutput: "{clip}", trimOutput: false),
            .init(category: "surround", relativePath: "Surround with (Japanese)/「 」.js", input: "clip", expectedOutput: "「clip」", trimOutput: false),
            .init(category: "html", relativePath: "HTML/Strip Tags.js", input: "<b>Hello</b><i>There</i>", expectedOutput: "HelloThere", trimOutput: false),
            .init(category: "html", relativePath: "HTML/Escape HTML characters.js", input: "<a&b>", expectedOutput: "&lt;a&amp;b&gt;", trimOutput: false),
            .init(category: "html", relativePath: "HTML/Unescape HTML characters.js", input: "&lt;a&amp;b&gt;", expectedOutput: "<a&b>", trimOutput: false),
            .init(category: "html", relativePath: "HTML/Encode URI component.js", input: "a b+c", expectedOutput: "a%20b%2Bc", trimOutput: false),
            .init(category: "html", relativePath: "HTML/Decode URI component.js", input: "a%20b%2Bc", expectedOutput: "a b+c", trimOutput: false),
            .init(category: "html", relativePath: "HTML/Convert Markdown to HTML.js", input: "Hello", expectedOutput: "<p>Hello</p>", trimOutput: true),
            .init(category: "html", relativePath: "HTML/Convert Character to Decimal.js", input: "Aあ", expectedOutput: "&#65;&#12354;", trimOutput: false),
            .init(category: "html", relativePath: "HTML/Convert Decimal to Character.js", input: "&#65;&#12354;", expectedOutput: "Aあ", trimOutput: false),
            .init(category: "crypt", relativePath: "Crypt/Calculate MD5 hash.js", input: "clipmenu", expectedOutput: "554e9ab34e37d31d68e40ae1ea474868", trimOutput: false),
            .init(category: "crypt", relativePath: "Crypt/Calculate SHA-1 hash.js", input: "clipmenu", expectedOutput: "6f4f3eade51c2c6e5ff1ff599c27b7a769541075", trimOutput: false),
            .init(category: "crypt", relativePath: "Crypt/Encode to Base64.js", input: "clipmenu", expectedOutput: "Y2xpcG1lbnU=", trimOutput: false),
            .init(category: "crypt", relativePath: "Crypt/Decode from Base64.js", input: "Y2xpcG1lbnU=", expectedOutput: "clipmenu", trimOutput: false),
            .init(category: "japanese", relativePath: "Japanese/Convert Hiragana to Katakana.js", input: "こんにちは", expectedOutput: "コンニチハ", trimOutput: false),
            .init(category: "japanese", relativePath: "Japanese/Convert Katakana to Hiragana.js", input: "コンニチハ", expectedOutput: "こんにちは", trimOutput: false),
            .init(category: "japanese", relativePath: "Japanese/Convert Hankaku alphanumeric characters to Zenkaku.js", input: "ABC123", expectedOutput: "ＡＢＣ１２３", trimOutput: false),
            .init(category: "japanese", relativePath: "Japanese/Convert Zenkaku alphanumeric characters to Hankaku.js", input: "ＡＢＣ１２３", expectedOutput: "ABC123", trimOutput: false),
            .init(category: "japanese", relativePath: "Japanese/Convert Hankaku katakana to Zenkaku katakana.js", input: "ｶﾀｶﾅ", expectedOutput: "カタカナ", trimOutput: false),
            .init(category: "japanese", relativePath: "Japanese/Convert Zenkaku katakana to Hankaku katakana.js", input: "カタカナ", expectedOutput: "ｶﾀｶﾅ", trimOutput: false)
        ]

        func normalizedOutput(_ text: String, trim: Bool) -> String {
            guard trim else { return text }
            return text.trimmingCharacters(in: .whitespacesAndNewlines)
        }

        var caseReports: [[String: Any]] = []
        var categoryMatches: [String: Bool] = [:]
        var allMatched = true

        for actionCase in cases {
            let result = runJavaScriptAction(
                at: "script/action/\(actionCase.relativePath)",
                clip: ClipItem(text: actionCase.input)
            )
            let output = result?.text ?? ""
            let matched = normalizedOutput(output, trim: actionCase.trimOutput) == actionCase.expectedOutput
            allMatched = allMatched && matched
            categoryMatches[actionCase.category] = (categoryMatches[actionCase.category] ?? true) && matched
            caseReports.append([
                "category": actionCase.category,
                "relativePath": actionCase.relativePath,
                "input": actionCase.input,
                "expectedOutput": actionCase.expectedOutput,
                "output": output,
                "matchesExpected": matched
            ])
        }

        let report: [String: Any] = [
            "cases": caseReports,
            "caseMatchesExpected": categoryMatches["case"] ?? false,
            "trimMatchesExpected": categoryMatches["trim"] ?? false,
            "surroundMatchesExpected": categoryMatches["surround"] ?? false,
            "htmlMatchesExpected": categoryMatches["html"] ?? false,
            "cryptMatchesExpected": categoryMatches["crypt"] ?? false,
            "japaneseMatchesExpected": categoryMatches["japanese"] ?? false,
            "matchesExpected": allMatched
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        NSApp.terminate(nil)
    }

    private func runDebugUserActionDiscoveryReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugUserActionDiscoveryReportPath")
            ?? "/tmp/clipmenu-user-action-discovery-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let fileManager = FileManager.default
        let actionsFileURL = supportDirectory.appendingPathComponent("actions.plist")
        let actionFolderURL = supportDirectory
            .appendingPathComponent("script/action", isDirectory: true)
            .appendingPathComponent("User Fixture", isDirectory: true)
        let actionScriptURL = actionFolderURL.appendingPathComponent("Fixture Script.js")
        let originalClips = clipsStore.clips
        let originalActionTarget = actionTarget

        defer {
            actionTarget = originalActionTarget
            clipsStore.clear()
            originalClips.forEach { clipsStore.add($0) }
            try? fileManager.removeItem(at: actionsFileURL)
            try? fileManager.removeItem(at: actionScriptURL)
            try? fileManager.removeItem(at: actionFolderURL)
            try? fileManager.removeItem(at: supportDirectory.appendingPathComponent("script", isDirectory: true))
            CMReloadActionPreferences()
            rebuildMenu()
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
        }

        do {
            try fileManager.createDirectory(at: actionFolderURL, withIntermediateDirectories: true)
            try """
            return clip.stringValue.toUpperCase() + " via user";
            """.write(to: actionScriptURL, atomically: true, encoding: .utf8)
            try? fileManager.removeItem(at: actionsFileURL)
        } catch {
            report["error"] = error.localizedDescription
            return
        }

        CMReloadActionPreferences()
        let discoveredUserTitles = CMCurrentUserReservedActionTitles()
        let addedFixtureAction = CMAddUserReservedActionForTesting(path: "User Fixture")
        if addedFixtureAction {
            CMCommitActionPreferences()
        }

        let clip = ClipItem(text: "user action smoke")
        clipsStore.add(clip)
        actionTarget = .clip(clip.id)

        let runtimeNodes = loadRuntimeActionNodes()
        let actionMenu = makeActionMenu()
        let fixtureFolderItem = actionMenu.items.first { $0.title == "User Fixture" }
        let fixtureScriptItem = fixtureFolderItem?.submenu?.items.first { $0.title == "Fixture Script" }
        let result = runJavaScriptAction(at: "script/action/User Fixture/Fixture Script.js", clip: clip)

        report["userReservedTitles"] = discoveredUserTitles
        report["addedFixtureActionToMenu"] = addedFixtureAction
        report["runtimeTopLevelTitles"] = runtimeNodes.map(\.nodeTitle)
        report["menuTopLevelTitles"] = actionMenu.items.map(\.title)
        report["menuContainsUserFixtureFolder"] = fixtureFolderItem != nil
        report["menuContainsUserFixtureScript"] = fixtureScriptItem != nil
        report["resolvedUserScriptPath"] = resolvedActionScriptURL(for: "script/action/User Fixture/Fixture Script.js")?.path ?? ""
        report["resultText"] = result?.text ?? ""
        let actualState: [String: Any] = [
            "userReservedTitles": discoveredUserTitles,
            "addedFixtureActionToMenu": addedFixtureAction,
            "runtimeContainsUserFixtureFolder": runtimeNodes.contains(where: { $0.nodeTitle == "User Fixture" }),
            "menuContainsUserFixtureScript": fixtureScriptItem != nil,
            "resolvedUserScriptPath": resolvedActionScriptURL(for: "script/action/User Fixture/Fixture Script.js")?.path ?? "",
            "resultText": result?.text ?? ""
        ]
        let expectedState: [String: Any] = [
            "userReservedTitles": ["User Fixture", "User Fixture/Fixture Script"],
            "addedFixtureActionToMenu": true,
            "runtimeContainsUserFixtureFolder": true,
            "menuContainsUserFixtureScript": true,
            "resolvedUserScriptPath": actionScriptURL.path,
            "resultText": "USER ACTION SMOKE via user"
        ]
        report["state"] = actualState
        report["expectedState"] = expectedState
        report["matchesExpected"] = NSDictionary(dictionary: actualState).isEqual(to: expectedState)
    }

    private func runDebugActionDiscoveryOrderReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugActionDiscoveryOrderReportPath")
            ?? "/tmp/clipmenu-action-discovery-order-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let fileManager = FileManager.default
        let scriptRootURL = supportDirectory.appendingPathComponent("script", isDirectory: true)
        let userActionRootURL = scriptRootURL.appendingPathComponent("action", isDirectory: true)
        let bundledActionRootURL = Bundle.main.resourceURL?.appendingPathComponent("script/action", isDirectory: true)

        func expectedEnumerationPaths(in directoryURL: URL, prefix: [String] = []) -> [String] {
            guard let contents = try? fileManager.contentsOfDirectory(
                at: directoryURL,
                includingPropertiesForKeys: [.isDirectoryKey],
                options: [.skipsHiddenFiles]
            ) else {
                return []
            }

            return contents.flatMap { url -> [String] in
                let resourceValues = try? url.resourceValues(forKeys: [.isDirectoryKey])
                let title = NSLocalizedString(url.deletingPathExtension().lastPathComponent, comment: "")
                let path = prefix + [title]
                let joinedPath = path.joined(separator: "/")

                if resourceValues?.isDirectory == true {
                    return [joinedPath] + expectedEnumerationPaths(in: url, prefix: path)
                }

                guard url.pathExtension == "js" else { return [] }
                return [joinedPath]
            }
        }

        do {
            try? fileManager.removeItem(at: scriptRootURL)
            try fileManager.createDirectory(at: userActionRootURL, withIntermediateDirectories: true)

            let betaFolderURL = userActionRootURL.appendingPathComponent("Beta Folder", isDirectory: true)
            try fileManager.createDirectory(at: betaFolderURL, withIntermediateDirectories: true)
            try "return 'beta-zeta';".write(
                to: betaFolderURL.appendingPathComponent("Zeta Script.js"),
                atomically: true,
                encoding: .utf8
            )
            try "return 'beta-alpha';".write(
                to: betaFolderURL.appendingPathComponent("Alpha Script.js"),
                atomically: true,
                encoding: .utf8
            )

            try "return 'middle';".write(
                to: userActionRootURL.appendingPathComponent("Middle Script.js"),
                atomically: true,
                encoding: .utf8
            )

            let alphaFolderURL = userActionRootURL.appendingPathComponent("Alpha Folder", isDirectory: true)
            try fileManager.createDirectory(at: alphaFolderURL, withIntermediateDirectories: true)
            try "return 'alpha-omega';".write(
                to: alphaFolderURL.appendingPathComponent("Omega Script.js"),
                atomically: true,
                encoding: .utf8
            )

            try "return 'last';".write(
                to: userActionRootURL.appendingPathComponent("Last Script.js"),
                atomically: true,
                encoding: .utf8
            )
        } catch {
            report["error"] = error.localizedDescription
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        defer {
            try? fileManager.removeItem(at: scriptRootURL)
            CMReloadActionPreferences()
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
        }

        CMReloadActionPreferences()

        let actualUserPaths = CMCurrentUserReservedActionTitles()
        let expectedUserPaths = expectedEnumerationPaths(in: userActionRootURL)
        report["actualUserPaths"] = actualUserPaths
        report["expectedUserPaths"] = expectedUserPaths
        report["userMatchesFilesystemEnumeration"] = actualUserPaths == expectedUserPaths

        if let bundledActionRootURL {
            let actualBundledPaths = CMCurrentBundledReservedActionTitles()
            let expectedBundledPaths = expectedEnumerationPaths(in: bundledActionRootURL)
            let actualState: [String: Any] = [
                "userPaths": actualUserPaths,
                "bundledPaths": actualBundledPaths
            ]
            let expectedState: [String: Any] = [
                "userPaths": expectedUserPaths,
                "bundledPaths": expectedBundledPaths
            ]
            let matchesExpected = NSDictionary(dictionary: actualState).isEqual(to: expectedState)
            report["actualBundledPaths"] = actualBundledPaths
            report["expectedBundledPaths"] = expectedBundledPaths
            report["bundledMatchesFilesystemEnumeration"] = actualBundledPaths == expectedBundledPaths
            report["state"] = actualState
            report["expectedState"] = expectedState
            report["matchesExpected"] = matchesExpected
        } else {
            report["error"] = "Bundled action root not available"
            report["matchesExpected"] = false
        }
    }

    private func runDebugReservedActionBrowserReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugReservedActionBrowserReportPath")
            ?? "/tmp/clipmenu-reserved-action-browser-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        showPreferencePanel(nil)

        let settleDelay = debugOneShotDoubleValue(forKey: "debugReservedActionBrowserReportSettleDelay") ?? 0.3
        DispatchQueue.main.asyncAfter(deadline: .now() + settleDelay) {
            let fileManager = FileManager.default
            let scriptRootURL = supportDirectory.appendingPathComponent("script", isDirectory: true)
            let userActionRootURL = scriptRootURL.appendingPathComponent("action", isDirectory: true)

            func flushMainRunLoop() {
                RunLoop.main.run(until: Date(timeIntervalSinceNow: 0.05))
            }

            do {
                try? fileManager.removeItem(at: scriptRootURL)
                let userFolderURL = userActionRootURL.appendingPathComponent("User Fixture", isDirectory: true)
                let nestedFolderURL = userFolderURL.appendingPathComponent("Inner Folder", isDirectory: true)
                try fileManager.createDirectory(at: nestedFolderURL, withIntermediateDirectories: true)
                try "return 'first';".write(
                    to: userFolderURL.appendingPathComponent("First Script.js"),
                    atomically: true,
                    encoding: .utf8
                )
                try "return 'second';".write(
                    to: nestedFolderURL.appendingPathComponent("Second Script.js"),
                    atomically: true,
                    encoding: .utf8
                )
            } catch {
                report["error"] = error.localizedDescription
                if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                    try? data.write(to: reportURL, options: .atomic)
                }
                NSApp.terminate(nil)
                return
            }

            defer {
                try? fileManager.removeItem(at: scriptRootURL)
                CMReloadActionPreferences()
                if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                    try? data.write(to: reportURL, options: .atomic)
                }
                NSApp.terminate(nil)
            }

            CMReloadActionPreferences()
            ActionTreePresentationState.shared.resetForTesting()
            flushMainRunLoop()

            let switchedToBundled = CMSetReservedActionKindForTesting("bundled")
            flushMainRunLoop()
            CMSetExpandedReservedPreferencePathsForTesting(["Case"])
            flushMainRunLoop()
            let bundledExpandedBeforeSwitch = CMCurrentExpandedReservedPreferencePaths()

            let switchedToBuiltin = CMSetReservedActionKindForTesting("builtin")
            flushMainRunLoop()
            let switchedBackToBundled = CMSetReservedActionKindForTesting("bundled")
            flushMainRunLoop()
            let bundledExpandedAfterReturn = CMCurrentExpandedReservedPreferencePaths()

            CMSetExpandedReservedPreferencePathsForTesting([])
            flushMainRunLoop()
            let selectedBundledLeaf = CMSelectReservedActionPreferenceNodeForTesting(path: "Case/UPPERCASE")
            flushMainRunLoop()
            let bundledExpandedAfterSelection = CMCurrentExpandedReservedPreferencePaths()
            let bundledLeafSnapshot = CMCurrentActionInspectorSnapshotForTesting()

            let switchedToUser = CMSetReservedActionKindForTesting("user")
            flushMainRunLoop()
            CMSetExpandedReservedPreferencePathsForTesting(["User Fixture", "User Fixture/Inner Folder"])
            flushMainRunLoop()
            let userExpandedBeforeSwitch = CMCurrentExpandedReservedPreferencePaths()
            let switchedAwayFromUser = CMSetReservedActionKindForTesting("bundled")
            flushMainRunLoop()
            let switchedBackToUser = CMSetReservedActionKindForTesting("user")
            flushMainRunLoop()
            let userExpandedAfterReturn = CMCurrentExpandedReservedPreferencePaths()

            CMSetExpandedReservedPreferencePathsForTesting([])
            flushMainRunLoop()
            let selectedUserLeaf = CMSelectReservedActionPreferenceNodeForTesting(path: "User Fixture/Inner Folder/Second Script")
            flushMainRunLoop()
            let userExpandedAfterSelection = CMCurrentExpandedReservedPreferencePaths()
            let userLeafSnapshot = CMCurrentActionInspectorSnapshotForTesting()

            report["bundledExpandedBeforeSwitch"] = bundledExpandedBeforeSwitch
            report["bundledExpandedAfterReturn"] = bundledExpandedAfterReturn
            report["bundledExpansionPersistsAcrossKindSwitch"] =
                switchedToBundled
                && switchedToBuiltin
                && switchedBackToBundled
                && bundledExpandedBeforeSwitch == ["Case"]
                && bundledExpandedAfterReturn == ["Case"]

            report["bundledExpandedAfterSelection"] = bundledExpandedAfterSelection
            report["bundledLeafSnapshot"] = bundledLeafSnapshot as Any
            report["bundledSelectionAutoExpandsAncestors"] =
                selectedBundledLeaf
                && bundledExpandedAfterSelection == ["Case"]
                && (bundledLeafSnapshot?["rowSubtitle"] as? String) == "UPPERCASE.js"
                && (bundledLeafSnapshot?["rowBadgeTitle"] as? String) == NSLocalizedString("755.labels[1]", tableName: "Preferences", bundle: .main, value: "JavaScript", comment: "")

            report["userExpandedBeforeSwitch"] = userExpandedBeforeSwitch
            report["userExpandedAfterReturn"] = userExpandedAfterReturn
            report["userExpansionPersistsAcrossKindSwitch"] =
                switchedToUser
                && switchedAwayFromUser
                && switchedBackToUser
                && userExpandedBeforeSwitch == ["User Fixture", "User Fixture/Inner Folder"]
                && userExpandedAfterReturn == ["User Fixture", "User Fixture/Inner Folder"]

            report["userExpandedAfterSelection"] = userExpandedAfterSelection
            report["userLeafSnapshot"] = userLeafSnapshot as Any
            report["userSelectionAutoExpandsAncestors"] =
                selectedUserLeaf
                && userExpandedAfterSelection == ["User Fixture", "User Fixture/Inner Folder"]
                && (userLeafSnapshot?["rowSubtitle"] as? String) == NSLocalizedString("User JavaScript action", comment: "")
                && (userLeafSnapshot?["rowBadgeTitle"] as? String) == NSLocalizedString("755.labels[2]", tableName: "Preferences", bundle: .main, value: "User's", comment: "")
                && (userLeafSnapshot?["type"] as? String) == NSLocalizedString("755.labels[2]", tableName: "Preferences", bundle: .main, value: "User's", comment: "")

            let actualState: [String: Any] = [
                "bundledExpandedBeforeSwitch": bundledExpandedBeforeSwitch,
                "bundledExpandedAfterReturn": bundledExpandedAfterReturn,
                "bundledExpandedAfterSelection": bundledExpandedAfterSelection,
                "userExpandedBeforeSwitch": userExpandedBeforeSwitch,
                "userExpandedAfterReturn": userExpandedAfterReturn,
                "userExpandedAfterSelection": userExpandedAfterSelection
            ]
            let expectedState: [String: Any] = [
                "bundledExpandedBeforeSwitch": ["Case"],
                "bundledExpandedAfterReturn": ["Case"],
                "bundledExpandedAfterSelection": ["Case"],
                "userExpandedBeforeSwitch": ["User Fixture", "User Fixture/Inner Folder"],
                "userExpandedAfterReturn": ["User Fixture", "User Fixture/Inner Folder"],
                "userExpandedAfterSelection": ["User Fixture", "User Fixture/Inner Folder"]
            ]
            report["state"] = actualState
            report["expectedState"] = expectedState
            report["matchesExpected"] = NSDictionary(dictionary: actualState).isEqual(to: expectedState)
        }
    }

    private func runDebugTypedClipRenderingReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugTypedClipRenderingReportPath")
            ?? "/tmp/clipmenu-typed-clip-rendering-report.json")
        let defaults = UserDefaults.standard
        let originalShowIcon = defaults.object(forKey: CMPrefShowIconInTheMenuKey)
        let originalShowImage = defaults.object(forKey: CMPrefShowImageInTheMenuKey)
        let originalShowToolTip = defaults.object(forKey: CMPrefShowToolTipOnMenuItemKey)
        let originalMarkNumbers = defaults.object(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        let originalStartWithZero = defaults.object(forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        let originalMaxTitleLength = defaults.object(forKey: CMPrefMaxMenuItemTitleLengthKey)
        let originalMaxTooltipLength = defaults.object(forKey: CMPrefMaxLengthOfToolTipKey)
        let originalMenuIconTagForPDF = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForPDFKey)
        let originalMenuIconTypeForPDF = defaults.object(forKey: CMPrefMenuIconOfFileTypeForPDFKey)
        let originalMenuIconTagForFilenames = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey)
        let originalMenuIconTypeForFilenames = defaults.object(forKey: CMPrefMenuIconOfFileTypeForFilenamesKey)
        let originalMenuIconTagForURL = defaults.object(forKey: CMPrefMenuIconOfFileTypeTagForURLKey)
        let originalMenuIconTypeForURL = defaults.object(forKey: CMPrefMenuIconOfFileTypeForURLKey)

        defer {
            restoreDefault(originalShowIcon, forKey: CMPrefShowIconInTheMenuKey)
            restoreDefault(originalShowImage, forKey: CMPrefShowImageInTheMenuKey)
            restoreDefault(originalShowToolTip, forKey: CMPrefShowToolTipOnMenuItemKey)
            restoreDefault(originalMarkNumbers, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
            restoreDefault(originalStartWithZero, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
            restoreDefault(originalMaxTitleLength, forKey: CMPrefMaxMenuItemTitleLengthKey)
            restoreDefault(originalMaxTooltipLength, forKey: CMPrefMaxLengthOfToolTipKey)
            restoreDefault(originalMenuIconTagForPDF, forKey: CMPrefMenuIconOfFileTypeTagForPDFKey)
            restoreDefault(originalMenuIconTypeForPDF, forKey: CMPrefMenuIconOfFileTypeForPDFKey)
            restoreDefault(originalMenuIconTagForFilenames, forKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey)
            restoreDefault(originalMenuIconTypeForFilenames, forKey: CMPrefMenuIconOfFileTypeForFilenamesKey)
            restoreDefault(originalMenuIconTagForURL, forKey: CMPrefMenuIconOfFileTypeTagForURLKey)
            restoreDefault(originalMenuIconTypeForURL, forKey: CMPrefMenuIconOfFileTypeForURLKey)
            NSApp.terminate(nil)
        }

        defaults.set(true, forKey: CMPrefShowIconInTheMenuKey)
        defaults.set(false, forKey: CMPrefShowImageInTheMenuKey)
        defaults.set(true, forKey: CMPrefShowToolTipOnMenuItemKey)
        defaults.set(true, forKey: CMPrefMenuItemsAreMarkedWithNumbersKey)
        defaults.set(false, forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        defaults.set(80, forKey: CMPrefMaxMenuItemTitleLengthKey)
        defaults.set(80, forKey: CMPrefMaxLengthOfToolTipKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForPDFKey)
        defaults.set("PDF ", forKey: CMPrefMenuIconOfFileTypeForPDFKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey)
        defaults.set("fold", forKey: CMPrefMenuIconOfFileTypeForFilenamesKey)
        defaults.set(1, forKey: CMPrefMenuIconOfFileTypeTagForURLKey)
        defaults.set("gurl", forKey: CMPrefMenuIconOfFileTypeForURLKey)

        let pdfPasteboard = NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.render.pdf.\(UUID().uuidString)"))
        let filePasteboard = NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.render.file.\(UUID().uuidString)"))
        let urlPasteboard = NSPasteboard(name: NSPasteboard.Name("com.naotaka.ClipMenu.debug.render.url.\(UUID().uuidString)"))

        guard writeDebugPDFPasteboard(pdfPasteboard),
              writeDebugFileURLPasteboard(filePasteboard),
              writeDebugURLPasteboard(urlPasteboard) else {
            let report = ["error": "Could not seed typed clip rendering fixture"]
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            return
        }

        let pdfClip = ClipItem.fromPasteboard(pdfPasteboard)
        let fileClip = ClipItem.fromPasteboard(filePasteboard)
        let urlClip = ClipItem.fromPasteboard(urlPasteboard)

        func itemReport(for clip: ClipItem?, index: Int) -> [String: Any] {
            guard let clip else {
                return ["captured": false]
            }
            let item = makeClipMenuItem(clip: clip, globalIndex: index, listNumber: index + 1)
            return [
                "captured": true,
                "primaryPasteboardType": clip.primaryPasteboardType?.rawValue as Any,
                "title": item.title,
                "toolTip": item.toolTip as Any,
                "hasImage": item.image != nil,
                "imageIsTemplate": item.image?.isTemplate as Any,
                "text": clip.text,
                "filenames": clip.filenames as Any,
                "urls": clip.urls as Any
            ]
        }

        let pdfReport = itemReport(for: pdfClip, index: 0)
        let fileReport = itemReport(for: fileClip, index: 1)
        let urlReport = itemReport(for: urlClip, index: 2)
        let actualState: [String: Any] = [
            "pdf": [
                "title": pdfReport["title"] as? String ?? "",
                "toolTip": pdfReport["toolTip"] as? String ?? "",
                "hasImage": pdfReport["hasImage"] as? Bool ?? false
            ],
            "fileURL": [
                "title": fileReport["title"] as? String ?? "",
                "toolTip": fileReport["toolTip"] as? String ?? "",
                "hasImage": fileReport["hasImage"] as? Bool ?? false,
                "filenames": fileReport["filenames"] as? [String] ?? []
            ],
            "url": [
                "title": urlReport["title"] as? String ?? "",
                "toolTip": urlReport["toolTip"] as? String ?? "",
                "hasImage": urlReport["hasImage"] as? Bool ?? false,
                "urls": urlReport["urls"] as? [String] ?? []
            ]
        ]
        let expectedState: [String: Any] = [
            "pdf": [
                "title": "1. (PDF)",
                "toolTip": "",
                "hasImage": true
            ],
            "fileURL": [
                "title": "2. (Filenames)",
                "toolTip": "",
                "hasImage": true,
                "filenames": ["/tmp/clipmenu-debug-file.txt"]
            ],
            "url": [
                "title": "3. https://example.com/clipmenu-debug",
                "toolTip": "https://example.com/clipmenu-debug",
                "hasImage": true,
                "urls": ["https://example.com/clipmenu-debug"]
            ]
        ]
        let report: [String: Any] = [
            "pdf": pdfReport,
            "fileURL": fileReport,
            "url": urlReport,
            "state": actualState,
            "expectedState": expectedState,
            "matchesExpected": NSDictionary(dictionary: actualState).isEqual(to: expectedState)
        ]

        if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }
    }

    private func runDebugRelaunchPersistenceReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugRelaunchPersistenceReportPath")
            ?? "/tmp/clipmenu-relaunch-persistence-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        let stageURL = supportDirectory.appendingPathComponent("debug-relaunch-persistence-stage.json")
        let clipsDataURL = supportDirectory.appendingPathComponent("clips.data")
        let clipsJSONURL = supportDirectory.appendingPathComponent("clips.json")
        let fileManager = FileManager.default
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        func makeDeterministicClip(text: String, seconds: TimeInterval) -> ClipItem {
            let date = Date(timeIntervalSinceReferenceDate: seconds)
            return ClipItem(text: text, createdAt: date, lastUsedAt: date)
        }

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let defaults = UserDefaults.standard

        if !fileManager.fileExists(atPath: stageURL.path) {
            let expectedLoadedTexts = ["relaunch-gamma", "relaunch-beta"]

            do {
                try fileManager.createDirectory(at: supportDirectory, withIntermediateDirectories: true)
                try? fileManager.removeItem(at: stageURL)
                clipsStore.clear()
                clipsStore.removeSavedHistory()
                defaults.set(2, forKey: CMPrefMaxHistorySizeKey)
                defaults.set(true, forKey: CMPrefSaveHistoryOnQuitKey)
                clipsStore.add(makeDeterministicClip(text: "relaunch-alpha", seconds: 100))
                clipsStore.add(makeDeterministicClip(text: "relaunch-beta", seconds: 200))
                clipsStore.add(makeDeterministicClip(text: "relaunch-gamma", seconds: 300))

                let stage: [String: Any] = [
                    "phase": "seeded",
                    "seededOrderedTextsBeforeQuit": clipsStore.orderedClips.map(\.text),
                    "expectedLoadedTextsAfterRelaunch": expectedLoadedTexts,
                    "maxHistorySize": 2
                ]
                let data = try JSONSerialization.data(withJSONObject: stage, options: [.prettyPrinted, .sortedKeys])
                try data.write(to: stageURL, options: .atomic)
                report["phase"] = "seeded"
                report["seededOrderedTextsBeforeQuit"] = stage["seededOrderedTextsBeforeQuit"] as Any
                report["expectedLoadedTextsAfterRelaunch"] = expectedLoadedTexts
                report["maxHistorySize"] = 2
                report["matchesExpected"] = false
                if let reportData = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                    try? reportData.write(to: reportURL, options: .atomic)
                }
            } catch {
                report["error"] = error.localizedDescription
                if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                    try? data.write(to: reportURL, options: .atomic)
                }
                NSApp.terminate(nil)
                return
            }

            NSApp.terminate(nil)
            return
        }

        defer {
            try? fileManager.removeItem(at: stageURL)
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
        }

        guard let data = try? Data(contentsOf: stageURL),
              let stage = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            report["error"] = "could not decode relaunch stage file"
            return
        }

        let seededOrderedTextsBeforeQuit = stage["seededOrderedTextsBeforeQuit"] as? [String] ?? []
        let expectedLoadedTexts = stage["expectedLoadedTextsAfterRelaunch"] as? [String] ?? []
        let loadedTexts = clipsStore.orderedClips.map(\.text)
        let actualState: [String: Any] = [
            "seededOrderedTextsBeforeQuit": seededOrderedTextsBeforeQuit,
            "loadedTextsAfterRelaunch": loadedTexts,
            "clipsDataExistsAfterRelaunch": fileManager.fileExists(atPath: clipsDataURL.path),
            "clipsJSONExistsAfterRelaunch": fileManager.fileExists(atPath: clipsJSONURL.path),
            "maxHistorySizeAfterRelaunch": defaults.integer(forKey: CMPrefMaxHistorySizeKey),
            "saveHistoryOnQuitAfterRelaunch": defaults.bool(forKey: CMPrefSaveHistoryOnQuitKey)
        ]
        let expectedState: [String: Any] = [
            "seededOrderedTextsBeforeQuit": ["relaunch-gamma", "relaunch-beta"],
            "loadedTextsAfterRelaunch": expectedLoadedTexts,
            "clipsDataExistsAfterRelaunch": true,
            "clipsJSONExistsAfterRelaunch": true,
            "maxHistorySizeAfterRelaunch": 2,
            "saveHistoryOnQuitAfterRelaunch": true
        ]

        report["phase"] = "verified"
        report["seededOrderedTextsBeforeQuit"] = seededOrderedTextsBeforeQuit
        report["expectedLoadedTextsAfterRelaunch"] = expectedLoadedTexts
        report["loadedTextsAfterRelaunch"] = loadedTexts
        report["clipsDataExistsAfterRelaunch"] = fileManager.fileExists(atPath: clipsDataURL.path)
        report["clipsJSONExistsAfterRelaunch"] = fileManager.fileExists(atPath: clipsJSONURL.path)
        report["maxHistorySizeAfterRelaunch"] = defaults.integer(forKey: CMPrefMaxHistorySizeKey)
        report["saveHistoryOnQuitAfterRelaunch"] = defaults.bool(forKey: CMPrefSaveHistoryOnQuitKey)
        report["state"] = actualState
        report["expectedState"] = expectedState
        report["matchesExpected"] = NSDictionary(dictionary: actualState).isEqual(to: expectedState)
    }

