    private func runDebugLegacyClipMigrationReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugLegacyClipMigrationReportPath")
            ?? "/tmp/clipmenu-legacy-clip-migration-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let fileManager = FileManager.default
        let legacyURL = supportDirectory.appendingPathComponent("clips.data")
        let jsonURL = supportDirectory.appendingPathComponent("clips.json")
        let defaults = UserDefaults.standard
        let originalMaxHistorySize = defaults.object(forKey: CMPrefMaxHistorySizeKey)

        defer {
            restoreDefault(originalMaxHistorySize, forKey: CMPrefMaxHistorySizeKey)
            try? fileManager.removeItem(at: legacyURL)
            try? fileManager.removeItem(at: jsonURL)
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
        }

        do {
            try fileManager.createDirectory(at: supportDirectory, withIntermediateDirectories: true)
            try? fileManager.removeItem(at: legacyURL)
            try? fileManager.removeItem(at: jsonURL)

            let fixtures = [
                DebugLegacyArchiveClip(
                    types: ["NSStringPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 100),
                    stringValue: "legacy-string"
                ),
                DebugLegacyArchiveClip(
                    types: ["NSRTFPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 200),
                    stringValue: "legacy-rtf",
                    rtfData: Data("{\\rtf1\\ansi legacy-rtf}".utf8)
                ),
                DebugLegacyArchiveClip(
                    types: ["NSPDFPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 300),
                    stringValue: "legacy-pdf",
                    pdfData: Data("legacy-pdf".utf8)
                ),
                DebugLegacyArchiveClip(
                    types: ["NSFilenamesPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 400),
                    stringValue: "legacy-files",
                    filenames: ["/tmp/legacy-a.txt", "/tmp/legacy-b.txt"]
                ),
                DebugLegacyArchiveClip(
                    types: ["Apple URL pasteboard type"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 500),
                    stringValue: "legacy-url",
                    urls: ["https://example.com/legacy"]
                ),
                DebugLegacyArchiveClip(
                    types: ["NSPICTPboardType"],
                    createdDate: Date(timeIntervalSinceReferenceDate: 600),
                    stringValue: "legacy-image",
                    imageData: Data([0x01, 0x02, 0x03, 0x04])
                )
            ]
            let legacyData = try DebugLegacyArchiveClip.archivedData(for: fixtures)
            try legacyData.write(to: legacyURL, options: .atomic)
        } catch {
            report["error"] = error.localizedDescription
            return
        }

        defaults.set(20, forKey: CMPrefMaxHistorySizeKey)
        let untrimmedStore = ClipStore()
        untrimmedStore.load()
