        let untrimmedPrimaryTypes = untrimmedStore.orderedClips.compactMap { $0.primaryPasteboardType?.rawValue }
        let untrimmedCountsByType = Dictionary(
            grouping: untrimmedStore.orderedClips,
            by: { $0.primaryPasteboardType?.rawValue ?? "" }
        ).mapValues(\.count)

        defaults.set(3, forKey: CMPrefMaxHistorySizeKey)
        let trimmedStore = ClipStore()
        trimmedStore.load()
        let trimmedOrderedTexts = trimmedStore.orderedClips.map(\.text)

        report["legacyArchiveExistsAfterWrite"] = fileManager.fileExists(atPath: legacyURL.path)
        report["jsonSidecarExistsAfterLoad"] = fileManager.fileExists(atPath: jsonURL.path)
        report["untrimmedCount"] = untrimmedStore.clips.count
        report["untrimmedOrderedTexts"] = untrimmedOrderedTexts
        report["untrimmedPrimaryTypes"] = untrimmedPrimaryTypes
        report["untrimmedCountsByPrimaryType"] = untrimmedCountsByType
        report["trimmedCount"] = trimmedStore.clips.count
        report["trimmedOrderedTexts"] = trimmedOrderedTexts
        let actualState: [String: Any] = [
            "legacyArchiveExistsAfterWrite": fileManager.fileExists(atPath: legacyURL.path),
            "jsonSidecarExistsAfterLoad": fileManager.fileExists(atPath: jsonURL.path),
            "untrimmedOrderedTexts": untrimmedOrderedTexts,
            "untrimmedPrimaryTypes": untrimmedPrimaryTypes,
            "untrimmedCountsByPrimaryType": untrimmedCountsByType,
            "trimmedOrderedTexts": trimmedOrderedTexts
        ]
        let expectedState: [String: Any] = [
            "legacyArchiveExistsAfterWrite": true,
            "jsonSidecarExistsAfterLoad": true,
            "untrimmedOrderedTexts": [
                "legacy-image",
                "legacy-url",
                "legacy-files",
                "legacy-pdf",
                "legacy-rtf",
                "legacy-string"
