    private func runDebugLegacyActionMenuMigrationReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugLegacyActionMenuMigrationReportPath")
            ?? "/tmp/clipmenu-legacy-actionmenu-migration-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        let fileManager = FileManager.default
        let actionsFileURL = supportDirectory.appendingPathComponent("actions.plist")
        let legacyArchiveURL = supportDirectory.appendingPathComponent("actionMenu.data")
        let scriptDirectoryURL = supportDirectory
            .appendingPathComponent("script/action", isDirectory: true)
            .appendingPathComponent("Legacy Fixture", isDirectory: true)
        let scriptURL = scriptDirectoryURL.appendingPathComponent("Legacy Upper.js")

        let clip = ClipItem(text: "legacy action smoke")
        clipsStore.add(clip)
        actionTarget = .clip(clip.id)

        defer {
            actionTarget = nil
            clipsStore.remove(clip.id)
            try? fileManager.removeItem(at: actionsFileURL)
            try? fileManager.removeItem(at: legacyArchiveURL)
            try? fileManager.removeItem(at: scriptURL)
            try? fileManager.removeItem(at: scriptDirectoryURL)
            rebuildMenu()
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
        }

        do {
            try fileManager.createDirectory(at: scriptDirectoryURL, withIntermediateDirectories: true)
            try "return clip.stringValue.toUpperCase();"
                .write(to: scriptURL, atomically: true, encoding: .utf8)
            try? fileManager.removeItem(at: actionsFileURL)

            let removeNode = LegacyRuntimeArchivedActionNode()
            removeNode.nodeTitle = "Remove"
            removeNode.isLeaf = true
            removeNode.action = ["name": "removeAction"]

            let scriptNode = LegacyRuntimeArchivedActionNode()
            scriptNode.nodeTitle = "Legacy Upper"
            scriptNode.isLeaf = true
            scriptNode.action = ["path": scriptURL.path]

            let folderNode = LegacyRuntimeArchivedActionNode()
            folderNode.nodeTitle = "Legacy Fixture"
            folderNode.isLeaf = false
            folderNode.children = [scriptNode]

            let archiveData = try NSKeyedArchiver.archivedData(
                withRootObject: [removeNode, folderNode],
                requiringSecureCoding: false
            )
            try archiveData.write(to: legacyArchiveURL, options: .atomic)
        } catch {
            report["error"] = error.localizedDescription
            return
        }

        let nodes = loadRuntimeActionNodes()
        report["topLevelTitles"] = nodes.map(\.nodeTitle)
        report["topLevelTypes"] = nodes.map { $0.action?["type"] ?? "folder" }
        report["removeActionName"] = nodes.first?.action?["name"] ?? ""
        report["folderChildTitles"] = nodes.dropFirst().first?.children.map(\.nodeTitle) ?? []
        report["folderChildActionTypes"] = nodes.dropFirst().first?.children.map { $0.action?["type"] ?? "" } ?? []

        let menu = makeActionMenu()
        report["menuTopLevelTitles"] = menu.items.map(\.title)
        let legacyFolderItem = menu.items.first { $0.title == "Legacy Fixture" }
        let legacyScriptItem = legacyFolderItem?.submenu?.items.first { $0.title == "Legacy Upper" }
        report["menuContainsLegacyFolder"] = legacyFolderItem != nil
        report["menuContainsLegacyScript"] = legacyScriptItem != nil

        if let action = legacyScriptItem?.representedObject as? [String: String] {
            report["legacyScriptActionPath"] = action["path"] ?? ""
            let result = action["path"].flatMap { path in
                runJavaScriptAction(at: path, clip: clip)
            }
            report["resultText"] = result?.text ?? ""
            report["resultMatchesExpected"] = result?.text == "LEGACY ACTION SMOKE"
        }

        let actualState: [String: Any] = [
            "topLevelTitles": report["topLevelTitles"] as? [String] ?? [],
            "topLevelTypes": report["topLevelTypes"] as? [String] ?? [],
            "removeActionName": report["removeActionName"] as? String ?? "",
            "folderChildTitles": report["folderChildTitles"] as? [String] ?? [],
            "folderChildActionTypes": report["folderChildActionTypes"] as? [String] ?? [],
            "menuContainsLegacyFolder": report["menuContainsLegacyFolder"] as? Bool ?? false,
            "menuContainsLegacyScript": report["menuContainsLegacyScript"] as? Bool ?? false,
            "legacyScriptActionPath": report["legacyScriptActionPath"] as? String ?? "",
            "resultText": report["resultText"] as? String ?? ""
        ]
        let expectedState: [String: Any] = [
            "topLevelTitles": [NSLocalizedString("Remove", comment: ""), "Legacy Fixture"],
            "topLevelTypes": ["builtin", "folder"],
            "removeActionName": "remove:",
            "folderChildTitles": ["Legacy Upper"],
            "folderChildActionTypes": ["js"],
            "menuContainsLegacyFolder": true,
            "menuContainsLegacyScript": true,
            "legacyScriptActionPath": scriptURL.path,
            "resultText": "LEGACY ACTION SMOKE"
        ]
        report["state"] = actualState
        report["expectedState"] = expectedState
        report["matchesExpected"] = NSDictionary(dictionary: actualState).isEqual(to: expectedState)
    }

