    private func runDebugQuitMenuItemReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugQuitMenuItemReportPath")
            ?? "/tmp/clipmenu-quit-menu-item-report.json")
        var report: [String: Any] = [
            "supportDirectory": clipMenuApplicationSupportDirectory().path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        let menu = makeMainMenu()
        let topLevelTitles = menu.items.map(\.title)
        let quitItem = menu.items.first { $0.title == NSLocalizedString("Quit ClipMenu", comment: "") }

        report["topLevelTitles"] = topLevelTitles
        report["quitItemFound"] = quitItem != nil
        report["quitItemAction"] = quitItem?.action.map(NSStringFromSelector) ?? ""
        report["quitItemTargetClass"] = quitItem?.target.map { String(describing: type(of: $0)) } ?? ""
        report["quitItemTargetIsApplication"] = quitItem?.target === NSApp
        report["attemptedSendAction"] = false
        report["applicationShouldTerminateCalled"] = false
        report["applicationWillTerminateCalled"] = false
        report["terminationPersistenceHandledAtWillTerminate"] = false

        guard let quitItem, let action = quitItem.action else {
            report["sendActionReturned"] = false
            report["fallbackTriggered"] = false
            report["matchesExpected"] = false
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        debugQuitMenuItemReportURL = reportURL
        debugQuitMenuItemReport = report
        debugQuitMenuItemReportDidInvokeTerminate = true
        debugQuitMenuItemReport["attemptedSendAction"] = true
        debugQuitMenuItemReport["sendActionReturned"] = NSApp.sendAction(action, to: quitItem.target, from: quitItem)

        DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) { [weak self] in
            guard let self else { return }
            guard self.debugQuitMenuItemReportDidInvokeTerminate,
                  !self.debugQuitMenuItemReportDidWrite else { return }
            self.finalizeDebugQuitMenuItemReport(fallbackTriggered: true)
            NSApp.terminate(nil)
        }
    }

    private func finalizeDebugQuitMenuItemReport(fallbackTriggered: Bool) {
        guard let reportURL = debugQuitMenuItemReportURL,
              !debugQuitMenuItemReportDidWrite else { return }

        debugQuitMenuItemReport["fallbackTriggered"] = fallbackTriggered
        let attemptedSendAction = debugQuitMenuItemReport["attemptedSendAction"] as? Bool ?? false
        let shouldTerminateCalled = debugQuitMenuItemReport["applicationShouldTerminateCalled"] as? Bool ?? false
        let willTerminateCalled = debugQuitMenuItemReport["applicationWillTerminateCalled"] as? Bool ?? false
        let targetIsApplication = debugQuitMenuItemReport["quitItemTargetIsApplication"] as? Bool ?? false
        debugQuitMenuItemReport["matchesExpected"] =
            attemptedSendAction
            && shouldTerminateCalled
            && willTerminateCalled
            && targetIsApplication
            && !fallbackTriggered

        if let data = try? JSONSerialization.data(withJSONObject: debugQuitMenuItemReport, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: reportURL, options: .atomic)
        }

        debugQuitMenuItemReportDidWrite = true
        debugQuitMenuItemReportDidInvokeTerminate = false
        debugQuitMenuItemReportURL = nil
    }

