    private func runDebugTerminationPersistenceReport() {
        let reportURL = URL(fileURLWithPath: debugOneShotStringValue(forKey: "debugTerminationPersistenceReportPath")
            ?? "/tmp/clipmenu-termination-persistence-report.json")
        let supportDirectory = clipMenuApplicationSupportDirectory()
        let fileManager = FileManager.default
        let snippetsURL = supportDirectory.appendingPathComponent("snippets.json")
        let actionsURL = supportDirectory.appendingPathComponent("actions.plist")
        var report: [String: Any] = [
            "supportDirectory": supportDirectory.path,
            "usedSupportDirectoryOverride": debugHasSupportDirectoryOverride()
        ]

        func persistedFolders(at url: URL) -> [SnippetFolder] {
            guard let data = try? Data(contentsOf: url),
                  let folders = try? JSONDecoder().decode([SnippetFolder].self, from: data) else {
                return []
            }
            return folders
        }

        func persistedClipTexts() -> [String] {
            let reloadedStore = ClipStore()
            reloadedStore.load()
            return reloadedStore.orderedClips.map(\.text)
        }

        guard debugHasSupportDirectoryOverride() else {
            report["error"] = "debugSupportDirectoryPath override is required"
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
            return
        }

        defer {
            if let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
                try? data.write(to: reportURL, options: .atomic)
            }
            NSApp.terminate(nil)
        }

        do {
            try fileManager.createDirectory(at: supportDirectory, withIntermediateDirectories: true)
            try? fileManager.removeItem(at: snippetsURL)
            try? fileManager.removeItem(at: actionsURL)
            clipsStore.clear()
            clipsStore.removeSavedHistory()
        } catch {
            report["error"] = error.localizedDescription
            return
        }

        let snippetStore = SnippetFileStore.shared

        let baselineFolders = [
            SnippetFolder(
                title: "Termination Folder",
                isEnabled: true,
                snippets: [
                    Snippet(title: "Termination Snippet", content: "Original body", isEnabled: true)
                ]
            )
        ]
        snippetStore.folders = baselineFolders
        snippetStore.save()
        snippetStore.reload()

        try? baselineActionTreeData().write(to: actionsURL, options: .atomic)
        CMReloadActionPreferences()

        var draftSnippet = snippetStore.folders[0].snippets[0]
        draftSnippet.content = "Termination snippet draft"
        snippetStore.updateSnippet(
            folderID: snippetStore.folders[0].id,
            snippetID: draftSnippet.id,
            to: draftSnippet
        )

        CMAddReservedActionForTesting()

        clipsStore.clear()
        clipsStore.removeSavedHistory()
        let draftClip = ClipItem(text: "Termination clip")
        clipsStore.add(draftClip)

        let beforeShouldTerminateSnippetContent = persistedFolders(at: snippetsURL).first?.snippets.first?.content ?? ""
        let beforeShouldTerminateActionCount = topLevelActionNodeCount(at: actionsURL)
        let beforeShouldTerminateClipTexts = persistedClipTexts()
        let stagedActionCount = CMCurrentActionPreferencePaths().count
        let snippetHasUnsavedChangesBeforeTermination = snippetStore.hasUnsavedChanges
        let actionHasPendingChangesBeforeTermination = stagedActionCount != beforeShouldTerminateActionCount
        let clipHasUnsavedChangesBeforeTermination = clipsStore.debugHasUnsavedChanges

        UserDefaults.standard.set(true, forKey: CMPrefSaveHistoryOnQuitKey)

        terminationPersistenceHandled = false
        let terminateReply = applicationShouldTerminate(NSApp)

        let afterShouldTerminateSnippetContent = persistedFolders(at: snippetsURL).first?.snippets.first?.content ?? ""
        let afterShouldTerminateActionCount = topLevelActionNodeCount(at: actionsURL)
        let afterShouldTerminateClipTexts = persistedClipTexts()
        let handledAfterShouldTerminate = terminationPersistenceHandled

        applicationWillTerminate(Notification(name: NSApplication.willTerminateNotification, object: NSApp))

        let afterWillTerminateSnippetContent = persistedFolders(at: snippetsURL).first?.snippets.first?.content ?? ""
        let afterWillTerminateActionCount = topLevelActionNodeCount(at: actionsURL)
        let afterWillTerminateClipTexts = persistedClipTexts()

        report["beforeShouldTerminateSnippetContent"] = beforeShouldTerminateSnippetContent
        report["beforeShouldTerminateActionCount"] = beforeShouldTerminateActionCount
        report["beforeShouldTerminateClipTexts"] = beforeShouldTerminateClipTexts
        report["snippetHasUnsavedChangesBeforeTermination"] = snippetHasUnsavedChangesBeforeTermination
        report["actionHasPendingChangesBeforeTermination"] = actionHasPendingChangesBeforeTermination
        report["clipHasUnsavedChangesBeforeTermination"] = clipHasUnsavedChangesBeforeTermination
        switch terminateReply {
        case .terminateNow:
            report["terminateReply"] = "terminateNow"
        case .terminateCancel:
            report["terminateReply"] = "terminateCancel"
        case .terminateLater:
            report["terminateReply"] = "terminateLater"
        @unknown default:
            report["terminateReply"] = "unknown"
        }
        report["handledAfterShouldTerminate"] = handledAfterShouldTerminate
        report["afterShouldTerminateSnippetContent"] = afterShouldTerminateSnippetContent
        report["afterShouldTerminateActionCount"] = afterShouldTerminateActionCount
        report["afterShouldTerminateClipTexts"] = afterShouldTerminateClipTexts
        report["afterWillTerminateSnippetContent"] = afterWillTerminateSnippetContent
        report["afterWillTerminateActionCount"] = afterWillTerminateActionCount
        report["afterWillTerminateClipTexts"] = afterWillTerminateClipTexts
        report["historyPersistsDuringShouldTerminate"] =
            beforeShouldTerminateClipTexts.isEmpty
            && afterShouldTerminateClipTexts == ["Termination clip"]
        report["editorStoresPersistDuringWillTerminate"] =
            beforeShouldTerminateSnippetContent == "Original body"
            && afterShouldTerminateSnippetContent == "Original body"
            && afterWillTerminateSnippetContent == "Termination snippet draft"
            && beforeShouldTerminateActionCount == 1
            && afterShouldTerminateActionCount == 1
            && afterWillTerminateActionCount == 2
        report["terminationPathMatchesExpected"] =
            terminateReply == .terminateNow
            && handledAfterShouldTerminate
            && beforeShouldTerminateClipTexts.isEmpty
            && afterShouldTerminateClipTexts == ["Termination clip"]
            && afterWillTerminateClipTexts == ["Termination clip"]
            && beforeShouldTerminateSnippetContent == "Original body"
            && afterShouldTerminateSnippetContent == "Original body"
            && afterWillTerminateSnippetContent == "Termination snippet draft"
            && beforeShouldTerminateActionCount == 1
            && afterShouldTerminateActionCount == 1
            && afterWillTerminateActionCount == 2
        report["matchesExpected"] =
            (report["historyPersistsDuringShouldTerminate"] as? Bool == true)
            && (report["editorStoresPersistDuringWillTerminate"] as? Bool == true)
            && (report["terminationPathMatchesExpected"] as? Bool == true)
    }
#endif

    @discardableResult
    private func persistCapturedHistoryIfPreferred() -> Bool {
        guard UserDefaults.standard.bool(forKey: CMPrefSaveHistoryOnQuitKey) else {
            return true
        }
        return clipsStore.saveIfNeeded()
    }

    @discardableResult
    private func persistHistoryForTermination() -> Bool {
        if UserDefaults.standard.bool(forKey: CMPrefSaveHistoryOnQuitKey) {
            return clipsStore.save()
        }
        clipsStore.removeSavedHistory()
        return true
    }

    private static func registerDefaults() {
        UserDefaults.standard.register(defaults: [
            CMPrefLegacyHotKeysKey: defaultLegacyHotKeys(),
            CMPrefHotKeyEnabledKey: true,
