    private func clipMenuTitle(for clip: ClipItem, listNumber: Int) -> String {
        let textTitle = trimmedMenuTitle(for: clip.text)
        let titleText: String
        switch clip.primaryPasteboardType {
        case .tiff, .clipMenuPICT:
            titleText = "(Image)"
        case .pdf:
            titleText = "(PDF)"
        case .clipMenuFilenames where textTitle.isEmpty:
            titleText = "(Filenames)"
        default:
            titleText = textTitle
        }

        return numberedMenuTitle(titleText, listNumber: listNumber)
    }

    private func snippetMenuTitle(for text: String, listNumber: Int) -> String {
        numberedMenuTitle(trimmedSnippetMenuTitle(for: text), listNumber: listNumber)
    }

    private func trimmedSnippetMenuTitle(for text: String) -> String {
        let stripped = text.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmedMenuTitle(for: stripped)
    }

    private func trimmedMenuTitle(for text: String) -> String {
        let stripped = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let nsString = stripped as NSString
        let firstLine: NSString
        if nsString.length > 0 {
            var lineStart = 0
            var lineEnd = 0
            var contentsEnd = 0
            nsString.getLineStart(&lineStart, end: &lineEnd, contentsEnd: &contentsEnd, for: NSRange(location: 0, length: 0))
            firstLine = nsString.substring(to: lineEnd == nsString.length ? nsString.length : contentsEnd) as NSString
        } else {
            firstLine = ""
        }
        let defaults = UserDefaults.standard
        let storedLimit = defaults.integer(forKey: CMPrefMaxMenuItemTitleLengthKey)
        let normalizedStoredLimit = CMNormalizedLegacyMenuTitleLength(storedLimit)
        if normalizedStoredLimit != storedLimit {
            defaults.set(normalizedStoredLimit, forKey: CMPrefMaxMenuItemTitleLengthKey)
        }
        let limit = max(3, normalizedStoredLimit)
        if firstLine.length > limit {
            let end = max(0, limit - 3)
            return firstLine.substring(to: end) + "..."
        }
        return firstLine as String
    }

    private func numberedMenuTitle(_ title: String, listNumber: Int) -> String {
        guard UserDefaults.standard.bool(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey) else {
            return title
        }
        return "\(listNumber). \(title)"
    }

    private func folderRangeTitle(startOffset: Int, folderCount: Int, fullHistoryCount: Int, firstIndex: Int) -> String {
        let firstNumber = startOffset + firstIndex
        let legacyCount = firstIndex == 0 ? startOffset - 1 : startOffset
        let legacyLastNumber = min(fullHistoryCount, legacyCount + folderCount)
        let lastNumber = max(firstNumber, legacyLastNumber)
        return "\(firstNumber) - \(lastNumber)"
    }

    private func keyEquivalent(for index: Int) -> String {
        guard index >= 0 else { return "" }
        guard UserDefaults.standard.bool(forKey: CMPrefMenuItemsAreMarkedWithNumbersKey),
              index < 10 else {
            return ""
        }
        let startsFromZero = UserDefaults.standard.bool(forKey: CMPrefMenuItemsTitleStartWithZeroKey)
        let shortcut = startsFromZero ? index : index + 1
        return shortcut == 10 ? "0" : "\(shortcut)"
    }

    private func keyEquivalentModifierMask(for index: Int) -> NSEvent.ModifierFlags {
        keyEquivalent(for: index).isEmpty ? [] : [.command]
    }

    private func tooltip(for text: String) -> String {
        let defaults = UserDefaults.standard
        let storedMaxLength = defaults.integer(forKey: CMPrefMaxLengthOfToolTipKey)
        let maxLength = CMNormalizedLegacyMenuTooltipLength(storedMaxLength)
        if maxLength != storedMaxLength {
            defaults.set(maxLength, forKey: CMPrefMaxLengthOfToolTipKey)
        }
        let nsString = text as NSString
        return nsString.length > maxLength ? nsString.substring(to: maxLength) : text
    }

    private func menuListNumber(forOffset offset: Int, firstIndex: Int, maxCount: Int) -> Int {
        let value = firstIndex + offset
        if firstIndex == 1, maxCount == 10, value == 10 {
            return 0
        }
        return value
    }

    private func applyPreferredFont(to item: NSMenuItem) {
        guard UserDefaults.standard.bool(forKey: CMPrefChangeFontSizeKey) else { return }
        let defaults = UserDefaults.standard
        let size: CGFloat
        let storedFontSizingMode = defaults.integer(forKey: CMPrefHowToChangeFontSizeKey)
        let normalizedFontSizingMode = CMNormalizedMenuLegacyFontSizingMode(storedFontSizingMode)
        if normalizedFontSizingMode != storedFontSizingMode {
            defaults.set(normalizedFontSizingMode, forKey: CMPrefHowToChangeFontSizeKey)
        }
        switch normalizedFontSizingMode {
        case 0:
            if defaults.bool(forKey: CMPrefShowIconInTheMenuKey) {
                switch defaults.integer(forKey: CMPrefMenuIconSizeKey) {
                case 32:
                    size = 28
                case 48:
                    size = 42
                default:
                    size = 14
                }
            } else {
                size = 14
            }
        case 1:
            size = CGFloat(CMNormalizedMenuLegacyFontSize(defaults.integer(forKey: CMPrefSelectedFontSizeKey)))
        default:
            size = 14
        }
        item.attributedTitle = NSAttributedString(
            string: item.title,
            attributes: [.font: NSFont.systemFont(ofSize: size)]
        )
    }

    private func applyImageOrIcon(to item: NSMenuItem, for clip: ClipItem) {
        let defaults = UserDefaults.standard
        let image = clip.image
        let isImageClip = isImagePasteboardType(clip.primaryPasteboardType)
        if let image, isImageClip {
            if defaults.bool(forKey: CMPrefShowImageInTheMenuKey) {
                let storedThumbnailWidth = defaults.integer(forKey: CMPrefThumbnailWidthKey)
                let thumbnailWidth = CMNormalizedLegacyThumbnailDimension(storedThumbnailWidth)
                if thumbnailWidth != storedThumbnailWidth {
                    defaults.set(thumbnailWidth, forKey: CMPrefThumbnailWidthKey)
                }
                let storedThumbnailHeight = defaults.integer(forKey: CMPrefThumbnailHeightKey)
                let thumbnailHeight = CMNormalizedLegacyThumbnailDimension(storedThumbnailHeight)
                if thumbnailHeight != storedThumbnailHeight {
                    defaults.set(thumbnailHeight, forKey: CMPrefThumbnailHeightKey)
                }
                if let thumbnail = thumbnail(for: image, fitting: NSSize(width: thumbnailWidth, height: thumbnailHeight)) {
                    item.image = thumbnail
                    return
                }
            } else {
                return
            }
        }

        guard defaults.bool(forKey: CMPrefShowIconInTheMenuKey),
              let icon = fileTypeIcon(for: clip.primaryPasteboardType) else {
            return
        }
        item.image = sizedMenuIcon(icon)
    }

    private func isImagePasteboardType(_ type: NSPasteboard.PasteboardType?) -> Bool {
        switch type {
        case .tiff, .clipMenuPICT:
            return true
        default:
            return false
        }
    }

    private func thumbnail(for image: NSImage, fitting size: NSSize) -> NSImage? {
        guard let bitmapRep = image.representations.first(where: { $0 is NSBitmapImageRep }) as? NSBitmapImageRep else {
            return nil
        }

        let originalWidth = CGFloat(bitmapRep.pixelsWide)
        let originalHeight = CGFloat(bitmapRep.pixelsHigh)
        guard originalWidth > 0, originalHeight > 0 else { return nil }

        let scale = min(size.width / originalWidth, size.height / originalHeight, 1)
        let targetSize = NSSize(width: originalWidth * scale, height: originalHeight * scale)
        let thumbnail = NSImage(size: targetSize)
        thumbnail.lockFocus()
        NSGraphicsContext.current?.imageInterpolation = .high
        image.draw(in: NSRect(origin: .zero, size: targetSize), from: .zero, operation: .copy, fraction: 1)
        thumbnail.unlockFocus()
        return thumbnail
    }

    private func fileTypeIcon(for type: NSPasteboard.PasteboardType?) -> NSImage? {
        guard let type, let preference = menuIconPreference(for: type) else {
            return nil
        }

        let defaults = UserDefaults.standard
        let storedFileType = defaults.string(forKey: preference.fileTypeKey)
        let storedTag = defaults.object(forKey: preference.tagKey) as? Int ?? preference.defaultSelectionTag
        let normalizedTag = CMNormalizedTypeFileIconSelectionTag(storedTag)
        let fileType = CMNormalizedMenuIconFileTypeValue(
            storedFileType,
            defaultValue: preference.defaultFileType,
            selectionTag: normalizedTag
        )
        if normalizedTag != storedTag {
            defaults.set(normalizedTag, forKey: preference.tagKey)
        }
        if fileType != storedFileType {
            defaults.set(fileType, forKey: preference.fileTypeKey)
        }
        if normalizedTag == 1 {
            return NSWorkspace.shared.icon(forFileType: NSFileTypeForHFSTypeCode(legacyHFSTypeCode(from: fileType)))
        }
        return NSWorkspace.shared.icon(forFileType: fileType)
    }

    private func menuFolderIcon(open: Bool = false) -> NSImage {
        let hfsType = open ? kOpenFolderIcon : kGenericFolderIcon
        let icon = NSWorkspace.shared.icon(forFileType: NSFileTypeForHFSTypeCode(OSType(hfsType)))
        return sizedMenuIcon(icon)
    }

    private func menuSnippetIcon() -> NSImage {
        let icon = NSWorkspace.shared.icon(forFileType: NSFileTypeForHFSTypeCode(OSType(kClippingTextTypeIcon)))
        return sizedMenuIcon(icon)
    }

    private func menuActionIcon(for action: [String: String]) -> NSImage? {
        guard UserDefaults.standard.bool(forKey: CMPrefShowIconInTheMenuKey) else { return nil }
        switch action["type"] {
        case "builtin":
            let iconName = UserDefaults.standard.integer(forKey: CMPrefMenuIconSizeKey) <= 16 ? "ActionIcon" : "ActionIconLarge"
            if let icon = NSImage(named: iconName) {
                return sizedMenuIcon(icon)
            }
            return nil
        case "js":
            return sizedMenuIcon(NSWorkspace.shared.icon(forFileType: "js"))
        default:
            return nil
        }
    }

    private func sizedMenuIcon(_ icon: NSImage) -> NSImage {
        let size = CMNormalizedTypeLegacyMenuIconSize(
            UserDefaults.standard.integer(forKey: CMPrefMenuIconSizeKey)
        )
        let copy = icon.copy() as? NSImage ?? icon
        copy.size = NSSize(width: size, height: size)
        return copy
    }

    private struct MenuIconPreference {
        let tagKey: String
        let fileTypeKey: String
        let defaultSelectionTag: Int
        let defaultFileType: String
    }

    private func menuIconPreference(for type: NSPasteboard.PasteboardType) -> MenuIconPreference? {
        switch type {
        case .string:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForStringKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForStringKey,
                defaultSelectionTag: 1,
                defaultFileType: "TEXT"
            )
        case .rtf:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForRTFKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForRTFKey,
                defaultSelectionTag: 0,
                defaultFileType: "rtf"
            )
        case .rtfd:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForRTFDKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForRTFDKey,
                defaultSelectionTag: 0,
                defaultFileType: "rtfd"
            )
        case .pdf:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForPDFKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForPDFKey,
                defaultSelectionTag: 0,
                defaultFileType: "pdf"
            )
        case .clipMenuFilenames:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForFilenamesKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForFilenamesKey,
                defaultSelectionTag: 1,
                defaultFileType: "clpu"
            )
        case .clipMenuURL:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForURLKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForURLKey,
                defaultSelectionTag: 1,
                defaultFileType: "gurl"
            )
        case .tiff:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForTIFFKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForTIFFKey,
                defaultSelectionTag: 0,
                defaultFileType: "tiff"
            )
        case .clipMenuPICT:
            return MenuIconPreference(
                tagKey: CMPrefMenuIconOfFileTypeTagForPICTKey,
                fileTypeKey: CMPrefMenuIconOfFileTypeForPICTKey,
                defaultSelectionTag: 0,
                defaultFileType: "pict"
            )
        default:
            return nil
        }
    }

    private func legacyHFSTypeCode(from value: String) -> OSType {
        NSHFSTypeCodeFromFileType("'\(value)'")
    }

    private enum MenuPopupEventStyle {
        case hotKey
        case action
    }

    private func popUpMenuAtMouseLocation(_ menu: NSMenu, style: MenuPopupEventStyle = .hotKey) {
        let window = popupWindow ?? {
            let window = NSWindow(
                contentRect: .zero,
                styleMask: .borderless,
                backing: .buffered,
                defer: false
            )
            window.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
            popupWindow = window
            return window
        }()

        let currentEvent = NSApp.currentEvent
        let screenLocation: NSPoint
        switch style {
        case .hotKey:
            screenLocation = NSEvent.mouseLocation
        case .action:
            screenLocation = NSEvent.mouseLocation
        }
        window.setFrameOrigin(screenLocation)
        window.makeKeyAndOrderFront(nil)

#if DEBUG
        if debugCapturePopupMenus {
            debugCapturedPopupMenuSummaries.append(
                debugPopupMenuSummary(menu: menu, style: style, screenLocation: screenLocation)
            )
            window.orderOut(nil)
            return
        }
#endif

        let localPoint = window.convertPoint(fromScreen: screenLocation)
        guard let view = window.contentView,
              let event = popupEvent(
                style: style,
                currentEvent: currentEvent,
                location: localPoint,
                windowNumber: window.windowNumber
              ) else {
            window.orderOut(nil)
            return
        }

        beginTrackingPopupInteraction()
        NSMenu.popUpContextMenu(menu, with: event, for: view)
        endTrackingPopupInteraction()
        window.orderOut(nil)
    }

#if DEBUG
    private func debugPopupMenuSummary(menu: NSMenu, style: MenuPopupEventStyle, screenLocation: NSPoint) -> [String: Any] {
        let topLevelTitles = menu.items.map { $0.isSeparatorItem ? "<separator>" : $0.title }
        let submenuTitlesByParent = Dictionary(uniqueKeysWithValues: menu.items.compactMap { item -> (String, [String])? in
            guard let submenu = item.submenu else { return nil }
            return (item.title, submenu.items.map { $0.isSeparatorItem ? "<separator>" : $0.title })
        })

        return [
            "menuTitle": menu.title,
            "style": style == .hotKey ? "hotKey" : "action",
            "topLevelCount": menu.items.count,
            "topLevelTitles": topLevelTitles,
            "submenuTitlesByParent": submenuTitlesByParent,
            "screenLocation": [
                "x": screenLocation.x,
                "y": screenLocation.y
            ]
        ]
    }
#endif

    private func popupEvent(
        style: MenuPopupEventStyle,
        currentEvent: NSEvent?,
        location: NSPoint,
        windowNumber: Int
    ) -> NSEvent? {
        switch style {
        case .hotKey:
            return NSEvent.otherEvent(
                with: currentEvent?.type ?? .applicationDefined,
                location: location,
                modifierFlags: currentEvent?.modifierFlags ?? [],
                timestamp: currentEvent?.timestamp ?? 0,
                windowNumber: windowNumber,
                context: nil,
                subtype: 0,
                data1: 0,
                data2: 0
            )
        case .action:
            guard let currentEvent else {
                return NSEvent.otherEvent(
                    with: .applicationDefined,
                    location: location,
                    modifierFlags: [],
                    timestamp: 0,
                    windowNumber: windowNumber,
                    context: nil,
                    subtype: 0,
                    data1: 0,
                    data2: 0
                )
            }

            switch currentEvent.type {
            case .leftMouseDown, .leftMouseUp, .rightMouseDown, .rightMouseUp, .keyDown:
                return NSEvent.otherEvent(
                    with: .applicationDefined,
                    location: location,
                    modifierFlags: [],
                    timestamp: 0,
                    windowNumber: windowNumber,
                    context: nil,
                    subtype: 0,
                    data1: 0,
                    data2: 0
                )
            default:
                return NSEvent.otherEvent(
                    with: currentEvent.type,
                    location: location,
                    modifierFlags: currentEvent.modifierFlags,
                    timestamp: currentEvent.timestamp,
                    windowNumber: windowNumber,
                    context: nil,
                    subtype: 0,
                    data1: 0,
                    data2: 0
                )
            }
        }
    }

    @objc(selectMenuItem:) fileprivate func selectClip(_ sender: NSMenuItem) {
        guard let id = sender.representedObject as? String,
              let clip = clipsStore.clip(with: id) else { return }
        debugPasteFlow("selectClip title=\(sender.title) targetText=\(clip.text)")
        if applyActionIfRequested(to: .clip(clip.id), sender: sender) {
            return
        }
        clip.write(to: pasteboard)
        debugPasteFlow("selectClip wroteToPasteboard")

        let defaults = UserDefaults.standard
        let shouldReorder = CMNormalizedLegacyReorderClipsAfterPastingValue(
            defaults.object(forKey: CMPrefReorderClipsAfterPasting)
        )
        if shouldReorder != defaults.bool(forKey: CMPrefReorderClipsAfterPasting)
            || !(defaults.object(forKey: CMPrefReorderClipsAfterPasting) is Bool) {
            defaults.set(shouldReorder, forKey: CMPrefReorderClipsAfterPasting)
        }

        if shouldReorder {
            clipsStore.promote(clip.id)
            rebuildMenu()
        }

        let shouldSynthesizePaste = defaults.bool(forKey: CMPrefInputPasteCommandKey)
        debugPasteFlow("selectClip shouldSynthesizePaste=\(shouldSynthesizePaste)")
        if shouldSynthesizePaste {
            synthesizePasteIfEnabled()
        }
    }

    @objc(selectSnippetMenuItem:) fileprivate func selectSnippet(_ sender: NSMenuItem) {
        guard let snippet = sender.representedObject as? SnippetActionReference else { return }
        let snippetContent = snippet.content.replacingOccurrences(of: "\n", with: "\\n")
        debugPasteFlow("selectSnippet title=\(sender.title) content=\(snippetContent)")
        if applyActionIfRequested(to: .snippet(snippet), sender: sender) {
            return
        }
        pasteboard.clearContents()
        pasteboard.setString(snippet.content, forType: .string)
        debugPasteFlow("selectSnippet wroteToPasteboard")
        let shouldSynthesizePaste = UserDefaults.standard.bool(forKey: CMPrefInputPasteCommandKey)
        debugPasteFlow("selectSnippet shouldSynthesizePaste=\(shouldSynthesizePaste)")
        if shouldSynthesizePaste {
            synthesizePasteIfEnabled()
        }
    }

    private func applyActionIfRequested(to target: ActionTarget, sender: NSMenuItem) -> Bool {
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: CMPrefEnableActionKey) else {
            debugPasteFlow("applyActionIfRequested disabled")
            return false
        }

        let event = NSApp.currentEvent
        if event == nil && lastPopupInteractionType == nil {
            debugPasteFlow("applyActionIfRequested noPopupEventContext")
            return false
        }
        let modifierFlags = currentModifierFlags(for: event)
        let isRightClick = currentMenuInteractionIsRightClick(event: event)
        let eventDescription = event.map { "\($0.type.rawValue)" } ?? "nil"
        let lastTypeDescription = lastPopupInteractionType.map { "\($0.rawValue)" } ?? "nil"
        let behavior: Any?
        if isRightClick || modifierFlags.contains(.control) {
            behavior = defaults.object(forKey: CMPrefContorlClickBehaviorKey)
        } else if modifierFlags.contains(.shift) {
            behavior = defaults.object(forKey: CMPrefShiftClickBehaviorKey)
        } else if modifierFlags.contains(.option) {
            behavior = defaults.object(forKey: CMPrefOptionClickBehaviorKey)
        } else if modifierFlags.contains(.command) {
            behavior = defaults.object(forKey: CMPrefCommandClickBehaviorKey)
        } else {
            debugPasteFlow("applyActionIfRequested noModifiers event=\(eventDescription) lastType=\(lastTypeDescription)")
            return false
        }

        let behaviorDescription: String
        if let behaviorString = behavior as? String {
            behaviorDescription = behaviorString
        } else if let action = actionDictionary(from: behavior) {
            behaviorDescription = action["name"] ?? action["type"] ?? "action"
        } else {
            behaviorDescription = "nil"
        }
        debugPasteFlow("applyActionIfRequested modifiers=\(modifierFlags.rawValue) rightClick=\(isRightClick) event=\(eventDescription) lastType=\(lastTypeDescription) behavior=\(behaviorDescription)")

        let invoked = invokeModifiedClickBehavior(behavior, popupTarget: target, sender: sender)
        debugPasteFlow("applyActionIfRequested invoked=\(invoked)")
        return invoked
    }

    private func currentModifierFlags(for event: NSEvent?) -> NSEvent.ModifierFlags {
        let eventFlags = event?.modifierFlags.normalizedShortcutFlags ?? []
        let trackedFlags = eventFlags.union(lastPopupInteractionFlags)
        if lastPopupInteractionType != nil || !trackedFlags.isEmpty {
            return trackedFlags
        }
        let globalFlags = NSEvent.modifierFlags.normalizedShortcutFlags
        return eventFlags.union(globalFlags)
    }

    private func currentMenuInteractionIsRightClick(event: NSEvent?) -> Bool {
        if event?.type == .rightMouseDown || event?.type == .rightMouseUp {
            return true
        }
        return lastPopupInteractionType == .rightMouseDown || lastPopupInteractionType == .rightMouseUp
    }

    private func beginTrackingPopupInteraction() {
        lastPopupInteractionFlags = []
        lastPopupInteractionType = nil
        popupInteractionMonitor = NSEvent.addLocalMonitorForEvents(matching: [.leftMouseDown, .leftMouseUp, .rightMouseDown, .rightMouseUp, .keyDown, .flagsChanged]) { [weak self] event in
            self?.lastPopupInteractionFlags = event.modifierFlags.normalizedShortcutFlags
            self?.lastPopupInteractionType = event.type
            return event
        }
        installPopupInteractionEventTap()
    }

    private func endTrackingPopupInteraction() {
        if let popupInteractionMonitor {
            NSEvent.removeMonitor(popupInteractionMonitor)
            self.popupInteractionMonitor = nil
        }
        if let popupInteractionRunLoopSource {
            CFRunLoopRemoveSource(CFRunLoopGetMain(), popupInteractionRunLoopSource, .commonModes)
            self.popupInteractionRunLoopSource = nil
        }
        if let popupInteractionEventTap {
            CGEvent.tapEnable(tap: popupInteractionEventTap, enable: false)
            self.popupInteractionEventTap = nil
        }
    }

    private func installPopupInteractionEventTap() {
        let events = [
            CGEventType.leftMouseDown,
            .leftMouseUp,
            .rightMouseDown,
            .rightMouseUp,
            .keyDown,
            .flagsChanged
        ]
        let mask = events.reduce(CGEventMask(0)) { partialResult, eventType in
            partialResult | (1 << eventType.rawValue)
        }

        let callback: CGEventTapCallBack = { _, type, event, userInfo in
            guard let userInfo else {
                return Unmanaged.passUnretained(event)
            }
            let controller = Unmanaged<AppController>.fromOpaque(userInfo).takeUnretainedValue()
            controller.recordPopupInteraction(type: type, event: event)
            return Unmanaged.passUnretained(event)
        }

        guard let eventTap = CGEvent.tapCreate(
            tap: .cgSessionEventTap,
            place: .headInsertEventTap,
            options: .listenOnly,
            eventsOfInterest: mask,
            callback: callback,
            userInfo: Unmanaged.passUnretained(self).toOpaque()
        ) else {
            return
        }

        let runLoopSource = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, eventTap, 0)
        CFRunLoopAddSource(CFRunLoopGetMain(), runLoopSource, .commonModes)
        CGEvent.tapEnable(tap: eventTap, enable: true)
        popupInteractionEventTap = eventTap
        popupInteractionRunLoopSource = runLoopSource
    }

    private func recordPopupInteraction(type: CGEventType, event: CGEvent) {
        lastPopupInteractionFlags = modifierFlags(for: event.flags)
        lastPopupInteractionType = menuInteractionEventType(for: type)
    }

    private func modifierFlags(for flags: CGEventFlags) -> NSEvent.ModifierFlags {
        var result: NSEvent.ModifierFlags = []
        if flags.contains(.maskShift) {
            result.insert(.shift)
        }
        if flags.contains(.maskControl) {
            result.insert(.control)
        }
        if flags.contains(.maskAlternate) {
            result.insert(.option)
        }
        if flags.contains(.maskCommand) {
            result.insert(.command)
        }
        return result
    }

    private func menuInteractionEventType(for type: CGEventType) -> NSEvent.EventType? {
        switch type {
        case .leftMouseDown:
            return .leftMouseDown
        case .leftMouseUp:
            return .leftMouseUp
        case .rightMouseDown:
            return .rightMouseDown
        case .rightMouseUp:
            return .rightMouseUp
        case .keyDown:
            return .keyDown
        case .flagsChanged:
            return .flagsChanged
        default:
            return nil
        }
    }

    private func invokeModifiedClickBehavior(_ behavior: Any?, popupTarget: ActionTarget, sender: NSMenuItem) -> Bool {
        if let behavior = behavior as? String {
            guard !behavior.isEmpty else { return false }
            if behavior == "popUpActionMenu" {
                actionTarget = popupTarget
                defer { actionTarget = nil }

                let nodes = loadRuntimeActionNodes()
                if UserDefaults.standard.bool(forKey: CMPrefInvokeActionImmediatelyKey),
                   nodes.count == 1 {
                    if let action = nodes.first?.action {
                        invokeAction(action, target: popupTarget)
                    }
                    return true
                }

                let menu = makeActionMenu()
                if menu.numberOfItems > 0 {
                    popUpMenuAtMouseLocation(menu, style: .action)
                }
                return true
            }
            return false
        }

        if let action = actionDictionary(from: behavior) {
            let directTarget = legacyDirectActionTarget(for: sender)
            actionTarget = directTarget
            defer { actionTarget = nil }
            if let directTarget {
                invokeAction(action, target: directTarget)
            }
            return true
        }

        return false
    }

    private func legacyDirectActionTarget(for sender: NSMenuItem) -> ActionTarget? {
        let tag = sender.tag
        if tag < 0,
           let snippet = sender.representedObject as? SnippetActionReference {
            return .snippet(snippet)
        }
        let clips = clipsStore.orderedClips
        guard tag >= 0, tag < clips.count else { return nil }
        return .clip(clips[tag].id)
    }

    private func makeActionMenu() -> NSMenu {
        let menu = NSMenu(title: "ActionMenu")
        menu.delegate = self
        for node in loadRuntimeActionNodes() {
            if let item = makeActionMenuItem(from: node) {
                menu.addItem(item)
            }
        }
        return menu
    }

    private func makeActionMenuItem(from node: RuntimeActionNode) -> NSMenuItem? {
        if let action = node.action {
            guard isActionPerformable(action) else { return nil }
            let item = NSMenuItem(title: node.nodeTitle, action: #selector(selectAction(_:)), keyEquivalent: "")
            item.target = statusMenuCommandRouter
            item.representedObject = action
            if UserDefaults.standard.bool(forKey: CMPrefShowToolTipOnMenuItemKey) {
                item.toolTip = tooltipForAction(action)
            }
            item.image = menuActionIcon(for: action)
            return item
        }

        let submenu = NSMenu(title: node.nodeTitle)
        for child in node.children {
            if let item = makeActionMenuItem(from: child) {
                submenu.addItem(item)
            }
        }
        guard submenu.numberOfItems > 0 else { return nil }

        let item = NSMenuItem(title: node.nodeTitle, action: nil, keyEquivalent: "")
        item.submenu = submenu
        if UserDefaults.standard.bool(forKey: CMPrefShowIconInTheMenuKey) {
            item.image = menuFolderIcon()
        }
        return item
    }

    private func loadRuntimeActionNodes() -> [RuntimeActionNode] {
        if let data = CMCommittedActionNodesData(),
           let nodes = try? PropertyListDecoder().decode([RuntimeActionNode].self, from: data) {
            return isEarlierGeneratedRuntimeDefault(nodes) ? defaultRuntimeActionNodes() : nodes
        }

        let directory = clipMenuApplicationSupportDirectory()
        let url = directory.appendingPathComponent("actions.plist")
        if FileManager.default.fileExists(atPath: url.path) {
            guard let data = try? Data(contentsOf: url) else {
                return defaultRuntimeActionNodes()
            }
            guard let nodes = try? PropertyListDecoder().decode([RuntimeActionNode].self, from: data) else {
                return []
            }
            return isEarlierGeneratedRuntimeDefault(nodes) ? defaultRuntimeActionNodes() : nodes
        }
        let legacyURL = directory.appendingPathComponent("actionMenu.data")
        if let nodes = loadLegacyRuntimeActionNodes(from: legacyURL) {
            return nodes
        }
        return defaultRuntimeActionNodes()
    }

    private func loadLegacyRuntimeActionNodes(from url: URL) -> [RuntimeActionNode]? {
        guard let data = try? Data(contentsOf: url) else { return nil }

        do {
            let unarchiver = try NSKeyedUnarchiver(forReadingFrom: data)
            unarchiver.requiresSecureCoding = false
            unarchiver.setClass(LegacyRuntimeArchivedActionNode.self, forClassName: "ActionNode")
            unarchiver.setClass(LegacyRuntimeArchivedActionNode.self, forClassName: "BaseNode")
            unarchiver.setClass(LegacyRuntimeArchivedActionNode.self, forClassName: "CMLegacyArchivedActionNode")
            unarchiver.setClass(LegacyRuntimeArchivedActionNode.self, forClassName: "CMLegacyRuntimeArchivedActionNode")
            defer { unarchiver.finishDecoding() }

            let decodedRoot = unarchiver.decodeObject(forKey: NSKeyedArchiveRootObjectKey)
            let legacyNodes: [LegacyRuntimeArchivedActionNode]
            if let nodes = decodedRoot as? [LegacyRuntimeArchivedActionNode] {
                legacyNodes = nodes
            } else if let nodes = decodedRoot as? NSArray {
                legacyNodes = nodes.compactMap { $0 as? LegacyRuntimeArchivedActionNode }
            } else {
                return nil
            }
            return legacyNodes.map { $0.runtimeActionNode() }
        } catch {
            NSLog("ClipMenu failed to load legacy actionMenu.data: \(error.localizedDescription)")
            return nil
        }
    }

    private func defaultRuntimeActionNodes() -> [RuntimeActionNode] {
        [
            runtimeBuiltinAction(title: NSLocalizedString("Paste as Plain Text", comment: ""), name: "pasteAsPlainText:"),
            RuntimeActionNode(
                nodeTitle: NSLocalizedString("Case", comment: ""),
                children: [
                    "Case/Capitalize.js",
                    "Case/lowercase.js",
                    "Case/Title Case.js",
                    "Case/UPPERCASE.js"
                ].compactMap { runtimeBundledScriptNode(relativePath: $0, includeExtensionInTitle: true) }
            ),
            RuntimeActionNode(
                nodeTitle: NSLocalizedString("Trim", comment: ""),
                children: [
                    "Trim/LTrim.js",
                    "Trim/RTrim.js",
                    "Trim/Trim.js"
                ].compactMap { runtimeBundledScriptNode(relativePath: $0, includeExtensionInTitle: true) }
            ),
            runtimeBuiltinAction(title: NSLocalizedString("Remove", comment: ""), name: "remove:")
        ]
    }

    private func isEarlierGeneratedRuntimeDefault(_ nodes: [RuntimeActionNode]) -> Bool {
        var builtinNames: [String] = []
        var scriptPaths: [String] = []
        for node in nodes {
            collectRuntimeActionSignatures(from: node, builtinNames: &builtinNames, scriptPaths: &scriptPaths)
        }

        if builtinNames == ["pasteAsPlainText:", "remove:"],
           Set(scriptPaths) == Set([
                "Case/Capitalize.js",
                "Case/Title Case.js",
                "Case/UPPERCASE.js",
                "Case/lowercase.js",
                "Trim/LTrim.js",
                "Trim/RTrim.js",
                "Trim/Trim.js"
           ]) {
            return true
        }

        return builtinNames == ["pasteAsPlainText:", "pasteAsFilePath:", "pasteAsHFSFilePath:", "remove:"]
            && Set(scriptPaths) == Set(bundledRuntimeScriptRelativePaths())
    }

    private func collectRuntimeActionSignatures(
        from node: RuntimeActionNode,
        builtinNames: inout [String],
        scriptPaths: inout [String]
    ) {
        if let action = node.action {
            switch action["type"] {
            case "builtin":
                if let name = action["name"] {
                    builtinNames.append(name)
                }
            case "js":
                if let path = action["path"],
                   let relativePath = bundledScriptRelativePath(from: path) {
                    scriptPaths.append(relativePath)
                }
            default:
                break
            }
            return
        }

        for child in node.children {
            collectRuntimeActionSignatures(from: child, builtinNames: &builtinNames, scriptPaths: &scriptPaths)
        }
    }

    private func bundledScriptRelativePath(from path: String) -> String? {
        if let range = path.range(of: "/script/action/") {
            return String(path[range.upperBound...])
        }

        let scriptActionPrefix = "script/action/"
        if path.hasPrefix(scriptActionPrefix) {
            return String(path.dropFirst(scriptActionPrefix.count))
        }

        guard !path.hasPrefix("/"), path.hasSuffix(".js") else { return nil }
        return path
    }

    private func runtimeBuiltinAction(title: String, name: String) -> RuntimeActionNode {
        RuntimeActionNode(nodeTitle: title, action: ["type": "builtin", "name": name])
    }

    private func runtimeBundledScriptNode(relativePath: String, includeExtensionInTitle: Bool = false) -> RuntimeActionNode? {
        let candidates = [
            Bundle.main.resourceURL?
                .appendingPathComponent("script/action", isDirectory: true)
                .appendingPathComponent(relativePath),
            URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
                .appendingPathComponent("resource/script/action", isDirectory: true)
                .appendingPathComponent(relativePath)
        ].compactMap { $0 }
        guard let url = candidates.first(where: { FileManager.default.fileExists(atPath: $0.path) }) else {
            return nil
        }
        let title = includeExtensionInTitle ? url.lastPathComponent : url.deletingPathExtension().lastPathComponent
        return RuntimeActionNode(
            nodeTitle: NSLocalizedString(title, comment: ""),
            action: ["type": "js", "path": url.path]
        )
    }

    private func bundledRuntimeActionNodes() -> [RuntimeActionNode] {
        let candidates = [
            Bundle.main.resourceURL?
                .appendingPathComponent("script/action", isDirectory: true),
            URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
                .appendingPathComponent("resource/script/action", isDirectory: true)
        ].compactMap { $0 }

        guard let root = candidates.first(where: { FileManager.default.fileExists(atPath: $0.path) }) else {
            return []
        }
        return runtimeScriptNodes(walking: root)
    }

    private func bundledRuntimeScriptRelativePaths() -> [String] {
        var scriptPaths: [String] = []
        var builtinNames: [String] = []
        for node in bundledRuntimeActionNodes() {
            collectRuntimeActionSignatures(from: node, builtinNames: &builtinNames, scriptPaths: &scriptPaths)
        }
        return scriptPaths
    }

    private func runtimeScriptNodes(walking directoryURL: URL) -> [RuntimeActionNode] {
        guard let contents = try? FileManager.default.contentsOfDirectory(
            at: directoryURL,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles]
        ) else {
            return []
        }

        return contents.compactMap { url -> RuntimeActionNode? in
            let resourceValues = try? url.resourceValues(forKeys: [.isDirectoryKey])
            if resourceValues?.isDirectory == true {
                return RuntimeActionNode(
                    nodeTitle: NSLocalizedString(url.deletingPathExtension().lastPathComponent, comment: ""),
                    children: runtimeScriptNodes(walking: url)
                )
            }

            guard url.pathExtension == "js" else { return nil }
            return RuntimeActionNode(
                nodeTitle: NSLocalizedString(url.deletingPathExtension().lastPathComponent, comment: ""),
                action: ["type": "js", "path": url.path]
            )
        }
    }

    private func isActionPerformable(_ action: [String: String]) -> Bool {
        guard let type = action["type"] else { return false }
        switch type {
        case "builtin":
            let name = action["name"] ?? ""
            if name == "pasteAsPlainText:" {
                return targetContainsPasteboardType(.string)
            }
            if ["removeAction", "removeAction:", "remove:"].contains(name) {
                return true
            }
            if ["pasteAsFilePath:", "pasteAsHFSFilePath:"].contains(name) {
                return targetContainsPasteboardType(.clipMenuFilenames)
            }
            return false
        case "js":
            return targetContainsPasteboardType(.string)
        default:
            return false
        }
    }

    private func targetContainsPasteboardType(_ pasteboardType: NSPasteboard.PasteboardType) -> Bool {
        switch actionTarget {
        case .clip(let id):
            return clipsStore.clip(with: id.uuidString)?.types.contains(pasteboardType.rawValue) == true
        case .snippet:
            return pasteboardType == .string
        case nil:
            return false
        }
    }

    private func tooltipForAction(_ action: [String: String]) -> String? {
        switch action["name"] {
        case "pasteAsPlainText:":
            return NSLocalizedString("Paste the clip as Plain Text", comment: "")
        case "pasteAsFilePath:":
            return NSLocalizedString("Paste the clip as POSIX File Path", comment: "")
        case "pasteAsHFSFilePath:":
            return NSLocalizedString("Paste the clip as HFS File Path", comment: "")
        case "removeAction", "removeAction:", "remove:":
            return NSLocalizedString("Remove the clip from the clipboard history", comment: "")
        default:
            return nil
        }
    }

    @objc(selectActionMenuItem:) fileprivate func selectAction(_ sender: NSMenuItem) {
        guard let action = sender.representedObject as? [String: String],
              let target = actionTarget else { return }
        invokeAction(action, target: target)
    }

    private func invokeAction(_ action: [String: String], target: ActionTarget) {
        guard let type = action["type"] else { return }
        switch type {
        case "builtin":
            invokeBuiltinAction(action, target: target)
        case "js":
            invokeJavaScriptAction(action, target: target)
        default:
            return
        }
    }

    private func invokeBuiltinAction(_ action: [String: String], target: ActionTarget) {
        switch action["name"] {
        case "pasteAsPlainText:":
            guard let text = text(for: target) else { return }
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
            synthesizePasteForAction()
        case "removeAction", "removeAction:", "remove:":
            if case let .clip(id) = target {
                clipsStore.remove(id)
                rebuildMenu()
            } else if case let .snippet(snippet) = target {
                SnippetFileStore.shared.removeSnippet(folderID: snippet.folderID, snippetID: snippet.snippetID)
                rebuildMenu()
            }
        case "pasteAsFilePath:":
            guard let text = clip(for: target)?.filePathsText else { return }
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
            synthesizePasteForAction()
        case "pasteAsHFSFilePath:":
            guard let text = clip(for: target)?.hfsFilePathsText else { return }
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
            synthesizePasteForAction()
        default:
            NSSound.beep()
        }
    }

    private func invokeJavaScriptAction(_ action: [String: String], target: ActionTarget) {
        guard let scriptPath = action["path"],
              let sourceClip = scriptClip(for: target),
              let result = runJavaScriptAction(at: scriptPath, clip: sourceClip) else {
            return
        }
        result.write(to: pasteboard)
        synthesizePasteForAction()
    }

    private func text(for target: ActionTarget?) -> String? {
        guard let target else { return nil }
        switch target {
        case .clip(let id):
            return clipsStore.clips.first { $0.id == id }?.text
        case .snippet(let snippet):
            return snippet.content
        }
    }

    private func clip(for target: ActionTarget?) -> ClipItem? {
        guard let target, case let .clip(id) = target else { return nil }
        return clipsStore.clips.first { $0.id == id }
    }

    private func scriptClip(for target: ActionTarget) -> ClipItem? {
        switch target {
        case .clip(let id):
            return clipsStore.clips.first { $0.id == id }
        case .snippet(let snippet):
            return ClipItem(text: snippet.content)
        }
    }

    private func runJavaScriptAction(at scriptPath: String, clip: ClipItem) -> ClipItem? {
        guard !clip.text.isEmpty else { return nil }

        guard let scriptURL = resolvedActionScriptURL(for: scriptPath) else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("The script you selected does not exist", comment: ""),
                message: ""
            )
            return nil
        }

        guard let script = try? String(contentsOf: scriptURL, encoding: .utf8) else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Unable to load script", comment: ""),
                message: NSLocalizedString("Your script file does not exist.", comment: "")
            )
            return nil
        }

        guard let context = JSContext() else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Error", comment: ""),
                message: NSLocalizedString("Failed to evaluate script", comment: "")
            )
            return nil
        }

        let scriptableClip = ScriptableActionClip(clip: clip)
        context.setObject(scriptableClip.stringValue, forKeyedSubscript: "clipText" as NSString)
        guard let clipObject = JSValue(newObjectIn: context) else { return nil }
        let getStringValue: @convention(block) () -> String = {
            scriptableClip.stringValue
        }
        let setStringValue: @convention(block) (String) -> Void = { value in
            scriptableClip.setStringValue(value)
        }
        let setStringAttributes: @convention(block) (JSValue) -> Void = { attributes in
            scriptableClip.setStringAttributes(attributes)
        }
        let addStringAttributes: @convention(block) (JSValue) -> Void = { attributes in
            scriptableClip.addStringAttributes(attributes)
        }
        clipObject.setObject(getStringValue, forKeyedSubscript: "__getStringValue" as NSString)
        clipObject.setObject(setStringValue, forKeyedSubscript: "__setStringValue" as NSString)
        clipObject.setObject(setStringAttributes, forKeyedSubscript: "setStringAttributes" as NSString)
        clipObject.setObject(addStringAttributes, forKeyedSubscript: "addStringAttributes" as NSString)
        context.setObject(clipObject, forKeyedSubscript: "clip" as NSString)
        let require: @convention(block) (String?) -> Bool = { filename in
            guard let filename, !filename.isEmpty else { return false }
            let scriptName = (filename as NSString).pathExtension == "js"
                ? filename
                : (filename as NSString).appendingPathExtension("js") ?? "\(filename).js"
            let candidates = [
                self.userActionLibrariesURL()
                    .appendingPathComponent(scriptName),
                Bundle.main.resourceURL?
                    .appendingPathComponent("script/lib", isDirectory: true)
                    .appendingPathComponent(scriptName)
            ].compactMap { $0 }

            for url in candidates where FileManager.default.fileExists(atPath: url.path) {
                if let library = try? String(contentsOf: url, encoding: .utf8) {
                    context.evaluateScript(library)
                    return true
                }
            }
            return false
        }
        let activate: @convention(block) () -> Void = {
            self.keepCurrentFrontmostApplicationAndActivateForJavaScript()
        }
        let prompt: @convention(block) (String?, String?) -> String? = { message, defaultValue in
            self.runOnMainThread {
                self.promptForJavaScript(message: message, defaultValue: defaultValue)
            }
        }
        let alert: @convention(block) (String?) -> Void = { message in
            self.runOnMainThread {
                let dialog = self.makeJavaScriptBridgeAlert(message: message)
                _ = self.runJavaScriptModal(dialog)
            }
        }
        let confirm: @convention(block) (String?) -> Bool = { message in
            self.runOnMainThread {
                let dialog = self.makeJavaScriptBridgeConfirm(message: message)
                let result = self.runJavaScriptModal(dialog)
                return self.javaScriptConfirmationAccepted(response: result)
            }
        }
        let bridge: [String: Any] = [
            "require": require,
            "activate": activate
        ]
        context.setObject(bridge, forKeyedSubscript: "ClipMenu" as NSString)
        context.setObject(prompt, forKeyedSubscript: "prompt" as NSString)
        context.setObject(alert, forKeyedSubscript: "alert" as NSString)
        context.setObject(confirm, forKeyedSubscript: "confirm" as NSString)

        var exceptionMessage: String?
        context.exceptionHandler = { _, exception in
            exceptionMessage = exception?.toString()
        }
        defer {
            restorePreviousFrontmostApplicationForJavaScript()
        }

        context.evaluateScript("""
        var exports = {};
        var module = { exports: exports };
        Object.defineProperty(clip, 'stringValue', {
            get: clip.__getStringValue,
            set: clip.__setStringValue
        });
        delete clip.__getStringValue;
        delete clip.__setStringValue;
        """)
        guard exceptionMessage == nil else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Error", comment: ""),
                message: NSLocalizedString("Failed to evaluate script", comment: "")
            )
            return nil
        }

        context.setObject("", forKeyedSubscript: "__scriptException" as NSString)
        context.evaluateScript("""
        function __clipMenuWrapper() {
            try {
                \(script)
            } catch (e) {
                __scriptException = e.toString();
                return;
            }
        }
        """)
        guard exceptionMessage == nil else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Error", comment: ""),
                message: NSLocalizedString("Failed to evaluate script", comment: "")
            )
            return nil
        }

        exceptionMessage = nil
        context.evaluateScript("var __clipMenuResult = __clipMenuWrapper();")
        guard exceptionMessage == nil else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Exception Raised", comment: ""),
                message: exceptionMessage ?? ""
            )
            return nil
        }
        if let scriptException = context.objectForKeyedSubscript("__scriptException")?.toString(),
           !scriptException.isEmpty {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Exception Raised", comment: ""),
                message: scriptException
            )
            return nil
        }

        guard let result = context.objectForKeyedSubscript("__clipMenuResult") else {
            showJavaScriptActionAlert(
                title: NSLocalizedString("Script Error", comment: ""),
                message: NSLocalizedString("Failed to evaluate script", comment: "")
            )
            return nil
        }

        guard !result.isUndefined else { return nil }

        if context.evaluateScript("__clipMenuResult === clip")?.toBool() == true {
            return scriptableClip.clip
        }

        return ClipItem(text: result.toString())
    }

    private func showJavaScriptActionAlert(title: String, message: String) {
#if DEBUG
        debugLastJavaScriptAlertTitle = title
        debugLastJavaScriptAlertMessage = message
        if UserDefaults.standard.bool(forKey: "debugJavaScriptAlertsAreLogged") {
            debugPasteFlow("showJavaScriptActionAlert title=\(title) message=\(message)")
            return
        }
#endif
        runOnMainThread {
            let alert = self.makeJavaScriptActionFailureAlert(title: title, message: message)
            _ = self.runJavaScriptModal(alert)
        }
    }

    private func javaScriptDialogMessageText(_ message: String?, fallback: String) -> String {
        message?.isEmpty == false ? message! : fallback
    }

