    private func makeJavaScriptDialogAccessory(
        title: String,
        detail: String,
        symbolName: String,
        tintColor: NSColor
    ) -> NSView {
        let width: CGFloat = 420
        let container = NSVisualEffectView(frame: NSRect(x: 0, y: 0, width: width, height: 72))
        container.material = .menu
        container.state = .active
        container.wantsLayer = true
        container.layer?.cornerRadius = 12
        container.layer?.masksToBounds = true

        let iconBackground = NSVisualEffectView(frame: NSRect(x: 16, y: 16, width: 40, height: 40))
        iconBackground.material = .sidebar
        iconBackground.state = .active
        iconBackground.wantsLayer = true
        iconBackground.layer?.cornerRadius = 10
        iconBackground.layer?.masksToBounds = true
        container.addSubview(iconBackground)

        let iconConfiguration = NSImage.SymbolConfiguration(pointSize: 17, weight: .semibold)
        let iconView = NSImageView(frame: NSRect(x: 9, y: 9, width: 22, height: 22))
        iconView.image = NSImage(
            systemSymbolName: symbolName,
            accessibilityDescription: title
        )?.withSymbolConfiguration(iconConfiguration)
        iconView.contentTintColor = tintColor
        iconView.imageScaling = .scaleProportionallyUpOrDown
        iconBackground.addSubview(iconView)

        let textWidth = width - 90

        let titleLabel = NSTextField(labelWithString: title)
        titleLabel.font = .systemFont(ofSize: 13, weight: .semibold)
        titleLabel.frame = NSRect(x: 70, y: 38, width: textWidth, height: 18)
        container.addSubview(titleLabel)

        let detailLabel = NSTextField(labelWithString: detail)
        detailLabel.font = .systemFont(ofSize: 12)
        detailLabel.textColor = .secondaryLabelColor
        detailLabel.lineBreakMode = .byTruncatingTail
        detailLabel.frame = NSRect(x: 70, y: 18, width: textWidth, height: 17)
        container.addSubview(detailLabel)

        return container
    }

    private func makeJavaScriptPromptAccessory(inputField: NSTextField) -> NSView {
        let width: CGFloat = 420
        let container = NSView(frame: NSRect(x: 0, y: 0, width: width, height: 118))
        let summary = makeJavaScriptDialogAccessory(
            title: localizedJavaScriptBridgePromptAccessoryTitle(),
            detail: localizedJavaScriptBridgePromptAccessoryDetail(),
            symbolName: "character.cursor.ibeam",
            tintColor: .systemBlue
        )
        summary.frame.origin = NSPoint(x: 0, y: 46)
        container.addSubview(summary)

        inputField.frame = NSRect(x: 0, y: 0, width: width, height: 28)
        container.addSubview(inputField)

        return container
    }

    private func makeJavaScriptBridgeAlert(message: String?) -> NSAlert {
        let dialog = NSAlert()
        dialog.messageText = javaScriptDialogMessageText(
            message,
            fallback: NSLocalizedString("JavaScript Alert", comment: "")
        )
        dialog.accessoryView = makeJavaScriptDialogAccessory(
            title: localizedJavaScriptBridgeAlertAccessoryTitle(),
            detail: localizedJavaScriptBridgeAlertAccessoryDetail(),
            symbolName: "ellipsis.bubble",
            tintColor: .systemBlue
        )
        dialog.addButton(withTitle: NSLocalizedString("OK", comment: ""))
        return dialog
    }

    private func makeJavaScriptBridgeConfirm(message: String?) -> NSAlert {
        let dialog = NSAlert()
        dialog.messageText = javaScriptDialogMessageText(
            message,
            fallback: NSLocalizedString("Confirm", comment: "")
        )
        dialog.accessoryView = makeJavaScriptDialogAccessory(
            title: localizedJavaScriptBridgeConfirmAccessoryTitle(),
            detail: localizedJavaScriptBridgeConfirmAccessoryDetail(),
            symbolName: "questionmark.circle",
            tintColor: .systemOrange
        )
        dialog.addButton(withTitle: NSLocalizedString("OK", comment: ""))
        dialog.addButton(withTitle: NSLocalizedString("Cancel", comment: ""))
        return dialog
    }

    private func makeJavaScriptPromptDialog(message: String?, defaultValue: String?) -> (alert: NSAlert, input: NSTextField) {
        let input = NSTextField(frame: .zero)
        input.stringValue = defaultValue ?? ""

        let dialog = NSAlert()
        dialog.messageText = javaScriptDialogMessageText(
            message,
            fallback: NSLocalizedString("Input", comment: "")
        )
        dialog.addButton(withTitle: NSLocalizedString("OK", comment: ""))
        dialog.addButton(withTitle: NSLocalizedString("Cancel", comment: ""))
        dialog.accessoryView = makeJavaScriptPromptAccessory(inputField: input)
        return (dialog, input)
    }

    private func makeJavaScriptActionFailureAlert(title: String, message: String) -> NSAlert {
        let alert = NSAlert()
        alert.messageText = title
        alert.informativeText = message
        alert.accessoryView = makeJavaScriptDialogAccessory(
            title: localizedJavaScriptActionFailureAccessoryTitle(),
            detail: localizedJavaScriptActionFailureAccessoryDetail(),
            symbolName: "exclamationmark.triangle",
            tintColor: .systemRed
        )
        alert.addButton(withTitle: NSLocalizedString("OK", comment: ""))
        return alert
    }

    private func runJavaScriptModal(_ alert: NSAlert, initialFirstResponder: NSResponder? = nil) -> NSApplication.ModalResponse {
        keepCurrentFrontmostApplicationAndActivateForJavaScript()
        if let initialFirstResponderView = initialFirstResponder as? NSView {
            alert.window.initialFirstResponder = initialFirstResponderView
            _ = alert.window.makeFirstResponder(initialFirstResponderView)
        }
        let response = alert.runModal()
        restorePreviousFrontmostApplicationForJavaScript()
        return response
    }

    private func javaScriptConfirmationAccepted(response: NSApplication.ModalResponse) -> Bool {
        response == .alertFirstButtonReturn
    }

    private func javaScriptPromptResult(response: NSApplication.ModalResponse, input: NSTextField) -> String? {
        guard response == .alertFirstButtonReturn else { return nil }
        return input.stringValue
    }

    private func resolvedActionScriptURL(for path: String) -> URL? {
        let directURL = URL(fileURLWithPath: path)
        if FileManager.default.fileExists(atPath: directURL.path) {
            return directURL
        }

        var candidates: [URL] = []
        if let relativePath = bundledScriptRelativePath(from: path) {
            if shouldPreferUserActionScript(for: path) {
                candidates.append(userActionScriptsURL().appendingPathComponent(relativePath))
            }
            candidates.append(contentsOf: bundledActionScriptURLs(relativePath: relativePath))
            if !shouldPreferUserActionScript(for: path) {
                candidates.append(userActionScriptsURL().appendingPathComponent(relativePath))
            }
        }

        let resourcePathSeparator = "ClipMenu.app/Contents/Resources/"
        if let suffix = path.components(separatedBy: resourcePathSeparator).last,
           suffix != path {
            candidates.append(contentsOf: [
                Bundle.main.resourceURL?.appendingPathComponent(suffix),
                URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
                    .appendingPathComponent("resource", isDirectory: true)
                    .appendingPathComponent(suffix)
            ].compactMap { $0 })
        }

        return candidates.first { FileManager.default.fileExists(atPath: $0.path) }
    }

    private func userActionScriptsURL() -> URL {
        clipMenuApplicationSupportDirectory()
            .appendingPathComponent("script/action", isDirectory: true)
    }

    private func userActionLibrariesURL() -> URL {
        clipMenuApplicationSupportDirectory()
            .appendingPathComponent("script/lib", isDirectory: true)
    }

    private func bundledActionScriptURLs(relativePath: String) -> [URL] {
        [
            Bundle.main.resourceURL?
                .appendingPathComponent("script/action", isDirectory: true)
                .appendingPathComponent(relativePath),
            URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
                .appendingPathComponent("resource/script/action", isDirectory: true)
                .appendingPathComponent(relativePath)
        ].compactMap { $0 }
    }

    private func shouldPreferUserActionScript(for path: String) -> Bool {
        path.hasPrefix("script/action/") || path.contains("/Application Support/ClipMenu/script/action/")
    }

    private func runOnMainThread<T>(_ work: @escaping () -> T) -> T {
        if Thread.isMainThread {
            return work()
        }

        return DispatchQueue.main.sync(execute: work)
    }

    private func keepCurrentFrontmostApplicationAndActivateForJavaScript() {
        runOnMainThread {
            let currentApplication = NSRunningApplication.current
            if self.previousJavaScriptFrontmostApplication == nil,
               let frontmostApplication = NSWorkspace.shared.frontmostApplication,
               frontmostApplication.processIdentifier != currentApplication.processIdentifier {
                self.previousJavaScriptFrontmostApplication = frontmostApplication
            }
            NSApp.activate(ignoringOtherApps: true)
        }
    }

    private func restorePreviousFrontmostApplicationForJavaScript() {
        runOnMainThread {
            guard let application = self.previousJavaScriptFrontmostApplication else { return }
            self.previousJavaScriptFrontmostApplication = nil
            guard !application.isTerminated else { return }
            application.activate(options: [])
        }
    }

    private func promptForJavaScript(message: String?, defaultValue: String?) -> String? {
#if DEBUG
        if let response = UserDefaults.standard.string(forKey: "debugJavaScriptPromptResponse") {
            debugPasteFlow("promptForJavaScript message=\(message ?? "") default=\(defaultValue ?? "") response=\(response)")
            return response
        }
#endif
        let dialog = makeJavaScriptPromptDialog(message: message, defaultValue: defaultValue)
        let result = runJavaScriptModal(dialog.alert, initialFirstResponder: dialog.input)
        return javaScriptPromptResult(response: result, input: dialog.input)
    }

    private func synthesizePaste() {
        let keyCode = pasteKeyCode()
        debugPasteFlow("synthesizePaste keyCode=\(keyCode)")
        guard ensurePasteEventAccess() else {
            debugPasteFlow("synthesizePaste directPostDenied")
            return
        }
        guard let source = CGEventSource(stateID: .combinedSessionState) else { return }
        let keyDown = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: true)
        let keyUp = CGEvent(keyboardEventSource: source, virtualKey: keyCode, keyDown: false)
        keyDown?.flags = .maskCommand
        keyUp?.flags = .maskCommand
        debugPasteFlow("synthesizePaste directPost")
        keyDown?.post(tap: .cgSessionEventTap)
        keyUp?.post(tap: .cgSessionEventTap)

#if DEBUG
        if UserDefaults.standard.bool(forKey: "debugPasteHelperFallback") {
            if synthesizePasteUsingAppleScriptHelper(keyCode: keyCode) {
                debugPasteFlow("synthesizePaste appleScriptHelperSucceeded")
                return
            }
            if synthesizePasteUsingHelper(keyCode: keyCode) {
                debugPasteFlow("synthesizePaste helperSucceeded")
            }
        }
#endif
    }

#if DEBUG
    private func synthesizePasteUsingAppleScriptHelper(keyCode: CGKeyCode) -> Bool {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
        process.arguments = [
            "-e",
            "tell application \"System Events\" to key code \(keyCode) using command down"
        ]
        guard let terminationStatus = runProcess(process, timeout: 2.0) else {
            debugPasteFlow("synthesizePasteUsingAppleScriptHelper timedOut")
            return false
        }
        debugPasteFlow("synthesizePasteUsingAppleScriptHelper terminationStatus=\(terminationStatus)")
        return terminationStatus == 0
    }

    private func synthesizePasteUsingHelper(keyCode: CGKeyCode) -> Bool {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/swift")
        process.arguments = [
            "-e",
            """
            import Cocoa; import CoreGraphics; let source = CGEventSource(stateID: .combinedSessionState)!; let down = CGEvent(keyboardEventSource: source, virtualKey: \(keyCode), keyDown: true)!; down.flags = .maskCommand; let up = CGEvent(keyboardEventSource: source, virtualKey: \(keyCode), keyDown: false)!; up.flags = .maskCommand; down.post(tap: .cgSessionEventTap); up.post(tap: .cgSessionEventTap)
            """
        ]
        do {
            try process.run()
            process.waitUntilExit()
            let succeeded = process.terminationStatus == 0
            debugPasteFlow("synthesizePasteUsingHelper terminationStatus=\(process.terminationStatus)")
            return succeeded
        } catch {
            debugPasteFlow("synthesizePasteUsingHelper failed error=\(error.localizedDescription)")
            return false
        }
    }

    private func runProcess(_ process: Process, timeout: TimeInterval) -> Int32? {
        do {
            try process.run()
        } catch {
            debugPasteFlow("runProcess failed error=\(error.localizedDescription)")
            return nil
        }

        let deadline = Date().addingTimeInterval(timeout)
        while process.isRunning && Date() < deadline {
            Thread.sleep(forTimeInterval: 0.02)
        }

        if process.isRunning {
            process.terminate()
            process.waitUntilExit()
            return nil
        }

        process.waitUntilExit()
        return process.terminationStatus
    }
#endif

    private func synthesizePasteIfEnabled() {
        guard UserDefaults.standard.bool(forKey: CMPrefInputPasteCommandKey) else { return }
        debugPasteFlow("synthesizePasteIfEnabled begin")
        debugRecordPasteSynthesisRequest(source: "selection")
        synthesizePasteAfterPasteboardWrite()
    }

    private func synthesizePasteForAction() {
        debugPasteFlow("synthesizePasteForAction begin")
        debugRecordPasteSynthesisRequest(source: "action")
        synthesizePasteAfterPasteboardWrite()
    }

    private func synthesizePasteAfterPasteboardWrite() {
        guard ensurePasteAutomationAccess() else {
            debugPasteFlow("synthesizePasteAfterPasteboardWrite permissionDenied")
            return
        }
        let targetBundleIdentifier = restorePasteTargetApplication()
        waitForPasteTargetActivation(bundleIdentifier: targetBundleIdentifier, remainingChecks: 80)
    }

    private func rememberPasteTargetApplication() {
        guard let frontmostApplication = NSWorkspace.shared.frontmostApplication,
              frontmostApplication.processIdentifier != NSRunningApplication.current.processIdentifier else {
            let currentBundleIdentifier = NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "nil"
            let previousBundleIdentifier = previousPasteTargetApplication?.bundleIdentifier ?? "nil"
            debugPasteFlow("rememberPasteTargetApplication skipped current=\(currentBundleIdentifier) previous=\(previousBundleIdentifier)")
            return
        }
        if let previousPasteTargetApplication,
           !previousPasteTargetApplication.isTerminated,
           previousPasteTargetApplication.processIdentifier == frontmostApplication.processIdentifier {
            let currentBundleIdentifier = frontmostApplication.bundleIdentifier ?? "nil"
            debugPasteFlow("rememberPasteTargetApplication unchanged current=\(currentBundleIdentifier)")
            return
        }
        previousPasteTargetApplication = frontmostApplication
        let storedBundleIdentifier = frontmostApplication.bundleIdentifier ?? "nil"
        debugPasteFlow("rememberPasteTargetApplication stored=\(storedBundleIdentifier)")
    }

    private func restorePasteTargetApplication() -> String? {
        guard let application = previousPasteTargetApplication else { return nil }
        previousPasteTargetApplication = nil
        guard !application.isTerminated else { return nil }
        let bundleIdentifier = application.bundleIdentifier ?? "nil"
        debugPasteFlow("restorePasteTargetApplication activating=\(bundleIdentifier)")
        bringApplicationToFront(application)
        return application.bundleIdentifier
    }

    private func bringApplicationToFront(_ application: NSRunningApplication) {
        var serialNumber = ProcessSerialNumber()
        let status = carbonGetProcessForPID(application.processIdentifier, &serialNumber)
        if status == noErr {
            _ = carbonSetFrontProcess(&serialNumber)
        } else {
            debugPasteFlow("bringApplicationToFront fallback status=\(status)")
            application.activate(options: [.activateIgnoringOtherApps])
        }
    }

    private func carbonGetProcessForPID(_ pid: pid_t, _ serialNumber: UnsafeMutablePointer<ProcessSerialNumber>) -> OSStatus {
        typealias Function = @convention(c) (pid_t, UnsafeMutablePointer<ProcessSerialNumber>) -> OSStatus
        guard let symbol = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "GetProcessForPID") else {
            return OSStatus(paramErr)
        }
        let function = unsafeBitCast(symbol, to: Function.self)
        return function(pid, serialNumber)
    }

    private func carbonSetFrontProcess(_ serialNumber: UnsafeMutablePointer<ProcessSerialNumber>) -> OSStatus {
        typealias Function = @convention(c) (UnsafeMutablePointer<ProcessSerialNumber>) -> OSStatus
        guard let symbol = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "SetFrontProcess") else {
            return OSStatus(paramErr)
        }
        let function = unsafeBitCast(symbol, to: Function.self)
        return function(serialNumber)
    }

    private func carbonGetFrontProcess(_ serialNumber: UnsafeMutablePointer<ProcessSerialNumber>) -> OSStatus {
        typealias Function = @convention(c) (UnsafeMutablePointer<ProcessSerialNumber>) -> OSStatus
        guard let symbol = dlsym(UnsafeMutableRawPointer(bitPattern: -2), "GetFrontProcess") else {
            return OSStatus(paramErr)
        }
        let function = unsafeBitCast(symbol, to: Function.self)
        return function(serialNumber)
    }

    private func resetPreviousFrontProcessSerialNumber() {
        previousFrontProcessSerialNumber.highLongOfPSN = 0
        previousFrontProcessSerialNumber.lowLongOfPSN = UInt32(kNoProcess)
    }

    private func hasStoredPreviousFrontProcessSerialNumber() -> Bool {
        previousFrontProcessSerialNumber.lowLongOfPSN != UInt32(kNoProcess)
    }

    private func waitForPasteTargetActivation(bundleIdentifier: String?, remainingChecks: Int) {
        let frontmostBundleIdentifier = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        let modifiersReleased = hotKeyModifiersAreReleased()
        let clipMenuActive = NSRunningApplication.current.isActive
        debugPasteFlow("waitForPasteTargetActivation target=\(bundleIdentifier ?? "nil") frontmost=\(frontmostBundleIdentifier ?? "nil") modifiersReleased=\(modifiersReleased) clipMenuActive=\(clipMenuActive) remaining=\(remainingChecks)")

        guard let bundleIdentifier else {
            guard (!clipMenuActive && modifiersReleased) || remainingChecks <= 0 else {
                pasteDispatchQueue.asyncAfter(deadline: .now() + 0.03) {
                    self.waitForPasteTargetActivation(bundleIdentifier: nil, remainingChecks: remainingChecks - 1)
                }
                return
            }
            pasteDispatchQueue.asyncAfter(deadline: .now() + 0.05) {
                self.synthesizePaste()
            }
            return
        }

        if (frontmostBundleIdentifier == bundleIdentifier && modifiersReleased && !clipMenuActive) || remainingChecks <= 0 {
            pasteDispatchQueue.asyncAfter(deadline: .now() + 0.05) {
                self.synthesizePaste()
            }
            return
        }

        pasteDispatchQueue.asyncAfter(deadline: .now() + 0.03) {
            self.waitForPasteTargetActivation(bundleIdentifier: bundleIdentifier, remainingChecks: remainingChecks - 1)
        }
    }

    private func hotKeyModifiersAreReleased() -> Bool {
        let modifierKeyCodes: [CGKeyCode] = [
            CGKeyCode(kVK_Command),
            CGKeyCode(kVK_RightCommand),
            CGKeyCode(kVK_Control),
            CGKeyCode(kVK_RightControl),
            CGKeyCode(kVK_Option),
            CGKeyCode(kVK_RightOption),
            CGKeyCode(kVK_Shift),
            CGKeyCode(kVK_RightShift)
        ]
        return modifierKeyCodes.allSatisfy { !CGEventSource.keyState(.combinedSessionState, key: $0) }
    }

    private func ensurePasteEventAccess(requestIfMissing: Bool = true) -> Bool {
        if CGPreflightPostEventAccess() {
            debugPasteFlow("ensurePasteEventAccess granted")
            return true
        }
        guard requestIfMissing else {
            debugPasteFlow("ensurePasteEventAccess denied")
            return false
        }
        debugPasteFlow("ensurePasteEventAccess requesting")
        let granted = CGRequestPostEventAccess()
        debugPasteFlow("ensurePasteEventAccess result=\(granted)")
        return granted
    }

    private func ensureAccessibilityAccess(requestIfMissing: Bool = true) -> Bool {
        if AXIsProcessTrusted() {
            debugPasteFlow("ensureAccessibilityAccess granted")
            return true
        }
        guard requestIfMissing else {
            debugPasteFlow("ensureAccessibilityAccess denied")
            return false
        }

        debugPasteFlow("ensureAccessibilityAccess requesting")
        let options = [kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String: true] as CFDictionary
        let granted = AXIsProcessTrustedWithOptions(options)
        debugPasteFlow("ensureAccessibilityAccess result=\(granted)")
        return granted
    }

    private func currentPasteAutomationAccessState() -> PasteAutomationAccessState {
        PasteAutomationAccessState(
            accessibilityGranted: AXIsProcessTrusted(),
            postEventGranted: CGPreflightPostEventAccess()
        )
    }

    private func ensurePasteAutomationAccess() -> Bool {
        let accessState = currentPasteAutomationAccessState()
        debugPasteFlow("ensurePasteAutomationAccess accessibility=\(accessState.accessibilityGranted) postEvent=\(accessState.postEventGranted)")

        if !accessState.isFullyGranted {
            presentPastePermissionAlertIfNeeded(accessState: accessState)
        }

        return accessState.isFullyGranted
    }

    private func presentPastePermissionAlertIfNeeded(accessState: PasteAutomationAccessState) {
        guard !hasShownPastePermissionAlert else { return }
        hasShownPastePermissionAlert = true

        runOnMainThread {
            let appName = legacyApplicationName()
            let alert = self.makePastePermissionPrompt(appName: appName, accessState: accessState)

            NSApp.activate(ignoringOtherApps: true)
            let response = alert.runModal()
            guard self.pastePermissionPromptOpenSettingsRequested(response: response),
                  let url = self.pastePermissionSettingsURL() else {
                return
            }
            NSWorkspace.shared.open(url)
        }
    }

    private func debugPasteFlow(_ message: String) {
#if DEBUG
        guard UserDefaults.standard.bool(forKey: CMDebugPasteFlowKey) else { return }
        let line = "[ClipMenu paste] \(message)\n"
        let url = URL(fileURLWithPath: "/tmp/clipmenu-paste-debug.log")
        let data = Data(line.utf8)
        if FileManager.default.fileExists(atPath: url.path),
           let handle = try? FileHandle(forWritingTo: url) {
            defer { try? handle.close() }
            _ = try? handle.seekToEnd()
            try? handle.write(contentsOf: data)
        } else {
            try? data.write(to: url, options: .atomic)
        }
#endif
    }

    private func debugRecordPasteSynthesisRequest(source: String) {
#if DEBUG
        debugPasteSynthesisRequestCount += 1
        debugLastPasteSynthesisSource = source
#endif
    }

    private func pasteKeyCode() -> CGKeyCode {
        if let cachedPasteKeyCode {
            return cachedPasteKeyCode
        }

        for keyCode in CGKeyCode(0)..<CGKeyCode(128) where stringForKeyCode(keyCode) == "V" {
            cachedPasteKeyCode = keyCode
            return keyCode
        }

        let fallback = CGKeyCode(kVK_ANSI_V)
        cachedPasteKeyCode = fallback
        return fallback
    }

    private func stringForKeyCode(_ keyCode: CGKeyCode) -> String? {
        guard let inputSource = TISCopyCurrentKeyboardLayoutInputSource()?.takeRetainedValue(),
              let layoutData = TISGetInputSourceProperty(inputSource, kTISPropertyUnicodeKeyLayoutData) else {
            return nil
        }

        let data = unsafeBitCast(layoutData, to: CFData.self)
        guard let keyboardLayout = UnsafeRawPointer(CFDataGetBytePtr(data))?.assumingMemoryBound(to: UCKeyboardLayout.self) else {
            return nil
        }

        var keysDown = UInt32(0)
        var chars = [UniChar](repeating: 0, count: 4)
        var realLength = 0
        let status = UCKeyTranslate(
            keyboardLayout,
            UInt16(keyCode),
            UInt16(kUCKeyActionDisplay),
            0,
            UInt32(LMGetKbdType()),
            OptionBits(kUCKeyTranslateNoDeadKeysBit),
            &keysDown,
            chars.count,
            &realLength,
            &chars
        )

        guard status == noErr, realLength > 0 else { return nil }
        return String(utf16CodeUnits: chars, count: realLength).uppercased()
    }

