    @discardableResult
    private func performClearHistory(
        confirmationResolver: (() -> ClearHistoryAlertResolution)? = nil
    ) -> Bool {
        if UserDefaults.standard.bool(forKey: CMPrefShowAlertBeforeClearHistoryKey) {
            let resolution: ClearHistoryAlertResolution
            if let confirmationResolver {
                resolution = confirmationResolver()
            } else {
                let alert = makeClearHistoryPrompt()
                NSApp.activate(ignoringOtherApps: true)

                let result = alert.runModal()
                resolution = ClearHistoryAlertResolution(
                    confirmed: result == .alertFirstButtonReturn,
                    suppressFutureAlerts: alert.suppressionButton?.state == .on
                )
            }

            if resolution.suppressFutureAlerts {
                UserDefaults.standard.set(false, forKey: CMPrefShowAlertBeforeClearHistoryKey)
            }
            guard resolution.confirmed else { return false }
        }

        clipsStore.clear()
        rebuildMenu()
        return true
    }

