    @objc private func restorePreviousFrontProcess() -> Bool {
        guard hasStoredPreviousFrontProcessSerialNumber() else {
            return true
        }
        let osError = carbonSetFrontProcess(&previousFrontProcessSerialNumber)
        resetPreviousFrontProcessSerialNumber()
        return osError == noErr
    }

    private func rebuildOpenRecentMenu(_ menu: NSMenu) {
        menu.removeAllItems()
        let recentURLs = NSDocumentController.shared.recentDocumentURLs
        for recentURL in recentURLs {
            let item = NSMenuItem(title: recentURL.lastPathComponent, action: #selector(openRecentSnippetDocument(_:)), keyEquivalent: "")
            item.target = self
            item.representedObject = recentURL
            item.toolTip = recentURL.path
            menu.addItem(item)
        }
        if !recentURLs.isEmpty {
            menu.addItem(.separator())
        }
        let clearRecentItem = NSMenuItem(title: NSLocalizedString("Clear Menu", comment: ""), action: #selector(clearRecentSnippetDocuments(_:)), keyEquivalent: "")
        clearRecentItem.target = self
        clearRecentItem.isEnabled = !recentURLs.isEmpty
        menu.addItem(clearRecentItem)
    }

    private func exportHistoryAsSingleFile() {
        let panel = NSSavePanel()
        panel.canCreateDirectories = true
        panel.allowedContentTypes = [.plainText]
        panel.nameFieldStringValue = "clipboard_history.txt"
        beginHistoryExportPanel(panel) { [weak self] response in
            guard response == .OK, let url = panel.url else { return }
            self?.finishExport {
                try self?.clipsStore.exportTextClipsAsSingleFile(to: url)
            }
        }
    }

    private func exportHistoryAsMultipleFiles() {
        let panel = NSOpenPanel()
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.canCreateDirectories = true
        panel.prompt = NSLocalizedString("Select", comment: "")
        beginHistoryExportPanel(panel) { [weak self] response in
            guard response == .OK, let url = panel.url else { return }
            self?.finishExport {
                try self?.clipsStore.exportTextClipsAsMultipleFiles(to: url)
            }
        }
    }

    private func beginHistoryExportPanel(_ panel: NSSavePanel, completion: @escaping (NSApplication.ModalResponse) -> Void) {
        if let preferencesWindow = SwiftUIPreferencesWindowController.shared.window,
           preferencesWindow.isVisible {
            panel.beginSheetModal(for: preferencesWindow, completionHandler: completion)
        } else {
            panel.begin(completionHandler: completion)
        }
    }

    private func finishExport(_ operation: () throws -> Void) {
        do {
            try operation()
        } catch {
            NSApp.activate(ignoringOtherApps: true)
            let alert = makeHistoryExportFailureAlert()
            CMShowAlert(
                alert,
                sheetFor: NSApp.keyWindow ?? NSApp.mainWindow ?? SwiftUIPreferencesWindowController.shared.window
            )
        }
    }

