    @objc private func popUpActionMenu(_ sender: Any?) {
        let nodes = loadRuntimeActionNodes()
        guard !nodes.isEmpty else { return }

        let popupTarget: ActionTarget?
        if let item = sender as? NSMenuItem,
           let snippet = item.representedObject as? SnippetActionReference {
            popupTarget = .snippet(snippet)
        } else if let item = sender as? NSMenuItem,
                  let clipID = (item.representedObject as? String).flatMap(UUID.init(uuidString:)) {
            popupTarget = .clip(clipID)
        } else if let existingTarget = actionTarget {
            popupTarget = existingTarget
        } else {
            popupTarget = nil
        }

        guard let popupTarget else { return }

        actionTarget = popupTarget
        defer { actionTarget = nil }

        if UserDefaults.standard.bool(forKey: CMPrefInvokeActionImmediatelyKey),
           nodes.count == 1,
           let action = nodes.first?.action {
            invokeAction(action, target: popupTarget)
            return
        }

        let menu = makeActionMenu()
        guard menu.numberOfItems > 0 else { return }
        popUpMenuAtMouseLocation(menu, style: .action)
    }

    @objc private func keepCurrentFrontProcessAndActivate() {
        resetPreviousFrontProcessSerialNumber()
        let osError = carbonGetFrontProcess(&previousFrontProcessSerialNumber)
        if osError != noErr {
            resetPreviousFrontProcessSerialNumber()
        }
        NSApp.activate(ignoringOtherApps: true)
    }

