    @objc(print:) private func `print`(_ sender: Any?) {
        guard let window = printableWindow(),
              let contentView = window.contentView else {
            NSSound.beep()
            return
        }
        let printOperation = NSPrintOperation(view: contentView)
        printOperation.run()
    }

    private func printableWindow() -> NSWindow? {
        guard let snippetWindow = snippetEditorController?.window,
              snippetWindow.isVisible,
              !snippetWindow.isMiniaturized else {
            return nil
        }
        return snippetWindow
    }

    private func closableWindow() -> NSWindow? {
        let candidateWindows = [NSApp.keyWindow, NSApp.mainWindow].compactMap { $0 }
        for candidate in candidateWindows {
            if candidate == snippetEditorController?.window || candidate == SwiftUIPreferencesWindowController.shared.window,
               candidate.isVisible,
               !candidate.isMiniaturized {
                return candidate
            }
        }

        if let snippetWindow = snippetEditorController?.window,
           snippetWindow.isVisible,
           !snippetWindow.isMiniaturized {
            return snippetWindow
        }

        if let preferencesWindow = SwiftUIPreferencesWindowController.shared.window,
           preferencesWindow.isVisible,
           !preferencesWindow.isMiniaturized {
            return preferencesWindow
        }

        return nil
    }

}

final class ClipStore {
    private(set) var clips: [ClipItem] = []
    private var hasUnsavedChanges = false

    var debugHasUnsavedChanges: Bool {
        hasUnsavedChanges
    }

    var orderedClips: [ClipItem] {
        let defaults = UserDefaults.standard
        let sortByLastUsed = CMNormalizedLegacyReorderClipsAfterPastingValue(
            defaults.object(forKey: CMPrefReorderClipsAfterPasting)
        )
        if sortByLastUsed != defaults.bool(forKey: CMPrefReorderClipsAfterPasting)
            || !(defaults.object(forKey: CMPrefReorderClipsAfterPasting) is Bool) {
            defaults.set(sortByLastUsed, forKey: CMPrefReorderClipsAfterPasting)
        }

        let keyPath: KeyPath<ClipItem, Date> = sortByLastUsed ? \.lastUsedAt : \.createdAt
        return clips.sorted {
            let left = $0[keyPath: keyPath]
            let right = $1[keyPath: keyPath]
            if left == right {
                return $0.createdAt > $1.createdAt
            }
            return left > right
        }
    }

    var hasTextClips: Bool {
        clips.contains { !$0.text.isEmpty }
    }

    private var supportDirectory: URL {
        clipMenuApplicationSupportDirectory()
    }

    private var fileURL: URL {
        supportDirectory.appendingPathComponent("clips.data")
    }

    private var jsonFileURL: URL {
        supportDirectory.appendingPathComponent("clips.json")
    }

    func load() {
        if shouldPreferJSONStore(),
           let jsonClips = loadJSONClips(from: jsonFileURL) {
            clips = jsonClips
            trim()
            save()
            return
        }

        if let swiftClips = loadJSONClips(from: fileURL) {
            clips = swiftClips
            trim()
            hasUnsavedChanges = false
            return
        }

        if let legacyClips = loadLegacyClips() {
            clips = legacyClips
            trim()
            save()
            return
        }

        if let jsonClips = loadJSONClips(from: jsonFileURL) {
            clips = jsonClips
            trim()
            save()
            return
        }

        clips = []
        hasUnsavedChanges = false
    }

    @discardableResult
    func save() -> Bool {
        trim()
        guard let data = try? JSONEncoder().encode(clips) else { return false }
        do {
            try saveLegacyCompatibleArchive(to: fileURL)
            try? data.write(to: jsonFileURL, options: .atomic)
            hasUnsavedChanges = false
            return true
        } catch {
            NSLog("Could not save clipboard history: \(error.localizedDescription)")
            return false
        }
    }

    @discardableResult
    func saveIfNeeded() -> Bool {
        guard hasUnsavedChanges else { return true }
        return save()
    }

    func removeSavedHistory() {
        try? FileManager.default.removeItem(at: fileURL)
        try? FileManager.default.removeItem(at: jsonFileURL)
        hasUnsavedChanges = false
    }

    func add(_ clip: ClipItem) {
        if let index = clips.firstIndex(where: { $0.duplicateKey == clip.duplicateKey }) {
            clips[index].lastUsedAt = Date()
        } else {
            clips.append(clip)
        }
        trim()
        hasUnsavedChanges = true
    }

    func promote(_ id: UUID) {
        guard let index = clips.firstIndex(where: { $0.id == id }) else { return }
        clips[index].lastUsedAt = Date()
        hasUnsavedChanges = true
    }

    func clip(with uuidString: String) -> ClipItem? {
        guard let id = UUID(uuidString: uuidString) else { return nil }
        return clips.first { $0.id == id }
    }

    func clear() {
        clips.removeAll()
        hasUnsavedChanges = true
    }

    func remove(_ id: UUID) {
        clips.removeAll { $0.id == id }
        hasUnsavedChanges = true
    }

    func trimToCurrentHistoryLimit() {
        let oldCount = clips.count
        trim()
        if clips.count != oldCount {
            hasUnsavedChanges = true
        }
    }

    func exportTextClipsAsSingleFile(to url: URL) throws {
        guard !clips.isEmpty else { return }
        if FileManager.default.fileExists(atPath: url.path) {
            try FileManager.default.removeItem(at: url)
        }

        let separator = exportSeparator()
        let textClips = orderedClips.filter { $0.hasStringPasteboardType }
        guard !textClips.isEmpty else { return }

        let contents = textClips.map { $0.text + separator }.joined()
        try contents.write(to: url, atomically: true, encoding: .utf8)
    }

    func exportTextClipsAsMultipleFiles(to directoryURL: URL) throws {
        guard !clips.isEmpty else { return }

        for (index, clip) in orderedClips.enumerated() where clip.hasStringPasteboardType {
            let fileURL = directoryURL.appendingPathComponent("\(index + 1).txt")
            try clip.text.write(to: fileURL, atomically: true, encoding: .utf8)
        }
    }

    private func exportSeparator() -> String {
        let defaults = UserDefaults.standard
        let storedTag = defaults.integer(forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        let normalizedTag = CMNormalizedLegacyExportSeparatorTag(storedTag)
        if normalizedTag != storedTag {
            defaults.set(normalizedTag, forKey: CMPrefTagOfSeparatorForExportHistoryToFileKey)
        }

        switch normalizedTag {
        case 0:
            return ""
        case 1:
            return "\n"
        case 2:
            return "\r\n"
        case 3:
            return "\r"
        case 4:
            return "\t"
        case 5:
            return " "
        default:
            return "\n"
        }
    }

    private func trim() {
        let defaults = UserDefaults.standard
        let storedLimit = defaults.integer(forKey: CMPrefMaxHistorySizeKey)
        let limit = CMNormalizedLegacyMaxHistorySize(storedLimit)
        if limit != storedLimit {
            defaults.set(limit, forKey: CMPrefMaxHistorySizeKey)
        }
        if clips.count > limit {
            clips = Array(orderedClips.prefix(limit))
        }
    }

    private func loadJSONClips(from url: URL) -> [ClipItem]? {
        guard let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode([ClipItem].self, from: data) else {
            return nil
        }
        return decoded
    }

    private func shouldPreferJSONStore() -> Bool {
        guard FileManager.default.fileExists(atPath: jsonFileURL.path) else { return false }
        guard FileManager.default.fileExists(atPath: fileURL.path) else { return true }
        guard loadJSONClips(from: fileURL) == nil,
              let jsonDate = modificationDate(for: jsonFileURL),
              let dataDate = modificationDate(for: fileURL) else {
            return false
        }
        return jsonDate > dataDate
    }

    private func modificationDate(for url: URL) -> Date? {
        (try? FileManager.default.attributesOfItem(atPath: url.path)[.modificationDate]) as? Date
    }

    private func saveLegacyCompatibleArchive(to url: URL) throws {
        let archivedClips = orderedClips.map { ArchivedClip(clip: $0) }
        let data = try NSKeyedArchiver.archivedData(withRootObject: archivedClips, requiringSecureCoding: false)
        try data.write(to: url, options: .atomic)
    }

    private func loadLegacyClips() -> [ClipItem]? {
        guard let data = try? Data(contentsOf: fileURL) else { return nil }

        do {
            let unarchiver = try NSKeyedUnarchiver(forReadingFrom: data)
            unarchiver.requiresSecureCoding = false
            unarchiver.setClass(LegacyArchivedClip.self, forClassName: "Clip")
            unarchiver.setClass(LegacyArchivedClip.self, forClassName: "ClipMenu.Clip")
            defer { unarchiver.finishDecoding() }

            let decodedRoot = unarchiver.decodeObject(forKey: NSKeyedArchiveRootObjectKey)
            if let legacyClips = decodedRoot as? [LegacyArchivedClip] {
                return legacyClips.map(\.clipItem)
            }

            if let legacyClips = decodedRoot as? NSArray {
                return legacyClips.compactMap { ($0 as? LegacyArchivedClip)?.clipItem }
            }

            if let legacySet = decodedRoot as? Set<LegacyArchivedClip> {
                return legacySet
                    .map(\.clipItem)
                    .sorted { $0.createdAt > $1.createdAt }
            }

            if let legacySet = decodedRoot as? NSSet {
                return legacySet
                    .compactMap { ($0 as? LegacyArchivedClip)?.clipItem }
                    .sorted { $0.createdAt > $1.createdAt }
            }
        } catch {
            NSLog("ClipMenu failed to migrate legacy clips.data: \(error.localizedDescription)")
        }

        return nil
    }
}
